use std::iter::once;
use std::iter::repeat;
use std::iter::successors;
use std::ops::Range;
 
fn main() {
    let primes = generate_primes(1_000_000).collect::<Vec<_>>();
    for d in &[
        &[2],
        &[1],
        &[2, 2],
        &[2, 4],
        &[4, 2],
        &[6, 4, 2],
    ] {
        let mut first = None;
        let mut last = None;
        let mut count = 0;
        for grp in find_difference_groups(d, &primes) {
            if first.is_none() {
                first = Some(grp);
            }
            last = Some(grp);
            count += 1;
        }
        println!("{:?}, {:?}, {}", first.unwrap(), last.unwrap(), count);
    }
}
 
fn find_difference_groups(diffs: &[usize], primes: &[usize]) -> impl Iterator<Item = Vec<usize>> {
    successors(Some(diffs.len()), |&pi| {
        if pi < primes.len() {
            Some(pi + 1)
        } else {
            None
        }
    })
   .filter(move |&pi| {
        Range::new(0, diffs.len())
           .all(|di| primes[pi - diffs.len() + di + 1] - primes[pi - diffs.len() + di] == diffs[di])
    })
   .map(move |pi| {
        Range::new(pi - diffs.len(), diffs.len() + 1)
           .map(|i| primes[i])
           .collect()
    })
}
 
fn generate_primes(lmt: usize) -> impl Iterator<Item = usize> {
    let mut comps = vec![false; lmt + 1];
    comps[0] = true;
    comps[1] = true;
    let mut primes = vec![2, 3];
    for j in (4..=lmt).step_by(2) {
        comps[j] = true;
    }
    for j in (9..=lmt).step_by(6) {
        comps[j] = true;
    }
    let mut i = 5;
    let mut d = 4;
    let mut rt = (lmt as f64).sqrt() as usize;
    while i <= rt {
        if!comps[i] {
            primes.push(i);
            for j in (i * i..=lmt).step_by(i << 1) {
                comps[j] = true;
            }
        }
        i += d;
        d = 6 - d;
    }
    while i <= lmt {
        if!comps[i] {
            primes.push(i);
        }
        i += d;
        d = 6 - d;
    }
    primes.into_iter()
}

