use std::io;
use std::io::Write;
 
const TRUE: bool = true;
const FALSE: bool = false;
const MAX: i32 = 120;
 
fn is_prime(n: i32) -> bool {
    let mut d = 5;
    if n < 2 {
        return FALSE;
    }
    if n % 2 == 0 {
        return n == 2;
    }
    if n % 3 == 0 {
        return n == 3;
    }
    while d * d <= n {
        if n % d == 0 {
            return FALSE;
        }
        d += 2;
        if n % d == 0 {
            return FALSE;
        }
        d += 4;
    }
    TRUE
}
 
fn count_prime_factors(n: i32) -> i32 {
    let mut count = 0;
    let mut f = 2;
    if n == 1 {
        return 0;
    }
    if is_prime(n) {
        return 1;
    }
    loop {
        if n % f == 0 {
            count += 1;
            n /= f;
            if n == 1 {
                return count;
            }
            if is_prime(n) {
                f = n;
            }
        } else if f >= 3 {
            f += 2;
        } else {
            f = 3;
        }
    }
}
 
fn main() {
    let mut count = 0;
    print!("The attractive numbers up to and including {} are:\n", MAX);
    for i in 1..=MAX {
        let n = count_prime_factors(i);
        if is_prime(n) {
            print!("{:4}", i);
            count += 1;
            if count % 20 == 0 {
                print!("\n");
            }
        }
    }
    print!("\n");
    io::stdout().flush().unwrap();
}

