fn rand_bsd(seed: i32) -> impl Iterator<Item = i32> {
    let mask = (1 << 31) - 1;
    (0..).scan(seed, move |state, _| {
        *state = (*state * 1_103_515_245 + 12_345) & mask;
        Some(*state)
    })
}
 
fn rand_ms(seed: i32) -> impl Iterator<Item = i32> {
    let mask = (1 << 31) - 1;
    (0..).scan(seed, move |state, _| {
        *state = (*state * 214_013 + 2_531_011) & mask;
        Some(*state >> 16)
    })
}

