fn hq9plus(code: &str) {
    let mut acc = 0;
    let mut sb = String::new();
    for c in code.chars() {
        sb.push_str(
            match c {
                'h' | 'H' => "Hello, world!\n",
                'q' | 'Q' => code + "\n",
                '9' => {
                    let mut sb2 = String::new();
                    for i in (1..100).rev() {
                        let s = if i > 1 { "s" } else { "" };
                        sb2.push_str(&format!("{} bottle{} of beer on the wall\n", i, s));
                        sb2.push_str(&format!("{} bottle{} of beer\n", i, s));
                        sb2.push_str("Take one down, pass it around\n");
                    }
                    sb2.push_str("No more bottles of beer on the wall!\n");
                    sb2.as_str()
                }
                '+' => { acc += 1; "" }  // yeah, it's weird!
                _ => panic!("Code contains illegal operation '{}'", c),
            }
        );
    }
    println!("{}", sb);
}
 
