fn sieve(limit: usize) -> Vec<usize> {
    let mut c = vec![false; limit + 1];
    let mut primes = Vec::new();
    let mut p = 3;
    while p * p <= limit {
        let mut i = p * p;
        while i <= limit {
            c[i] = true;
            i += 2 * p;
        }
        p += 2;
        while c[p] {
            p += 2;
        }
    }
    for i in 3..limit {
        if!c[i] {
            primes.push(i);
        }
    }
    primes
}
 
fn find_period(n: usize) -> usize {
    let mut r = 1;
    for _ in 1..n {
        r = (10 * r) % n;
    }
    let mut rr = r;
    let mut period = 0;
    while r!= rr {
        r = (10 * r) % n;
        period += 1;
    }
    period
}
 
fn main() {
    let primes = sieve(64000);
    let mut long_primes = Vec::new();
    for prime in &primes {
        if find_period(*prime) == *prime - 1 {
            long_primes.push(*prime);
        }
    }
    let numbers = [500, 1000, 2000, 4000, 8000, 16000, 32000, 64000];
    let mut count = 0;
    let mut index = 0;
    let mut totals = vec![0; numbers.len()];
    for long_prime in &long_primes {
        if *long_prime > numbers[index] {
            totals[index] = count;
            index += 1;
        }
        count += 1;
    }
    totals[totals.len() - 1] = count;
    println!("The long primes up to 500 are:");
    println!("{}", long_primes[..totals[0]].iter().map(|x| x.to_string()).collect::<Vec<String>>().join(","));
    println!("\nThe number of long primes up to:");
    for (i, total) in totals.iter().enumerate() {
        println!("  {:>5} is {}", numbers[i], total);
    }
}

fn Y<F>(f: F) -> F
    where F: Fn(F) -> F
{
    let g = f(move |h| {
        let g = f(h(h));
        move |args| g(args)
    });
    g
}
 
fn fac(f: fn(u32) -> u32) -> fn(u32) -> u32 {
    move |n| if n > 1 { n * f(n - 1) } else { 1 }
}
 
fn fib(f: fn(u32) -> u32) -> fn(u32) -> u32 {
    move |n| if n > 1 { f(n - 1) + f(n - 2) } else { n }
}
 
fn main() {
    let fac = Y(fac);
    let fib = Y(fib);
    println!("{}", fac(5));
    println!("{}", fib(5));
}

// The flt package (http://flt.rubyforge.org/) is useful for high-precision floating-point math.
// It lets us control 'context' of numbers, individually or collectively -- including precision
// (which adjusts the context's value of epsilon accordingly).

use flt::flt::BinNum;
use flt::flt::BinNumContext;

fn main() {
    let mut context = BinNumContext::new();
    context.precision = 512;
    let a = BinNum::new(1, &context);
    let g = BinNum::new(1, &context) / BinNum::new(2, &context).sqrt();
    println!("{}", agm(a, g));
}

fn agm(a: BinNum, g: BinNum) -> BinNum {
    let mut new_a = a;
    let mut new_g = g;
    while new_a - new_g > new_a.context().epsilon {
        let old_g = new_g;
        new_g = (new_a * new_g).sqrt();
        new_a = (old_g + new_a) * 0.5;
    }
    new_g
}

fn van_eck() -> impl Iterator<Item = usize> {
    let mut n = 0;
    let mut seen = HashMap::new();
    let mut val = 0;
    std::iter::from_fn(move || {
        let ret = Some(val);
        let last = { val };
        val = n - seen.get(&val).unwrap_or(&n);
        seen.insert(last, n);
        n += 1;
        ret
    })
}

fn main() {
    println!("Van Eck: first 10 terms: {:?}", &van_eck().take(10).collect::<Vec<_>>());
    println!("Van Eck: terms 991 - 1000: {:?}", &van_eck().skip(990).take(10).collect::<Vec<_>>());
}

fn is_pangram(test: &str) -> bool {
    for a in 'A'..='Z' {
        if test.find(a).is_none() && test.find(a.to_lowercase().next().unwrap()).is_none() {
            return false;
        }
    }
    true
}

fn main() {
    println!("{}", is_pangram("the quick brown fox jumps over the lazy dog")); //true
    println!("{}", is_pangram("the quick brown fox jumped over the lazy dog")); //false, no s
    println!("{}", is_pangram("ABCDEFGHIJKLMNOPQRSTUVWXYZ")); //true
    println!("{}", is_pangram("ABCDEFGHIJKLMNOPQSTUVWXYZ")); //false, no r
    println!("{}", is_pangram("ABCDEFGHIJKL.NOPQRSTUVWXYZ")); //false, no m
    println!("{}", is_pangram("ABC.D.E.FGHI*J/KL-M+NO*PQ R\nSTUVWXYZ")); //true
    println!("{}", is_pangram("")); //false
}

