use rand::seq::SliceRandom;
use rand::thread_rng;

fn gen(n: usize) -> String {
    let mut txt = vec!['['; n];
    txt.extend(vec![']'; n]);
    txt.shuffle(&mut thread_rng());
    txt.into_iter().collect()
}

fn balanced(txt: &str) -> bool {
    let mut braced = 0;
    for ch in txt.chars() {
        if ch == '[' {
            braced += 1;
        }
        if ch == ']' {
            braced -= 1;
            if braced < 0 {
                return false;
            }
        }
    }
    braced == 0
}

fn main() {
    for n in 0..10 {
        let txt = gen(n);
        println!("{:?}\tis{}", txt, if balanced(&txt) { "" } else { " not" });
    }
}

fn q(s: Vec<&str>) -> String {
    match s.len() {
        0 => "{}".to_string(),
        1 => format!("{{{}}}", s[0]),
        2 => format!("{{{} and {}}}", s[0], s[1]),
        _ => format!(
            "{{{}, {} and {}}}",
            s[..s.len() - 1].join(", "),
            s[s.len() - 1]
        ),
    }
}
 
fn main() {
    println!("{}", q(vec![]));
    println!("{}", q(vec!["ABC"]));
    println!("{}", q(vec!["ABC", "DEF"]));
    println!("{}", q(vec!["ABC", "DEF", "G", "H"]));
}

