use std::fmt::Write;
 
fn lookandsay(number: &str) -> String {
    let mut result = String::new();
 
    let mut repeat = number.chars().next().unwrap();
    let mut number = number.chars().skip(1).chain(Some(' '));
    let mut times = 1;
 
    for actual in number {
        if actual!= repeat {
            write!(&mut result, "{}{}", times, repeat).unwrap();
            times = 1;
            repeat = actual;
        } else {
            times += 1;
        }
    }
    result
}
 
fn main() {
    let mut num = "1".to_string();
 
    for i in 1..11 {
        println!("{}", num);
        num = lookandsay(&num);
    }
}

