use std::fmt;
 
#[derive(Debug)]
struct CfTerm {
    a: i32,
    b: i32,
}
 
// follows subscript convention of mathworld and WP where there is no b(0).
// cf[0].b is unused in this representation.
type Cf = Vec<CfTerm>;
 
fn cf_sqrt2(n_terms: usize) -> Cf {
    let mut f = Vec::with_capacity(n_terms);
    for _ in 0..n_terms {
        f.push(CfTerm { a: 2, b: 1 });
    }
    f[0].a = 1;
    f
}
 
fn cf_nap(n_terms: usize) -> Cf {
    let mut f = Vec::with_capacity(n_terms);
    for n in 0..n_terms {
        f.push(CfTerm { a: n as i32, b: (n - 1) as i32 });
    }
    f[0].a = 2;
    f[1].b = 1;
    f
}
 
fn cf_pi(n_terms: usize) -> Cf {
    let mut f = Vec::with_capacity(n_terms);
    for n in 0..n_terms {
        let g = 2 * n - 1;
        f.push(CfTerm { a: 6, b: g * g });
    }
    f[0].a = 3;
    f
}
 
impl Cf {
    fn real(&self) -> f64 {
        let mut r = 0.0;
        for n in (1..self.len()).rev() {
            r = (self[n].b as f64) / (self[n].a as f64 + r);
        }
        r + self[0].a as f64
    }
}
 
fn main() {
    println!("sqrt2: {}", cf_sqrt2(20).real());
    println!("nap:   {}", cf_nap(20).real());
    println!("pi:    {}", cf_pi(20).real());
}

fn isqrt( x: i64 ) -> i64 {
    let mut q = 1;
    while q <= x {
        q *= 4;
    }
    let mut z = x;
    let mut r = 0;
    while q > 1 {
        q /= 4;
        let t = z - r - q;
        let r = r / 2;
        if t >= 0 {
            z = t;
            r = r + q;
        }
    }
    r
}
 
fn main() {
    for n in 0..66 {
        print!("{} ", isqrt(n as i64));
    }
    println!("");
    for n in (1..204).step_by(2) {
        println!("{:114,} = isqrt( 7^{:3} )", isqrt(7i64.pow(n)), n);
    }
}

use rand::Rng;
use std::time::SystemTime;

fn s_of_n_creator(n: usize) -> impl FnMut(u8) -> Vec<u8> {
    let mut s = Vec::with_capacity(n);
    let mut m = n;
    move |item| {
        if s.len() < n {
            s.push(item);
        } else {
            m += 1;
            if rand::thread_rng().gen_range(0, m) < n {
                s[rand::thread_rng().gen_range(0, n)] = item;
            }
        }
        s.clone()
    }
}

fn main() {
    let mut freq = [0; 10];
    let mut rng = rand::thread_rng();
    for _ in 0..100_000 {
        let mut s_of_n = s_of_n_creator(3);
        for d in b'0'..b'9' {
            s_of_n(d);
        }
        for d in s_of_n(b'9') {
            freq[(d - b'0') as usize] += 1;
        }
    }
    println!("{:?}", freq);
}

use rand::Rng;
 
fn main() {
    let mut a = rand::thread_rng().gen_int_range(0, 20);
    println!("{:?}", a);
    println!("{:?}", even(&a));
    println!("{:?}", a);
    reduce_to_even(&mut a);
    println!("{:?}", a);
    println!("a len: {}, cap: {}", a.len(), a.capacity());
}
 
fn even(a: &[i32]) -> Vec<i32> {
    let mut r = Vec::new();
    for e in a {
        if e % 2 == 0 {
            r.push(*e);
        }
    }
    r
}
 
fn reduce_to_even(a: &mut Vec<i32>) {
    let mut last = 0;
    for e in a {
        if e % 2 == 0 {
            a[last] = *e;
            last += 1;
        }
    }
    a.truncate(last);
}

/*
 * rust bf interpreter
 * by 
 */
 
fn execute(code: &str) -> bool {
    let mut mem = [0; 30000];
    let mut sp = 10000;
    let mut opcode = code.to_string();
    let oplen = opcode.len();
    let mut ip = 0;
    let mut loopstack = Vec::new();
    let mut output = String::new();
 
    while ip < oplen {
        match opcode.chars().nth(ip).unwrap() {
            '+' => mem[sp] += 1,
            '-' => mem[sp] -= 1,
            '>' => sp += 1,
            '<' => sp -= 1,
            '.' => {
                if mem[sp]!= 10 && mem[sp]!= 13 {
                    output.push(mem[sp] as u8 as char);
                } else {
                    println!("{}", output);
                    output = String::new();
                }
            }
            ',' => {
                let mut s = String::new();
                std::io::stdin().read_line(&mut s).unwrap();
                if s.is_empty() {
                    return false;
                }
                mem[sp] = s.chars().nth(0).unwrap() as u8 as i32;
            }
            '[' => {
                if mem[sp]!= 0 {
                    loopstack.push(ip);
                } else {
                    let mut k = ip;
                    let mut j = 0;
                    while k < oplen {
                        match opcode.chars().nth(k).unwrap() {
                            '[' => j += 1,
                            ']' => j -= 1,
                            _ => {}
                        }
                        if j == 0 {
                            break;
                        }
                        k += 1;
                    }
                    if j == 0 {
                        ip = k;
                    } else {
                        println!("Unmatched loop");
                        return false;
                    }
                }
            }
            ']' => {
                ip = loopstack.pop().unwrap() - 1;
            }
            _ => {}
        }
        ip += 1;
    }
    true
}
 
fn main() {
    execute("++++++++++[>+>+++>++++>+++++++ >++++++++>+++++++++>++++++++++>+++++++++
    ++>++++++++++++<<<<<<<<<-]>>>>+.>>>>+..<.<++++++++.>>>+.<<+.<<<<++++.<+
    +.>>>+++++++.>>>.+++.<+++++++.--------.<<<<<+.<+++.---.");
}

