fn in_carpet(x: f64, y: f64) -> bool {
    loop {
        if x == 0.0 || y == 0.0 {
            return true;
        } else if x.rem_euclid(3.0) == 1.0 && y.rem_euclid(3.0) == 1.0 {
            return false;
        }
        x /= 3.0;
        y /= 3.0;
    }
}
 
fn carpet(n: u32) {
    for i in 0..3u32.pow(n) {
        for j in 0..3u32.pow(n) {
            if in_carpet(i as f64, j as f64) {
                print!("*");
            } else {
                print!(" ");
            }
        }
        println!("");
    }
}

