use std::cell::RefCell;

struct Node<T> {
    data: T,
    next: Option<Rc<RefCell<Node<T>>>>,
}

struct Queue<T> {
    head: Option<Rc<RefCell<Node<T>>>>,
    tail: Option<Rc<RefCell<Node<T>>>>,
}

impl<T> Queue<T> {
    fn new() -> Queue<T> {
        Queue { head: None, tail: None }
    }

    fn push(&mut self, t: T) {
        let new_node = Rc::new(RefCell::new(Node { data: t, next: None }));
        match self.tail.take() {
            Some(old_tail) => old_tail.borrow_mut().next = Some(new_node.clone()),
            None => self.head = Some(new_node.clone()),
        }
        self.tail = Some(new_node);
    }

    fn pop(&mut self) -> Option<T> {
        self.head.take().map(|old_head| {
            match old_head.borrow_mut().next.take() {
                Some(new_head) => self.head = Some(new_head),
                None => self.tail.take(),
            }
            Rc::try_unwrap(old_head).ok().unwrap().into_inner().data
        })
    }

    fn is_empty(&self) -> bool {
        self.head.is_none()
    }
}

fn main() {
    let mut q = Queue::new();
    q.push(1);
    q.push(2);
    q.push(3);
    while!q.is_empty() {
        println!("{}", q.pop().unwrap());
    }
}

fn main() {
    let mut list = vec![31, 41, 59, 26, 53, 58, 97, 93, 23, 84];
    println!("unsorted: {:?}", list);

    quicksort(&mut list);
    println!("sorted!  {:?}", list);
}

fn quicksort(a: &mut Vec<i32>) {
    let mut pex = |lower: usize, upper: usize| {
        loop {
            match upper - lower {
                -1 | 0 => return,
                1 => {
                    if a[upper] < a[lower] {
                        a.swap(upper, lower);
                    }
                    return;
                }
                _ => {
                    let bx = (upper + lower) / 2;
                    let b = a[bx];
                    let mut lp = lower;
                    let mut up = upper;
                    loop {
                        while lp < upper &&!(b < a[lp]) {
                            lp += 1;
                        }
                        while {
                            if lp > up {
                                break;
                            }
                            a[up] < b
                        } {
                            up -= 1;
                        }
                        a.swap(lp, up);
                        lp += 1;
                        up -= 1;
                    }
                    if bx < lp {
                        if bx < lp - 1 {
                            a.swap(bx, lp - 1);
                        }
                        up = lp - 2;
                    } else {
                        if bx > lp {
                            a.swap(bx, lp);
                        }
                        up = lp - 1;
                        lp += 1;
                    }
                    if up - lower < upper - lp {
                        pex(lower, up);
                        lower = lp;
                    } else {
                        pex(lp, upper);
                        upper = up;
                    }
                }
            }
        }
    };
    pex(0, a.len() - 1);
}

use std::iter::Sum;
 
fn find_proper_divisors(n: i32) -> Vec<i32> {
    (1..n / 2 + 1)
       .filter(|i| n % i == 0)
       .collect::<Vec<i32>>()
}
 
fn main() {
    let mut deficients = Vec::new();
    let mut perfects = Vec::new();
    let mut abundants = Vec::new();
    for n in 1..20001 {
        let divisors = find_proper_divisors(n);
        let sum: i32 = divisors.iter().sum();
        if sum < n {
            deficients.push(n);
        }
        if sum == n {
            perfects.push(n);
        }
        if sum > n {
            abundants.push(n);
        }
    }
    println!("Deficient : {}", deficients.len());
    println!("Perfect   : {}", perfects.len());
    println!("Abundant  : {}", abundants.len());
}

use std::time::Instant;
use std::thread;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
 
fn main() {
	let gotint = Arc::new(AtomicBool::new(false));
	let gotint_clone = gotint.clone();
	ctrlc::set_handler(move || {
		gotint_clone.store(true, Ordering::SeqCst);
	}).expect("Error setting Ctrl-C handler");
 
	let mut i = 0;
	let start_time = Instant::now();
	while!gotint.load(Ordering::SeqCst) {
		thread::sleep(std::time::Duration::from_millis(500));
		if gotint.load(Ordering::SeqCst) {
			break;
		}
		println!("{}", i);
		i += 1;
	}
	let end_time = Instant::now();
	let dt = end_time.duration_since(start_time).as_secs_f64();
	println!("Program has run for {} seconds", dt);
}

use std::ops::{Add, Mul, Sub};
use std::fmt;
 
#[derive(Debug, Clone, Copy)]
struct Vector {
    x: f64,
    y: f64,
    z: f64,
}
 
impl Vector {
    fn new(x: f64, y: f64, z: f64) -> Vector {
        Vector { x: x, y: y, z: z }
    }
 
    fn scalar_triple_product(&self, b: &Vector, c: &Vector) -> f64 {
        self.inner_product(b.cross_product(c))
    }
 
    fn vector_triple_product(&self, b: &Vector, c: &Vector) -> Vector {
        self.cross_product(b.cross_product(c))
    }
 
    fn inner_product(&self, b: Vector) -> f64 {
        self.x * b.x + self.y * b.y + self.z * b.z
    }
 
    fn cross_product(&self, b: Vector) -> Vector {
        Vector {
            x: self.y * b.z - self.z * b.y,
            y: self.z * b.x - self.x * b.z,
            z: self.x * b.y - self.y * b.x,
        }
    }
}
 
impl Add for Vector {
    type Output = Vector;
 
    fn add(self, b: Vector) -> Vector {
        Vector {
            x: self.x + b.x,
            y: self.y + b.y,
            z: self.z + b.z,
        }
    }
}
 
impl Sub for Vector {
    type Output = Vector;
 
    fn sub(self, b: Vector) -> Vector {
        Vector {
            x: self.x - b.x,
            y: self.y - b.y,
            z: self.z - b.z,
        }
    }
}
 
impl Mul<f64> for Vector {
    type Output = Vector;
 
    fn mul(self, b: f64) -> Vector {
        Vector {
            x: self.x * b,
            y: self.y * b,
            z: self.z * b,
        }
    }
}
 
impl Mul<Vector> for f64 {
    type Output = Vector;
 
    fn mul(self, b: Vector) -> Vector {
        Vector {
            x: self * b.x,
            y: self * b.y,
            z: self * b.z,
        }
    }
}
 
impl fmt::Display for Vector {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "({}, {}, {})", self.x, self.y, self.z)
    }
}
 
fn main() {
    let a = Vector::new(3.0, 4.0, 5.0);
    let b = Vector::new(4.0, 3.0, 5.0);
    let c = Vector::new(-5.0, -12.0, -13.0);
 
    println!("a dot b = {}", a.inner_product(b));
    println!("a cross b = {}", a.cross_product(b));
    println!("a dot (b cross c) = {}", a.scalar_triple_product(&b, &c));
    println!("a cross (b cross c) = {}", a.vector_triple_product(&b, &c));
}

// version 1.1.3
 
typealias Vector = Vec<f64>;
typealias Matrix = Vec<Vector>;
 
fn johnson_trotter(n: usize) -> (Vec<Vec<usize>>, Vec<i32>) {
    let mut p = (0..n).collect::<Vec<usize>>();  // permutation
    let mut q = (0..n).collect::<Vec<usize>>();  // inverse permutation
    let mut d = vec![-1; n];  // direction = 1 or -1
    let mut sign = 1;
    let mut perms = Vec::new();
    let mut signs = Vec::new();
 
    fn permute(k: usize, p: &mut Vec<usize>, q: &mut Vec<usize>, d: &mut Vec<i32>,
               sign: &mut i32, perms: &mut Vec<Vec<usize>>, signs: &mut Vec<i32>) {
        if k >= n {
            perms.push(p.clone());
            signs.push(*sign);
            *sign *= -1;
            return;
        }
        permute(k + 1, p, q, d, sign, perms, signs);
        for i in 0..k {
            let z = p[q[k] + d[k] as usize];
            p[q[k]] = z;
            p[q[k] + d[k] as usize] = k;
            q[z] = q[k];
            q[k] += d[k];
            permute(k + 1, p, q, d, sign, perms, signs);
        }
        d[k] *= -1;
    }
 
    permute(0, &mut p, &mut q, &mut d, &mut sign, &mut perms, &mut signs);
    (perms, signs)
}
 
fn determinant(m: &Matrix) -> f64 {
    let (sigmas, signs) = johnson_trotter(m.len());
    let mut sum = 0.0;
    for (i, sigma) in sigmas.iter().enumerate() {
        let mut prod = 1.0;
        for (j, s) in sigma.iter().enumerate() {
            prod *= m[j][*s];
        }
        sum += signs[i] as f64 * prod;
    }
    sum
}
 
fn cramer(m: &Matrix, d: &Vector) -> Vector {
    let divisor = determinant(m);
    let mut numerators = vec![vec![vec![0.0; m.len()]; m.len()]; m.len()];
    let mut v = vec![0.0; m.len()];
    for i in 0..m.len() {
        for j in 0..m.len() {
            numerators[i][j][i] = d[j];
        }
    }
    for i in 0..m.len() {
        v[i] = determinant(&numerators[i]) / divisor;
    }
    v
}
 
fn main() {
    let m = vec![
        vec![2.0, -1.0,  5.0,  1.0],
        vec![3.0,  2.0,  2.0, -6.0],
        vec![1.0,  3.0,  3.0, -1.0],
        vec![5.0, -2.0, -3.0,  3.0]
    ];
    let d = vec![-3.0, -32.0, -47.0, 49.0];
    let v = cramer(&m, &d);
    println!("w = {}, x = {}, y = {}, z = {}", v[0], v[1], v[2], v[3]);
}

use std::ops::{Not, BitAnd, BitOr};
 
type Pin = bool;
 
fn halfadder(a: Pin, b: Pin) -> (Pin, Pin) {
    let s = (a ^ b) & 1;
    let c = a & b;
    (s, c)
}
 
fn fulladder(a: Pin, b: Pin, ic: Pin) -> (Pin, Pin) {
    let (ps, pc) = halfadder(a, b);
    let (s, tc) = halfadder(ps, ic);
    let oc = tc | pc;
    (s, oc)
}
 
fn fourbitsadder(a0: Pin, a1: Pin, a2: Pin, a3: Pin,
                 b0: Pin, b1: Pin, b2: Pin, b3: Pin) -> (Pin, Pin, Pin, Pin, Pin) {
    let (s0, tc0) = fulladder(a0, b0, false);
    let (s1, tc1) = fulladder(a1, b1, tc0);
    let (s2, tc2) = fulladder(a2, b2, tc1);
    let (s3, overflow) = fulladder(a3, b3, tc2);
    (s0, s1, s2, s3, overflow)
}
 
fn main() {
    let (s0, s1, s2, s3, overflow) = fourbitsadder(false, true, false, true,
                                                   false, true, false, true);
    println!("0101 + 0101 = {:01$b}, overflow = {:01$b}",
             s3 << 3 | s2 << 2 | s1 << 1 | s0,
             overflow, 4);
}

use std::time::Instant;
fn main() {
    let m = 1000000;
    println!("L {} R {}", l(m), r(m));
    let now = Instant::now();
    for _ in 0..1000 {
        l(m);
        r(m);
    }
    println!("{}", now.elapsed());
}
fn l(mut n: u32) -> u32 {
    n -= n & 1;
    n -= 1;
    let mut d1 = 100;
    loop {
        while n % 3 == 0 || n % 5 == 0 || n % 7 == 0 {
            n -= 2;
        }
        let d = n % 10;
        if d == 3 || d == 7 {
            while d1 < n && d < (d = n % d1) && is_p(d) {
                d1 *= 10;
            }
            if d1 > n && is_p(n) {
                return n;
            }
            d1 = 100;
        }
        n -= 2;
    }
}
fn r(mut m: u32) -> u32 {
    let mut p = vec![2, 3, 5, 7];
    let mut n = 20;
    let mut np;
    for i in 1..p.len() {
        n = 10 * p[i];
        if (np = n + 1) >= m {
            break;
        }
        if is_p(np) {
            p.push(np);
        }
        if (np = n + 3) >= m {
            break;
        }
        if is_p(np) {
            p.push(np);
        }
        if (np = n + 7) >= m {
            break;
        }
        if is_p(np) {
            p.push(np);
        }
        if (np = n + 9) >= m {
            break;
        }
        if is_p(np) {
            p.push(np);
        }
    }
    p[p.len() - 1]
}
fn is_p(mut n: u32) -> bool {
    if n < 7 {
        return n == 2 || n == 3 || n == 5;
    }
    if (n & 1) == 0 || n % 3 == 0 || n % 5 == 0 {
        return false;
    }
    let r = (n as f64).sqrt() as u32;
    let mut d = 7;
    while d <= r {
        if n % (d + 00) == 0
            || n % (d + 04) == 0
            || n % (d + 06) == 0
            || n % (d + 10) == 0
            || n % (d + 12) == 0
            || n % (d + 16) == 0
            || n % (d + 22) == 0
            || n % (d + 24) == 0
        {
            return false;
        }
        d += 30;
    }
    true
}

