use std::collections::VecDeque;

struct DataFrame {
    sum: i32,
    coins: Vec<i32>,
    avail_coins: Vec<i32>,
}

fn main() {
    let mut s = VecDeque::new();
    s.push_back(DataFrame {
        sum: 100,
        coins: vec![],
        avail_coins: vec![25, 10, 5, 1],
    });
    let mut ways = 0;
    while!s.is_empty() {
        let top = s.pop_front().unwrap();
        if top.sum < 0 {
            continue;
        }
        if top.sum == 0 {
            ways += 1;
            continue;
        }
        if top.avail_coins.is_empty() {
            continue;
        }
        let mut d = top.clone();
        d.sum -= top.avail_coins[0];
        d.coins.push(top.avail_coins[0]);
        s.push_back(d);
        let mut d = top;
        d.avail_coins.remove(0);
        s.push_back(d);
    }
    println!("{}", ways);
}

