fn combsort(arr: &mut [i32]) {
    let mut gap = arr.len();
    let mut swaps = true;
    while gap > 1 || swaps {
        gap = (1.max(gap as f64 / 1.25)) as usize;
        swaps = false;
        for i in 0..arr.len() - gap {
            if arr[i] > arr[i + gap] {
                arr.swap(i, i + gap);
                swaps = true;
            }
        }
    }
}
 
