use std::fmt;

struct RangeBounds {
    b1: f64,
    b2: f64,
}

impl fmt::Display for RangeBounds {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "({}, {})", self.b1, self.b2)
    }
}

fn map_range(x: RangeBounds, y: RangeBounds, n: f64) -> f64 {
    y.b1 + (n - x.b1) * (y.b2 - y.b1) / (x.b2 - x.b1)
}

fn main() {
    let r1 = RangeBounds { b1: 0.0, b2: 10.0 };
    let r2 = RangeBounds { b1: -1.0, b2: 0.0 };
    for n in (0..11).map(|x| x as f64 * 2.0) {
        println!("{} maps to {}", n, map_range(r1, r2, n));
    }
}

