use std::io;
use std::io::Write;
 
fn to_roman(value: i32) -> String {
    struct romandata_t { value: i32, numeral: &'static str };
    static romandata: [romandata_t; 13] = [
        romandata_t { value: 1000, numeral: "M" },
        romandata_t { value: 900, numeral: "CM" },
        romandata_t { value: 500, numeral: "D" },
        romandata_t { value: 400, numeral: "CD" },
        romandata_t { value: 100, numeral: "C" },
        romandata_t { value: 90, numeral: "XC" },
        romandata_t { value: 50, numeral: "L" },
        romandata_t { value: 40, numeral: "XL" },
        romandata_t { value: 10, numeral: "X" },
        romandata_t { value: 9, numeral: "IX" },
        romandata_t { value: 5, numeral: "V" },
        romandata_t { value: 4, numeral: "IV" },
        romandata_t { value: 1, numeral: "I" }
    ];
 
    let mut result = String::new();
    for current in romandata.iter() {
        while value >= current.value {
            result.push_str(current.numeral);
            value -= current.value;
        }
    }
    result
}
 
fn main() {
    for i in 1..4001 {
        println!("{}", to_roman(i));
    }
}

fn magic(n: i32) {
    for row in 1..n + 1 {
        let mut s = String::new();
        for col in 1..n + 1 {
            let cell = n * ((row + col - 1 + n / 2) % n) + ((row + 2 * col - 2) % n) + 1;
            s.push_str(&format!("{:>width$}", cell, width = (n * n).to_string().len()));
            s.push(' ');
        }
        println!("{}", s);
    }
    println!("\nAll sum to magic number {}", ((n * n + 1) * n / 2));
}
 
fn main() {
    for n in [5, 3, 7].iter() {
        println!("\nOrder {}\n=======", n);
        magic(*n);
    }
}

