fn is_esthetic(n: u64, b: u64) -> bool {
    if n == 0 {
        return false;
    }
    let mut i = n % b;
    let mut n2 = n / b;
    while n2 > 0 {
        let j = n2 % b;
        if (i - j).abs()!= 1 {
            return false;
        }
        n2 = n2 / b;
        i = j;
    }
    return true;
}
 
fn list_esths(n: u64, n2: u64, m: u64, m2: u64, per_line: u64, all: bool) {
    let mut esths = Vec::new();
    let dfs = |n: u64, m: u64, i: u64| {
        if n <= i && i <= m {
            esths.push(i);
        }
        if i == 0 || i > m {
            return;
        }
        let d = i % 10;
        let i1 = i * 10 + d - 1;
        let i2 = i1 + 2;
        if d == 0 {
            dfs(n, m, i2);
        } else if d == 9 {
            dfs(n, m, i1);
        } else {
            dfs(n, m, i1);
            dfs(n, m, i2);
        }
    };
    for i in 0..10 {
        dfs(n2, m2, i);
    }
    let le = esths.len();
    println!("Base 10: {} esthetic numbers between {} and {}", le, n, m);
    if all {
        for (idx, esth) in esths.iter().enumerate() {
            print!("{} ", esth);
            if (idx + 1) % per_line == 0 {
                println!("");
            }
        }
        println!("");
    } else {
        for i in 0..per_line {
            print!("{} ", esths[i as usize]);
        }
        println!("............");
        for i in le - per_line as usize..le {
            print!("{} ", esths[i]);
        }
        println!("");
    }
    println!("");
}
 
fn main() {
    for b in 2..17 {
        println!("Base {}: {}th to {}th esthetic numbers:", b, 4 * b, 6 * b);
        let mut n = 1;
        let mut c = 0;
        while c < 6 * b {
            if is_esthetic(n, b) {
                c += 1;
                if c >= 4 * b {
                    print!("{} ", n.to_string().chars().rev().collect::<String>());
                }
            }
            n += 1;
        }
        println!("");
    }
    println!("");
    list_esths(1000, 1010, 9999, 9898, 16, true);
    list_esths(1e8, 101010101, 13 * 1e7, 123456789, 9, true);
    list_esths(1e11, 101010101010, 13 * 1e10, 123456789898, 7, false);
    list_esths(1e14, 101010101010101, 13 * 1e13, 123456789898989, 5, false);
    list_esths(1e17, 101010101010101010, 13 * 1e16, 123456789898989898, 4, false);
}

use std::f64;
use std::num::FpCategory;
 
fn h(n: u64) -> f64 {
    f64::consts::PI * (n as f64).ln() / (2.0 * (2.0 * f64::consts::PI * n as f64).sqrt())
}
 
fn h2(n: u64) -> f64 {
    let n = n as f64;
    let x = n.ln() * (n + 1.0).ln() - n.ln() - (n + 1.0).ln();
    let y = 2.0 * f64::consts::PI * n;
    let z = y.sqrt() * y.sqrt();
    let w = x - 2.0 * z;
    w.exp()
}
 
