use std::env;
use std::fs;
use std::path::Path;
use std::process;
 
fn file_size_distribution(directory: &Path) {
    let sizes = [0, 1000, 10000, 100000, 1000000, 10000000, 100000000, 1000000000, 10000000000];
    let mut count = [0; 10];
    let mut files = 0;
    let mut total_size = 0;
    for entry in fs::read_dir(directory).unwrap() {
        let entry = entry.unwrap();
        if entry.file_type().unwrap().is_file() {
            let file_size = entry.metadata().unwrap().len();
            total_size += file_size;
            let i = sizes.iter().position(|&s| s >= file_size).unwrap();
            count[i] += 1;
            files += 1;
        }
    }
    println!("File size distribution for {}:", directory.display());
    for (i, size) in sizes.iter().enumerate() {
        if i == sizes.len() - 1 {
            print!("> {} ", sizes[i - 1]);
        } else {
            print!("{:>16} ", size);
        }
        println!("bytes: {}", count[i]);
    }
    println!("Number of files: {}", files);
    println!("Total file size: {} bytes", total_size);
}
 
fn main() {
    let directory = if let Some(arg) = env::args().nth(1) {
        arg
    } else {
        ".".to_string()
    };
    let path = Path::new(&directory);
    if!path.is_dir() {
        eprintln!("{} is not a directory.", directory);
        process::exit(1);
    }
    file_size_distribution(path);
}

fn rk4(y: f64, x: f64, dx: f64, f: &Fn(f64, f64) -> f64) -> f64 {
    let k1 = dx * f(x, y);
    let k2 = dx * f(x + dx / 2.0, y + k1 / 2.0);
    let k3 = dx * f(x + dx / 2.0, y + k2 / 2.0);
    let k4 = dx * f(x + dx, y + k3);
 
    return y + (k1 + 2.0 * k2 + 2.0 * k3 + k4) / 6.0;
}
 
fn f(x: f64, y: f64) -> f64 {
    return x * y.sqrt();
}
 
fn actual(x: f64) -> f64 {
    return (1.0/16.0) * (x*x+4.0)*(x*x+4.0);
}
 
fn main() {
    let mut y = 1.0;
    let mut x = 0.0;
    let step = 0.1;
    let mut steps = 0;
    let max_steps = 101;
    let sample_every_n = 10;
 
    while steps < max_steps {
        if steps%sample_every_n == 0 {
            println!("y({}) = \t{} \t ± {}", x, y, (actual(x) - y).to_string());
        }
 
        y = rk4(y, x, step, &f);
 
        // using integer math for the step addition
        // to prevent floating point errors as 0.2 + 0.1 != 0.3
        x = ((x * 10.0) + (step * 10.0)) / 10.0;
        steps += 1;
    }
}

fn horner(x: i64, c: &[i64]) -> i64 {
    let mut acc = 0;
    for i in (0..c.len()).rev() {
        acc = acc * x + c[i];
    }
    acc
}
 
