use std::io;
use std::io::Write;
use std::collections::VecDeque;
use std::f32;
 
fn main() {
    let mut narc = VecDeque::new();
    let mut powr = [0.0; 10];
    let mut digs = [0; 10];
    let mut st = 0;
    let mut tl = 0;
    let mut pwr = 0;
    let mut len = 0;
    let mx = 25;
    while narc.len() < mx {
        len = get_digs(st, &mut digs);
        if pwr!= len {
            pwr = len;
            fill_power(pwr, &mut powr);
        }
        tl = 0;
        for i in 1..10 {
            tl += powr[i] * digs[i] as f32;
        }
        if tl == st as f32 {
            narc.push_back(st);
        }
        st += 1;
    }
    for i in narc {
        print!("{} ", i);
    }
    print!("\n\n");
    io::stdout().flush().unwrap();
}
 
fn get_digs(st: u32, digs: &mut [i32; 10]) -> i32 {
    let mut r = 0;
    let mut st = st;
    for i in 0..10 {
        digs[i] = 0;
    }
    while st > 0 {
        digs[(st % 10) as usize] += 1;
        st /= 10;
        r += 1;
    }
    r
}
 
fn fill_power(z: i32, powr: &mut [f32; 10]) {
    for i in 1..10 {
        powr[i] = f32::powi(i as f32, z);
    }
}

use std::cmp::Ordering;
use std::collections::HashMap;
use std::sync::mpsc::channel;
use std::thread;
 
fn prime_factors(number: u64) -> Vec<u64> {
    let mut primes = Vec::new();
    let mut div = 2;
    while div <= number {
        while number % div == 0 {
            primes.push(div);
            number = number / div;
        }
        div += 1;
    }
    primes
}
 
fn main() {
    let n = vec![12757923, 12878611, 12757923, 15808973, 15780709, 197622519];
    let (tx, rx) = channel();
    for number in n {
        let tx = tx.clone();
        thread::spawn(move || {
            let factors = prime_factors(number);
            tx.send(factors).unwrap();
        });
    }
    drop(tx);
    let mut factors = Vec::new();
    for factor in rx {
        factors.push(factor);
    }
    let smallest_factors: Vec<u64> = factors.iter().map(|this_numbers_factors| {
        this_numbers_factors.iter().min().unwrap().clone()
    }).collect();
    let biggest_factor = smallest_factors.iter().max().unwrap().clone();
    let what_index_is_that = smallest_factors.iter().position(|&x| x == biggest_factor).unwrap();
    println!("{} has the largest minimum prime factor: {}", n[what_index_is_that], biggest_factor);
    println!("{:?}", factors[what_index_is_that]);
}

