// The Rust code

// Interface for all Continued Fractions
//, February 9th., 2013.
trait ContinuedFraction {
    fn nextTerm(&self) -> i32;
    fn moreTerms(&self) -> bool;
}

// Create a continued fraction from a rational number
//, February 9th., 2013.
struct r2cf {
    n1: i32,
    n2: i32,
}

impl ContinuedFraction for r2cf {
    fn nextTerm(&self) -> i32 {
        let thisTerm = self.n1 / self.n2;
        let t2 = self.n2;
        self.n2 = self.n1 - thisTerm * self.n2;
        self.n1 = t2;
        return thisTerm;
    }
    fn moreTerms(&self) -> bool {
        return (self.n2).abs() > 0;
    }
}

// Generate a continued fraction for sqrt of 2
//, February 9th., 2013.
struct SQRT2 {
    first: bool,
}

impl ContinuedFraction for SQRT2 {
    fn nextTerm(&self) -> i32 {
        if self.first {
            self.first = false;
            return 1;
        } else {
            return 2;
        }
    }
    fn moreTerms(&self) -> bool {
        return true;
    }
}

