use std::time::Duration;
use std::thread::sleep;
 
const WORLD_7X14: [&str; 2] = [
  "+-----------+\n\
   |tH.........|\n\
   |.  .      |\n\
   |  ...     |\n\
   |.  .      |\n\
   |Ht........|\n\
   +-----------+\n",
  "+-----------+\n\
   |tH.........|\n\
   |.  .      |\n\
   |  ...     |\n\
   |.  .      |\n\
   |Ht........|\n\
   +-----------+\n"
];
 
fn next_world(in_: &str, out: &mut String, w: usize, h: usize) {
  for i in 0..w*h {
    match in_.chars().nth(i).unwrap() {
     '' => out.push(' '),
      't' => out.push('.'),
      'H' => out.push('t'),
      '.' => {
        let hc = (in_.chars().nth(i-w-1).unwrap() == 'H') as usize +
                 (in_.chars().nth(i-w).unwrap() == 'H') as usize +
                 (in_.chars().nth(i-w+1).unwrap() == 'H') as usize +
                 (in_.chars().nth(i-1).unwrap() == 'H') as usize +
                 (in_.chars().nth(i+1).unwrap() == 'H') as usize +
                 (in_.chars().nth(i+w-1).unwrap() == 'H') as usize +
                 (in_.chars().nth(i+w).unwrap() == 'H') as usize +
                 (in_.chars().nth(i+w+1).unwrap() == 'H') as usize;
        out.push(if hc == 1 || hc == 2 { 'H' } else { '.' });
      },
      _ => out.push(in_.chars().nth(i).unwrap())
    }
  }
  out.push('\n');
}
 
fn main() {
  let mut f = 0;
  loop {
    println!("{}", WORLD_7X14[f]);
    let mut out = String::new();
    next_world(WORLD_7X14[f], &mut out, 14, 7);
    println!("{}", out);
    f = 1 - f;
    sleep(Duration::from_millis(100));
  }
}

use std::fmt;
 
fn rll_encode(s: &str) -> Vec<u8> {
    let mut r = Vec::new();
    if s.is_empty() {
        return r;
    }
    let mut c = s.chars().next().unwrap();
    if c < 'A' || c > 'Z' {
        panic!("invalid");
    }
    let mut nc = 1;
    for d in s.chars().skip(1) {
        match d {
            d if d!= c => {}
            d if nc < (255 - 24) => {
                nc += 1;
                continue;
            }
            _ => {}
        }
        if nc > 1 {
            r.push(nc + 24);
        }
        r.push((c as u8) - ('A' as u8));
        if d < 'A' || d > 'Z' {
            panic!("invalid");
        }
        c = d;
        nc = 1;
    }
    if nc > 1 {
        r.push(nc + 24);
    }
    r.push((c as u8) - ('A' as u8));
    r
}
 
fn rll_decode(e: &[u8]) -> String {
    let mut c = 0;
    let mut d = String::new();
    for b in e {
        if *b < 26 {
            c = 1;
        } else {
            c = *b - 24;
            b = &e[1];
        }
        for _ in 0..c {
            d.push((b + ('A' as u8)) as char);
        }
    }
    d
}
 
fn main() {
    let s = "WWWWWWWWWWWWBWWWWWWWWWWWWBBBWWWWWWWWWWWWWWWWWWWWWWWWBWWWWWWWWWWWWWW";
    println!("source: {} bytes: {}", s.len(), s);
    let e = rll_encode(s);
    println!("encoded: {} bytes: {:?}", e.len(), e);
    let d = rll_decode(&e);
    println!("decoded: {} bytes: {}", d.len(), d);
    println!("decoded = source: {}", d == s);
}

fn main() {
