fn digit_product(base: i32, n: i32) -> i32 {
    let mut product = 1;
    let mut n = n;
    while n!= 0 {
        product *= n % base;
        n /= base;
    }
    product
}

fn prime_factor_sum(n: i32) -> i32 {
    let mut sum = 0;
    let mut n = n;
    while (n & 1) == 0 {
        sum += 2;
        n >>= 1;
    }
    for p in (3..).step_by(2).take_while(|&p| p * p <= n) {
        while n % p == 0 {
            sum += p;
            n /= p;
        }
    }
    if n > 1 {
        sum += n;
    }
    sum
}

fn is_prime(n: i32) -> bool {
    if n < 2 {
        return false;
    }
    if n % 2 == 0 {
        return n == 2;
    }
    if n % 3 == 0 {
        return n == 3;
    }
    for p in (5..).step_by(4).take_while(|&p| p * p <= n) {
        if n % p == 0 {
            return false;
        }
        let p = p + 2;
        if n % p == 0 {
            return false;
        }
    }
    true
}

fn is_rhonda(base: i32, n: i32) -> bool {
    digit_product(base, n) == base * prime_factor_sum(n)
}

use std::io;
 
fn main() {
	let mut input = String::new();
	println!("Enter year: ");
	io::stdin().read_line(&mut input).expect("Failed to read line");
	let year: i32 = input.trim().parse().expect("Please type a number!");
	let last_day = find_last_sunday(year);
	display(year, &last_day);
}
 
fn find_last_sunday(year: i32) -> [i32; 12] {
	let is_leap = is_leap_year(year);
	let days = [31, if is_leap { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
	let mut last_day = [0; 12];
	for m in 0..12 {
		let mut d;
		for d = days[m]; get_week_day(year, m, d)!= 0; d -= 1 {}
		last_day[m] = d;
	}
	last_day
}
 
fn is_leap_year(year: i32) -> bool {
	if year % 4 == 0 {
		if year % 100!= 0 {
			return true;
		} else if year % 400 == 0 {
			return true;
		}
	}
	false
}
 
fn get_week_day(y: i32, m: i32, d: i32) -> i32 {
	let mut f = y + d + 3 * m - 1;
	m += 1;
	if m < 3 {
		f -= 1;
	} else {
		f -= (0.4 * m as f32 + 2.3) as i32;
	}
	f += (y / 4) - ((y / 100 + 1) * 0.75) as i32;
	f %= 7;
	f
}
 
fn display(year: i32, last_day: &[i32; 12]) {
	println!("\nYEAR: {}", year);
	let months = [
		"January", "February", "March", "April", "May", "June", "July", "August", "September",
		"October", "November", "December",
	];
	for m in 0..12 {
		println!("{}: {}", months[m], last_day[m]);
	}
}

use std::collections::HashMap;
use std::collections::HashSet;
use std::collections::VecDeque;

fn main() {
    let mut variables = HashSet::new();
    let mut symbols = Vec::new();
    let mut operators = HashMap::new();
    operators.insert("!", |stack: &mut VecDeque<bool>| {
       !stack.pop().unwrap()
    });
    operators.insert("&", |stack: &mut VecDeque<bool>| {
        let a = stack.pop().unwrap();
        let b = stack.pop().unwrap();
        a && b
    });
    operators.insert("|", |stack: &mut VecDeque<bool>| {
        let a = stack.pop().unwrap();
        let b = stack.pop().unwrap();
        a || b
    });
    operators.insert("^", |stack: &mut VecDeque<bool>| {
        let a = stack.pop().unwrap();
        let b = stack.pop().unwrap();
        a ^ b
    });
    let mut values = HashMap::new();
    let mut stack = VecDeque::new();
    for symbol in symbols.iter() {
        if!operators.contains_key(symbol) {
            variables.insert(symbol);
        }
    }
    let mut result = String::new();
    for variable in variables.iter() {
        result.push_str(variable);
        result.push(' ');
    }
    result.push(' ');
    for symbol in symbols.iter() {
        result.push_str(symbol);
        result.push(' ');
    }
    result.push('\n');
    for values in enumerate(variables.len()) {
        let mut i = variables.iter();
        for value in values.iter() {
            result.push_str(&format!("{:width$}", if *value { 'T' } else { 'F' }, width = i.next().unwrap().len()));
        }
        result.push(' ');
        result.push(if evaluate(values) { 'T' } else { 'F' });
        result.push('\n');
    }
    println!("{}", result);
}

fn enumerate(size: usize) -> Vec<Vec<bool>> {
    if size == 1 {
        return vec![vec![false], vec![true]];
    }
    let mut result = Vec::new();
    for head in enumerate(size - 1) {
        result.push(vec![false, head]);
        result.push(vec![true, head]);
    }
    result
}

fn evaluate(enumeration: &Vec<bool>) -> bool {
    let mut i = enumeration.iter();
    let mut values = HashMap::new();
    let mut stack = VecDeque::new();
    for variable in variables.iter() {
        values.insert(variable, i.next().unwrap());
    }
    for symbol in symbols.iter() {
        let op = operators.get(symbol);
        stack.push(if op.is_none() {
            values.get(symbol).unwrap()
        } else {
            op.unwrap()(&mut stack)
        });
    }
    stack.pop().unwrap()
}

use std::io;
use std::io::Write;
use std::collections::HashMap;
use rand::Rng;
use rand::thread_rng;

const RPS: &str = "rps";

fn main() {
    let mut rng = thread_rng();
    println!("Rock Paper Scissors");
    println!("Enter r, p, or s as your play.  Anything else ends the game.");
    println!("Running score shown as <your wins>:<my wins>");
    let mut pi = String::new(); // player input
    let mut a_score = 0;
    let mut p_score = 0;
    let mut sl = 3; // for output alignment
    let mut pcf: HashMap<char, i32> = HashMap::new(); // pcf = player choice frequency
    let mut plays = 0;
    let mut a_choice = rng.gen_range(0, 3); // ai choice for first play is completely random
    loop {
        // get player choice
        print!("Play: ");
        io::stdout().flush().unwrap();
        pi.clear();
        io::stdin().read_line(&mut pi).unwrap();
        let p_choice = pi.trim().chars().next();
        if p_choice.is_none() {
            break;
        }
        let p_choice = p_choice.unwrap();
        let p_choice = RPS.find(p_choice);
        if p_choice.is_none() {
            break;
        }
        let p_choice = p_choice.unwrap();
        *pcf.entry(p_choice).or_insert(0) += 1;
        plays += 1;

        // show result of play
        print!("My play:{}.  ", "   ".repeat(sl - 2));
        match (a_choice - p_choice + 3) % 3 {
            0 => println!("Tie."),
            1 => {
                println!("{}.  My point.", msg(a_choice));
                a_score += 1;
            }
            2 => {
                println!("{}.  Your point.", msg(p_choice));
                p_score += 1;
            }
            _ => unreachable!(),
        }

        // show score
        sl = format!("{}:{}  ", p_score, a_score).len();

        // compute ai choice for next play
        let rn = rng.gen_range(0, plays);
        a_choice = if rn < pcf['r'] {
            1
        } else if rn < pcf['r'] + pcf['p'] {
            2
        } else {
            0
        };
    }
}

fn msg(choice: usize) -> &'static str {
    match choice {
        0 => "Rock breaks scissors",
        1 => "Paper covers rock",
        2 => "Scissors cut paper",
        _ => unreachable!(),
    }
}

fn leonardo(n: usize, l0: usize, l1: usize, add: usize) -> Vec<usize> {
    let mut leo = vec![0; n];
    leo[0] = l0;
    leo[1] = l1;
    for i in 2..n {
        leo[i] = leo[i - 1] + leo[i - 2] + add;
    }
    leo
}
 
fn main() {
    println!("The first 25 Leonardo numbers with L[0] = 1, L[1] = 1 and add number = 1 are:");
    println!("{:?}", leonardo(25, 1, 1, 1));
    println!("\nThe first 25 Leonardo numbers with L[0] = 0, L[1] = 1 and add number = 0 are:");
    println!("{:?}", leonardo(25, 0, 1, 0));
}

fn turn(base: i32, n: i32) -> i32 {
    let mut sum = 0;
    let mut n2 = n;
    while n2!= 0 {
        let re = n2 % base;
        n2 /= base;
        sum += re;
    }
    sum % base
}
 
fn fair_share(base: i32, count: i32) {
    print!("Base {:2}: ", base);
    for i in 0..count {
        let t = turn(base, i);
        print!(" {:2}", t);
    }
    println!();
}
 
fn turn_count(base: i32, count: i32) {
    let mut cnt = vec![0; base as usize];
    for i in 0..count {
        let t = turn(base, i);
        cnt[t as usize] += 1;
    }
 
    let mut min_turn = i32::MAX;
    let mut max_turn = i32::MIN;
    let mut portion = 0;
    for i in 0..base {
        let num = cnt[i as usize];
        if num > 0 {
            portion += 1;
        }
        if num < min_turn {
            min_turn = num;
        }
        if num > max_turn {
            max_turn = num;
        }
    }
 
    print!("  With {} people: ", base);
    match min_turn {
        0 => {
            println!("Only {} have a turn", portion);
        }
        max_turn => {
            println!("{}", min_turn);
        }
        _ => {
            println!("{} or {}", min_turn, max_turn);
        }
    }
