    selection_sort(&mut a);
    println!("after: {:?}", a);
}
 
fn selection_sort(a: &mut Vec<i32>) {
    let last = a.len() - 1;
    for i in 0..last {
        let mut a_min = a[i];
        let mut i_min = i;
        for j in i + 1..a.len() {
            if a[j] < a_min {
                a_min = a[j];
                i_min = j;
            }
        }
        a.swap(i, i_min);
    }
}

