use std::rand;
 
fn irand(n: int) -> int {
	let randmax = rand::RAND_MAX / n * n;
	let mut r = rand::random::<int>();
	while r >= randmax {
		r = rand::random::<int>();
	}
	r / (randmax / n)
}
 
fn one_of_n(n: int) -> int {
	let mut r = 0;
	for i in range(1, n) {
		if!irand(i + 1) {
			r = i;
		}
	}
	r
}
 
fn main() {
	let mut r = [0,..10];
	for _ in range(0, 1000000) {
		r[one_of_n(10)] += 1;
	}
	for i in range(0, 10) {
		print!("{}{}", r[i], if i == 9 { "\n" } else { " " });
	}
}

fn shell(seq: &mut [i32]) {
    let mut inc = seq.len() / 2;
    while inc > 0 {
        for i in inc..seq.len() {
            let mut j = i;
            while j >= inc && seq[j - inc] > seq[j] {
                seq.swap(j, j - inc);
                j -= inc;
            }
        }
        if inc == 2 {
            inc = 1;
        } else {
            inc = (inc * 5) / 11;
        }
    }
}

use std::env;
use std::fs::File;
use std::io::prelude::*;
use std::f64::consts::PI;
 
fn process_file(name: &str) {
	let mut file = File::open(name).expect("Unable to open file");
	let mut contents = String::new();
	file.read_to_string(&mut contents)
		.expect("Unable to read file");
	let mut lines = contents.lines();
	let records = lines.next().unwrap().parse::<i32>().unwrap();
	for _ in 0..records {
		let line = lines.next().unwrap();
		let mut words = line.split_whitespace();
		let b1 = words.next().unwrap().parse::<f64>().unwrap();
		let b2 = words.next().unwrap().parse::<f64>().unwrap();
		let diff = (b2 - b1).rem_euclid(360.0);
		println!(
			"Difference between b2({:.2}) and b1({:.2}) is {:.2}",
			b2,
			b1,
			if diff < -180.0 {
				diff + 360.0
			} else if diff >= 180.0 {
				diff - 360.0
			} else {
				diff
			}
		);
	}
}
 
fn main() {
	let args: Vec<String> = env::args().collect();
	if args.len() < 2 {
		println!("Usage : {} <bearings separated by a space OR full file name which contains the bearing list>", args[0]);
	} else if args.len() == 2 {
		process_file(&args[1]);
	} else {
		let diff = (args[2].parse::<f64>().unwrap() - args[1].parse::<f64>().unwrap()).rem_euclid(360.0);
		println!(
			"Difference between b2({:.2}) and b1({:.2}) is {:.2}",
			args[2].parse::<f64>().unwrap(),
			args[1].parse::<f64>().unwrap(),
			if diff < -180.0 {
				diff + 360.0
			} else if diff >= 180.0 {
				diff - 360.0
			} else {
				diff
			}
		);
	}
}

use std::cmp::Ordering;
use std::iter::Iterator;
use std::vec::Vec;
 
fn find_largest_concat(mut mynumbers: Vec<i32>) -> String {
    mynumbers.sort();
    let mut concatnumbers: Vec<String> = Vec::new();
    loop {
        let mut numberstream = String::new();
        for i in mynumbers.iter() {
            numberstream.push_str(&i.to_string());
        }
        concatnumbers.push(numberstream);
        if!mynumbers.next_permutation() {
            break;
        }
    }
    concatnumbers.sort_by(|a, b| {
        if a > b {
            Ordering::Greater
        } else if a < b {
            Ordering::Less
        } else {
            Ordering::Equal
        }
    });
    concatnumbers.pop().unwrap()
}
 
fn main() {
    let mut mynumbers: Vec<i32> = vec![98, 76, 45, 34, 9, 4, 3, 1];
    let mut othernumbers: Vec<i32> = vec![54, 546, 548, 60];
    println!("The largest concatenated int is {} !",
             find_largest_concat(mynumbers));
    println!("And here it is {} !",
             find_largest_concat(othernumbers));
}

