fn all_equal(a: &[&str]) -> bool {
    let mut out = true;
    let mut i = 0;
    while i < a.len() {
        out = out && (a[i] == a[i + 1]);
        i += 1;
    }
    out
}
 
fn az_sorted(a: &[&str]) -> bool {
    let mut out = true;
    let mut i = 0;
    while i < a.len() {
        out = out && (a[i] < a[i + 1]);
        i += 1;
    }
    out
}
 
