    let s = ["AA", "ACB", "BB", "CC"];
    let empty: [&str; 0] = [];
    let single = ["AA"];
    println!("{}", all_equal(&e)); // true
    println!("{}", all_equal(&s)); // false
    println!("{}", all_equal(&empty)); // true
    println!("{}", all_equal(&single)); // true
    println!("{}", az_sorted(&e)); // false
    println!("{}", az_sorted(&s)); // true
    println!("{}", az_sorted(&empty)); // true
    println!("{}", az_sorted(&single)); // true
}

