fn is_isbn13(in_str: &str) -> bool {
    let pre = in_str[0..3].parse::<i32>().unwrap();
    if pre!= 978 {
        return false;
    }
    let post_str = &in_str[4..];
    if post_str.len()!= 10 {
        return false;
    }
    let post = post_str.parse::<i32>().unwrap();
    let mut sum = 38;
    for x in (0..10).step_by(2) {
        sum += (post_str.chars().nth(x).unwrap() as i32 - 48) * 3
            + (post_str.chars().nth(x + 1).unwrap() as i32 - 48);
    }
    if sum % 10 == 0 {
        return true;
    }
    return false;
}

use std::fmt;
 
#[derive(Debug)]
struct Vigenere {
    key: String,
}
 
impl Vigenere {
    fn new(key: &str) -> Result<Vigenere, String> {
        let key = key.to_uppercase();
        if key.is_empty() {
            Err("Invalid key".to_string())
        } else {
            Ok(Vigenere { key: key })
        }
    }
 
    fn encipher(&self, pt: &str) -> String {
        let mut ct = pt.to_uppercase();
        for (i, c) in ct.char_indices() {
            let k = self.key.chars().cycle().nth(i).unwrap();
            ct.replace_range(i..i+1, &((c as u8 + k as u8 - 2 * b'A') % 26 + b'A' as u8).to_string());
        }
        ct
    }
 
    fn decipher(&self, ct: &str) -> Result<String, String> {
        let mut pt = String::new();
        for (i, c) in ct.chars().enumerate() {
            if c < 'A' || c > 'Z' {
                return Err("Invalid ciphertext".to_string());
            }
            let k = self.key.chars().cycle().nth(i).unwrap();
            pt.push((c as u8 + 26 - k as u8) % 26 + b'A' as u8 as char);
        }
        Ok(pt)
    }
}
 
impl fmt::Display for Vigenere {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}", self.key)
    }
}
 
const TEST_KEY: &'static str = "Vigenère Cipher";
const TEST_PT: &'static str = "Beware the Jabberwock, my son!
    The jaws that bite, the claws that catch!";
 
fn main() {
    println!("Supplied key: {}", TEST_KEY);
    let v = Vigenere::new(TEST_KEY).unwrap();
    println!("Effective key: {}", v);
    println!("Plain text: {}", TEST_PT);
    let ct = v.encipher(TEST_PT);
    println!("Enciphered: {}", ct);
    let dt = v.decipher(&ct).unwrap();
    println!("Deciphered: {}", dt);
}

use std::io::Write;
use std::iter::Iterator;
use std::vec::Vec;

const LIMIT1: usize = 1000000;
const LIMIT2: usize = 10000000;

struct PrimeInfo {
    max_print: usize,
    count1: usize,
    count2: usize,
    primes: Vec<usize>,
}

impl PrimeInfo {
    fn new(max: usize) -> PrimeInfo {
        PrimeInfo {
            max_print: max,
            count1: 0,
            count2: 0,
            primes: Vec::new(),
        }
    }

    fn add_prime(&mut self, prime: usize) {
        self.count2 += 1;
        if prime < LIMIT1 {
            self.count1 += 1;
        }
        if self.count2 <= self.max_print {
            self.primes.push(prime);
        }
    }

    fn print<W: Write>(&self, mut os: W, name: &str) -> std::io::Result<()> {
        write!(os, "First {} {} primes: ", self.max_print, name)?;
        for prime in &self.primes {
            write!(os, "{} ", prime)?;
        }
        writeln!(os)?;
        writeln!(os, "Number of {} primes below {}: {}", name, LIMIT1, self.count1)?;
        writeln!(os, "Number of {} primes below {}: {}", name, LIMIT2, self.count2)?;
        Ok(())
    }
}

fn main() {
    let sieve = prime_sieve::PrimeSieve::new(LIMIT2 + 100);

    // count and print strong/weak prime numbers
    let mut strong_primes = PrimeInfo::new(36);
    let mut weak_primes = PrimeInfo::new(37);
    let mut p1 = 2;
    let mut p2 = 3;
    for p3 in 5..LIMIT2 {
        if!sieve.is_prime(p3) {
            continue;
        }
        let diff = p1 + p3 - 2 * p2;
        if diff < 0 {
            strong_primes.add_prime(p2);
        } else if diff > 0 {
            weak_primes.add_prime(p2);
        }
        p1 = p2;
        p2 = p3;
    }
    strong_primes.print(std::io::stdout(), "strong").unwrap();
    weak_primes.print(std::io::stdout(), "weak").unwrap();
}

use std::env;
use std::str::FromStr;
 
fn heap_permute(n: usize, arr: &mut [i32], arr_len: usize) {
	let mut temp: i32;
	let mut i: usize;
 
	if n == 1 {
		print!("\n[");
 
		for i in 0..arr_len {
			print!("{},", arr[i]);
		}
		print!("\b] Sign : {}", flag);
 
		flag *= -1;
	} else {
		for i in 0..n-1 {
			heap_permute(n-1, arr, arr_len);
 
			if n % 2 == 0 {
				temp = arr[i];
				arr[i] = arr[n-1];
				arr[n-1] = temp;
			} else {
				temp = arr[0];
				arr[0] = arr[n-1];
				arr[n-1] = temp;
			}
		}
		heap_permute(n-1, arr, arr_len);
	}
}
 
fn main() {
	let mut arr: Vec<i32>;
	let mut i: usize = 0;
	let mut count: usize = 1;
	let mut token: &str;
 
	if env::args().count() == 1 {
		println!("Usage : {} <comma separated list of integers>", env::args().nth(0).unwrap());
	} else {
		while env::args().nth(1).unwrap().chars().nth(i).unwrap()!= '\0' {
			if env::args().nth(1).unwrap().chars().nth(i).unwrap() == ',' {
				count += 1;
			}
			i += 1;
		}
 
		arr = Vec::with_capacity(count);
 
		i = 0;
 
		token = env::args().nth(1).unwrap().split(",").next().unwrap();
 
		while token!= "" {
			arr.push(FromStr::from_str(token).unwrap());
			token = env::args().nth(1).unwrap().split(",").nth(i).unwrap();
			i += 1;
		}
 
		heap_permute(i, &mut arr, count);
	}
}

fn count_divisors(n: i32) -> i32 {
    if n < 2 {
        return 1;
    }
    let mut count = 2; // 1 and n
    for i in 2..=n/2 {
        if n%i == 0 {
            count += 1;
        }
    }
    return count;
}
 
