use std::fmt;
 
struct SudokuSolver {
    grid: [i32; 81],
}
 
impl SudokuSolver {
    fn new(s: &str) -> SudokuSolver {
        let mut grid = [0; 81];
        for (i, c) in s.chars().enumerate() {
            grid[i] = c.to_digit(10).unwrap() as i32;
        }
        SudokuSolver { grid: grid }
    }
 
    fn solve(&mut self) {
        match self.place_number(0) {
            Ok(_) => println!("Unsolvable!"),
            Err(e) => println!("{} {}", e, self.to_string()),
        }
    }
 
    fn place_number(&mut self, pos: usize) -> Result<(), &'static str> {
        if pos == 81 {
            return Err("Finished!");
        }
        if self.grid[pos] > 0 {
            return self.place_number(pos + 1);
        }
        for n in 1..10 {
            if self.check_validity(n, pos % 9, pos / 9) {
                self.grid[pos] = n;
                match self.place_number(pos + 1) {
                    Ok(_) => return Ok(()),
                    Err(_) => self.grid[pos] = 0,
                }
            }
        }
        Ok(())
    }
 
    fn check_validity(&self, val: i32, x: usize, y: usize) -> bool {
        for i in 0..9 {
            if self.grid[y * 9 + i] == val || self.grid[i * 9 + x] == val {
                return false;
            }
        }
        let start_x = (x / 3) * 3;
        let start_y = (y / 3) * 3;
        for i in start_y..start_y + 3 {
            for j in start_x..start_x + 3 {
                if self.grid[i * 9 + j] == val {
                    return false;
                }
            }
        }
        true
    }
}
 
impl fmt::Display for SudokuSolver {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        for i in 0..9 {
            for j in 0..9 {
                write!(f, "{} ", self.grid[i * 9 + j])?;
                if j == 2 || j == 5 {
                    write!(f, "| ")?;
                }
            }
            write!(f, "\n")?;
            if i == 2 || i == 5 {
                write!(f, "------+-------+------\n")?;
            }
        }
        Ok(())
    }
}
 
fn main() {
    let mut ss = SudokuSolver::new("850002400"
                                   "720000009"
                                   "004000000"
                                   "000107002"
                                   "305000900"
                                   "040000000"
                                   "000080070"
                                   "017000000"
                                   "000036040");
    ss.solve();
}

use std::io::Write;
use std::fs::File;
use std::path::Path;
use std::fmt::Write as FmtWrite;
use std::collections::VecDeque;
 
fn word_fractal(i: i32) -> String {
    if i < 2 {
        if i == 1 {
            return "1".to_string();
        }
        return "".to_string();
    }
    let mut f1 = String::new();
    f1.push_str("1");
    let mut f2 = String::new();
    f2.push_str("0");
    for j in (1..i).rev() {
        let tmp = f2.clone();
        f2.push_str(&f1);
        f1.clear();
        f1.push_str(&tmp);
    }
    return f2;
}
 
fn draw(x: f64, y: f64, dx: f64, dy: f64, wf: &str) -> String {
    let mut x = x;
    let mut y = y;
    let mut dx = dx;
    let mut dy = dy;
    let mut path = String::new();
    for c in wf.chars() {
        path.push_str(&format!("M {} {} L {} {}\n", x, y, x + dx, y + dy));
        x += dx;
        y += dy;
        if c == '0' {
            let tx = dx;
            dx = dy;
            if wf.chars().count() % 2 == 0 {
                dx = -dy;
            }
            dy = -tx;
            if wf.chars().count() % 2 == 0 {
                dy = tx;
            }
        }
    }
    return path;
}
 
fn main() {
    let wf = word_fractal(23);
    let path = draw(20.0, 20.0, 1.0, 0.0, &wf);
    let mut file = File::create(Path::new("fib_wordfractal.svg")).unwrap();
    file.write_all(b"<svg width=\"450\" height=\"620\" xmlns=\"http://www.w3.org/2000/svg\">\n").unwrap();
    file.write_all(b"<path d=\"").unwrap();
    file.write_all(path.as_bytes()).unwrap();
    file.write_all(b"\" stroke=\"green\" fill=\"none\" />\n").unwrap();
    file.write_all(b"</svg>").unwrap();
}

