fn reverse(s: u64) -> u64 {
    let mut e = 0;
    let mut s = s;
    while s > 0 {
        e = e * 10 + (s % 10);
        s /= 10;
    }
    e
}
 
fn commatize(n: u32) -> String {
    let s = format!("{}", n);
    let mut le = s.len();
    let mut i = le - 3;
    while i >= 1 {
        let mut s = s.split_at(i);
        s.0.to_owned() + "," + s.1;
        i -= 3;
    }
    s
}
 
fn ord(n: u32) -> String {
    let mut suffix = "";
    if n > 10 && ((n - 11) % 100 == 0 || (n - 12) % 100 == 0 || (n - 13) % 100 == 0) {
        suffix = "th";
    } else {
        match n % 10 {
            1 => suffix = "st",
            2 => suffix = "nd",
            3 => suffix = "rd",
            _ => suffix = "th",
        }
    }
    format!("{}{}", commatize(n), suffix)
}
 
fn main() {
    let max = 10_000_000;
    let data = vec![[1, 20, 7], [86, 100, 8], [991, 1000, 10], [9995, 10000, 12], [100_000, 100_000, 14],
        [1_000_000, 1_000_000, 16], [10_000_000, 10_000_000, 18]];
    let mut results: HashMap<u32, Vec<u64>> = HashMap::new();
    for d in &data {
        for i in d[0]..=d[1] {
            results.insert(i, vec![0; 9]);
        }
    }
    let mut p: u64;
    'outer: for d in 1..10 {
        let mut count = 0;
        let mut pow = 1;
        let fl = d * 11;
        for nd in 3..20 {
            let slim = (d + 1) * pow;
            for s in d * pow..slim {
                let e = reverse(s);
                let mut mlim = 1;
                if nd % 2 == 1 {
                    mlim = 10;
                }
                for m in 0..mlim {
                    if nd % 2 == 0 {
                        p = s * pow * 10 + e;
                    } else {
                        p = s * pow * 100 + m * pow * 10 + e;
                    }
                    if p % fl == 0 {
                        count += 1;
                        if let Some(v) = results.get_mut(&count) {
                            v[d as usize - 1] = p;
                        }
                        if count == max {
                            continue 'outer;
                        }
                    }
                }
            }
            if nd % 2 == 1 {
                pow *= 10;
            }
        }
    }
 
    for d in &data {
        if d[0]!= d[1] {
            println!(
                "{} to {} palindromic gapful numbers (> 100) ending with:",
                ord(d[0]),
                ord(d[1])
            );
        } else {
            println!(
                "{} palindromic gapful number (> 100) ending with:",
                ord(d[0])
            );
        }
        for i in 1..=9 {
            print!("{}: ", i);
            for j in d[0]..=d[1] {
                print!("{:0width$} ", results[&j][i as usize - 1], width = d[2]);
            }
            println!();
        }
        println!();
    }
}

