use std::fmt::Formatter;
use std::fmt::Error;
use std::vec::Vec;
 
struct UlamSpiral {
    lst: Vec<i32>,
    mx: i32,
    wd: i32,
}
 
impl UlamSpiral {
    fn new(n: i32, start_with: i32) -> UlamSpiral {
        let mut lst = Vec::new();
        if n % 2 == 0 {
            lst.resize((n + 1) as usize, -1);
        } else {
            lst.resize(n as usize, -1);
        }
        let mx = n;
        let wd = (f64::log10(n as f64 * n as f64) + 1.0) as i32;
        let mut spiral = UlamSpiral { lst: lst, mx: mx, wd: wd };
        spiral.arrange(start_with);
        spiral
    }
    fn arrange(&mut self, start_with: i32) {
        let mut stp = 1;
        let mut n = 1;
        let mut pos_x = self.mx / 2;
        let mut pos_y = pos_x;
        let mut st_c = 0;
        let mut dx = 1;
        let mut dy = 0;
        while pos_x < self.mx && pos_y < self.mx {
            self.lst[pos_x as usize + pos_y as usize * self.mx as usize] = if is_prime(start_with + n) {
                start_with + n
            } else {
                0
            };
            n += 1;
            if dx!= 0 {
                pos_x += dx;
                if st_c + 1 == stp {
                    dy = -dx;
                    dx = 0;
                    st_c = 0;
                }
            } else {
                pos_y += dy;
                if st_c + 1 == stp {
                    dx = dy;
                    dy = 0;
                    stp += 1;
                    st_c = 0;
                }
            }
            st_c += 1;
        }
    }
    fn display(&self, c: char) {
        if c == '\0' {
            self.display_numbers();
        } else {
            self.display_symbol(c);
        }
    }
    fn display_numbers(&self) {
        let mut ct = 0;
        for i in &self.lst {
            if *i!= -1 {
                print!("{:>width$} ", *i, width = self.wd);
            } else {
                print!("{:>width$} ", "*", width = self.wd);
            }
            ct += 1;
            if ct >= self.mx {
                println!("");
                ct = 0;
            }
        }
        println!("");
    }
    fn display_symbol(&self, c: char) {
        let mut ct = 0;
        for i in &self.lst {
            if *i!= -1 {
                print!("{}", c);
            } else {
                print!(" ");
            }
            ct += 1;
            if ct >= self.mx {
                println!("");
                ct = 0;
            }
        }
        println!("");
    }
}
 
fn is_prime(n: i32) -> bool {
    if n < 4 {
        return n > 1;
    }
    if n % 2 == 0 || n % 3 == 0 {
        return false;
    }
    let q = f64::sqrt(n as f64) as i32;
    let mut c = 5;
    while c <= q {
        if n % c == 0 || n % (c + 2) == 0 {
            return false;
        }
        c += 6;
    }
    true
}
 
fn main() {
    let mut ulam = UlamSpiral::new(9, 1);
    ulam.display('\0');
    ulam = UlamSpiral::new(35, 1);
    ulam.display('#');
}

use std::ops::Add;
use std::ops::Mul;
use std::ops::Sub;
 
