    let rows = (0..41)
       .map(|y| {
            (0..80)
               .map(|x| {
                    let a = Complex::new(
                        -2.0 + (x as f64 * 0.0315),
                        1.0 - (y as f64 * 0.05),
                    );
                    let z = mandelbrot(a);
                    if z.abs() < 2.0 {
                        '*'
                    } else {
                       ''
                    }
                })
               .collect::<String>()
        })
       .collect::<Vec<String>>();
    println!("{}", rows.join("\n"));
