extern crate rand;
extern crate sdl2;

use rand::Rng;
use sdl2::event::Event;
use sdl2::keyboard::Keycode;
use sdl2::pixels::Color;
use sdl2::rect::Rect;
use sdl2::render::Canvas;
use sdl2::video::Window;
use std::time::Duration;

const MAXSPEED: i32 = 15;
const SIZE: u32 = 3;
const COLOR: Color = Color::RGB(45, 90, 45);
const WINDOWSIZE: u32 = 400;
const TIMETICK: u32 = 1;
const MAXPART: usize = 50;

struct Particle {
    vector: (i32, i32),
    location: (i32, i32),
    surface: Canvas<Window>,
}

impl Particle {
    fn new(vector: (i32, i32), location: (i32, i32), surface: Canvas<Window>) -> Particle {
        Particle {
            vector: vector,
            location: location,
            surface: surface,
        }
    }

    fn on_edge(&self) {
        if self.location.0 <= 0 {
            self.vector.0 = self.vector.0.abs();
        } else if self.location.1 <= 0 {
            self.vector.1 = self.vector.1.abs();
        } else if self.location.0 >= WINDOWSIZE {
            self.vector.0 = -self.vector.0.abs();
        } else if self.location.1 >= WINDOWSIZE {
            self.vector.1 = -self.vector.1.abs();
        }
    }

    fn update(&mut self) {
        self.surface.set_draw_color(Color::RGB(0, 0, 0));
        self.surface.fill_rect(Rect::new(self.location.0, self.location.1, SIZE, SIZE));
        self.on_edge();
        self.location.0 += self.vector.0;
        self.location.1 += self.vector.1;
        self.surface.set_draw_color(COLOR);
        self.surface.fill_rect(Rect::new(self.location.0, self.location.1, SIZE, SIZE));
    }

    fn stop(&mut self) {
        self.vector = (0, 0);
    }

    fn accelerate(&mut self, vector: (i32, i32)) {
        self.vector = vector;
    }
}

fn main() {
    let sdl_context = sdl2::init().unwrap();
    let video_subsystem = sdl_context.video().unwrap();
    let window = video_subsystem
       .window("Brownian Tree", WINDOWSIZE, WINDOWSIZE)
       .position_centered()
       .build()
       .unwrap();
    let mut canvas = window.into_canvas().build().unwrap();
    let mut event_pump = sdl_context.event_pump().unwrap();

    let mut particles: Vec<Particle> = Vec::new();

    let mut rng = rand::thread_rng();
    let half = WINDOWSIZE / 2;
    let tenth = WINDOWSIZE / 10;
    let root = Particle::new(
        (0, 0),
        (
            rng.gen_range(half - tenth, half + tenth),
            rng.gen_range(half - tenth, half + tenth),
        ),
        canvas.clone(),
    );
    root.stop();
    particles.push(root);

    'running: loop {
        for event in event_pump.poll_iter() {
            match event {
                Event::Quit {.. }
                | Event::KeyDown {
                    keycode: Some(Keycode::Escape),
                   ..
                } => break 'running,
                _ => {}
            }
        }

        if particles.len() < MAXPART {
            particles.push(Particle::new(
                (
                    rng.gen_range(-MAXSPEED, MAXSPEED),
                    rng.gen_range(-MAXSPEED, MAXSPEED),
                ),
                (
                    rng.gen_range(0, WINDOWSIZE),
                    rng.gen_range(0, WINDOWSIZE),
                ),
                canvas.clone(),
            ));
        }

        for particle in &mut particles {
            particle.update();
        }

        canvas.present();
        ::std::thread::sleep(Duration::new(0, 1_000_000_000u32 / 60));
    }
}

