fn insertion_sort(a: &mut [i32]) {
    for i in 0..a.len() {
        let k = a[i];
        let mut j = i;
        while j > 0 && k < a[j - 1] {
            a[j] = a[j - 1];
            j -= 1;
        }
        a[j] = k;
    }
}

