fn lex_order(n: i32) -> Vec<i32> {
    if n < 1 {
        return (n..2-n).collect();
    }
    let mut v = (1..n+1).collect();
    v.sort_by(|a, b| a.to_string().cmp(&b.to_string()));
    v
}

