fn is_self_describing(n: u64) -> bool {
    let s = n.to_string();
    s.chars()
       .enumerate()
       .all(|(i, ch)| s.chars().filter(|&c| c == ch.to_string().parse::<u8>().unwrap()).count() == i as u8)
}

