pub struct Color {
    pub red: u8,
    pub blue: u8,
    pub green: u8,
}

pub struct Bitmap {
    imagemap: Vec<Vec<Color>>,
}

impl Bitmap {
    pub fn new(width: usize, height: usize) -> Self {
        let mut imagemap = Vec::with_capacity(width);
        for _ in 0..width {
            let mut row = Vec::with_capacity(height);
            for _ in 0..height {
                row.push(Color {
                    red: 0,
                    blue: 0,
                    green: 0,
                });
            }
            imagemap.push(row);
        }
        Bitmap { imagemap }
    }

    pub fn fill(&mut self, color: Color) {
        for row in self.imagemap.iter_mut() {
            for pixel in row.iter_mut() {
                *pixel = color;
            }
        }
    }

    pub fn get_pixel(&self, x: usize, y: usize) -> Color {
        self.imagemap[x][y]
    }

    pub fn set_pixel(&mut self, x: usize, y: usize, color: Color) {
        self.imagemap[x][y] = color;
    }
}

