use std::io;
use std::rand;
 
fn biased(bias: int) -> bool {
	let rand_max = rand::MAX - (rand::MAX % bias);
	let r = rand::random::<int>();
	r < rand_max / bias
}
 
fn unbiased(bias: int) -> bool {
	let mut a = biased(bias);
	while a == biased(bias) {
		a = biased(bias);
	}
	a
}
 
fn main() {
	let n = 10000;
	for b in range(3, 7) {
		let mut cb = 0;
		let mut cu = 0;
		for _ in range(0, n) {
			if biased(b) { cb += 1; }
			if unbiased(b) { cu += 1; }
		}
		println!("bias {}: {}% vs {}%", b, 100.0 * cb as f64 / n as f64, 100.0 * cu as f64 / n as f64);
	}
}

use std::io;
use std::str::FromStr;
use std::fmt;
 
// Class representing an IPv4 address + netmask length
#[derive(Debug)]
struct Ipv4Cidr {
    address: u32,
    mask_length: u8,
}
 
impl Ipv4Cidr {
    fn new(address: u32, mask_length: u8) -> Ipv4Cidr {
        Ipv4Cidr {
            address: address,
            mask_length: mask_length,
        }
    }
}
 
// Stream extraction operator, also performs canonicalization
impl FromStr for Ipv4Cidr {
    type Err = io::Error;
    fn from_str(s: &str) -> Result<Ipv4Cidr, Self::Err> {
        let mut parts = s.split('/');
        let address_str = parts.next().ok_or(io::Error::new(io::ErrorKind::InvalidInput, "Invalid input"))?;
        let mask_length_str = parts.next().ok_or(io::Error::new(io::ErrorKind::InvalidInput, "Invalid input"))?;
        let mask_length: u8 = mask_length_str.parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid input"))?;
        let address: u32 = address_str.parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid input"))?;
        let mask =!((1 << (32 - mask_length)) - 1);
        let address = address & mask;
        Ok(Ipv4Cidr::new(address, mask_length))
    }
}
 
// Stream insertion operator
impl fmt::Display for Ipv4Cidr {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let a = (self.address >> 24) & 0xff;
        let b = (self.address >> 16) & 0xff;
        let c = (self.address >> 8) & 0xff;
        let d = self.address & 0xff;
        write!(f, "{}.{}.{}.{}/{}", a, b, c, d, self.mask_length)
    }
}
 
fn main() {
    let tests = vec![
        "87.70.141.1/22",
        "36.18.154.103/12",
        "62.62.197.11/29",
        "67.137.119.181/4",
        "161.214.74.21/24",
        "184.232.176.184/18",
    ];
    for test in tests {
        let cidr = Ipv4Cidr::from_str(test).unwrap();
        println!("{:18} -> {}", test, cidr);
    }
}

