fn main() {
    let file = File::open("unixdict.txt").unwrap();
    let reader = BufReader::new(file);
    let mut words = HashSet::new();
    let mut count = 0;

    for line in reader.lines() {
        let word = line.unwrap();
        let drow: String = word.chars().rev().collect();
        if!words.contains(&drow) {
            words.insert(word);
        } else {
            if count < 5 {
                println!("{} {}", word, drow);
            }
            count += 1;
        }
    }
    println!("\nSemordnilap pairs: {}", count);
}

use std::io::Read;
use std::collections::HashMap;
use std::fs::File;
use std::io::Write;
use std::path::Path;
use std::env;
use std::process::Command;
 
fn main() {
    let mut tasks = HashMap::new();
    let mut total = 0;
    let mut file = File::open("tasks.txt").unwrap();
    let mut contents = String::new();
    file.read_to_string(&mut contents).unwrap();
    let mut lines = contents.lines();
    while let Some(line) = lines.next() {
        let mut url = "https://www.rosettacode.org/mw/index.php?title=".to_string();
        url.push_str(line);
        url.push_str("&action=raw");
        let output = Command::new("curl")
           .arg("-s")
           .arg(url)
           .output()
           .expect("failed to execute process");
        let count = output.stdout.iter().filter(|&&x| x == b'{' && output.stdout[output.stdout.iter().position(|&y| y == b'{').unwrap() + 1] == b'h').count();
        tasks.insert(line.to_string(), count);
        total += count;
        println!("{}: {}", line.replace("_", " "), count);
    }
    println!("\nTotal: {} examples.", total);
}

use std::cmp::Ordering;
use std::fmt;
use std::ops::Deref;

fn printtable<T: Deref<Target=[String]> + fmt::Display>(data: &[T]) {
    for row in data {
        println!("{}", row);
    }
}

fn sorttable<T: Deref<Target=[String]> + fmt::Display>(
    table: &[T],
    ordering: Option<fn(&T, &T) -> Ordering>,
    column: usize,
    reverse: bool,
) -> Vec<T> {
    let mut table = table.to_vec();
    table.sort_by(|a, b| {
        let a = a.deref();
        let b = b.deref();
        if let Some(ordering) = ordering {
            ordering(a, b)
        } else {
            a[column].cmp(&b[column])
        }
    });
    if reverse {
        table.reverse();
    }
    table
}

fn main() {
    let data = vec![
        vec!["a".to_string(), "b".to_string(), "c".to_string()],
        vec!["".to_string(), "q".to_string(), "z".to_string()],
        vec!["zap".to_string(), "zip".to_string(), "Zot".to_string()],
    ];
    printtable(&data);
    println!();
    printtable(&sorttable(&data, None, 0, false));
    println!();
    printtable(&sorttable(&data, None, 2, false));
    println!();
    printtable(&sorttable(&data, None, 1, false));
    println!();
    printtable(&sorttable(&data, None, 1, true));
    println!();
    printtable(&sorttable(
        &data,
        Some(|a, b| b.len().cmp(&a.len())),
        0,
        false,
    ));
}

