use std::cmp::Ordering;
use std::fmt;
 
#[derive(Debug)]
struct Item {
    w: f64,
    v: f64,
    name: &'static str,
}
 
impl Item {
    fn new(w: f64, v: f64, name: &'static str) -> Item {
        Item { w: w, v: v, name: name }
    }
}
 
impl Ord for Item {
    fn cmp(&self, other: &Item) -> Ordering {
        let ua = self.v / self.w;
        let ub = other.v / other.w;
        if ua < ub {
            Ordering::Less
        } else if ua > ub {
            Ordering::Greater
        } else {
            Ordering::Equal
        }
    }
}
 
impl PartialOrd for Item {
    fn partial_cmp(&self, other: &Item) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
 
impl PartialEq for Item {
    fn eq(&self, other: &Item) -> bool {
        self.cmp(other) == Ordering::Equal
    }
}
 
impl Eq for Item {}
 
impl fmt::Display for Item {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "Item {{ w: {}, v: {}, name: {} }}", self.w, self.v, self.name)
    }
}
 
fn main() {
    let items = [
        Item::new(3.8, 36.0, "beef"),
        Item::new(5.4, 43.0, "pork"),
        Item::new(3.6, 90.0, "ham"),
        Item::new(2.4, 45.0, "greaves"),
        Item::new(4.0, 30.0, "flitch"),
        Item::new(2.5, 56.0, "brawn"),
        Item::new(3.7, 67.0, "welt"),
        Item::new(3.0, 95.0, "salami"),
        Item::new(5.9, 98.0, "sausage"),
    ];
    let mut space = 15.0;
    let mut items = items.to_vec();
    items.sort();
    for it in items.iter().rev() {
        if space >= it.w {
            println!("take all {}", it.name);
            space -= it.w;
        } else {
            println!("take {}kg of {} kg of {}", space, it.w, it.name);
            space = 0.0;
        }
    }
}

