use std::iter::FromIterator;

fn main() {
    let empty: Vec<i32> = Vec::new();
    let list1 = vec![1, 2];
    let list2 = vec![3, 4];
    let list3 = vec![1776, 1789];
    let list4 = vec![7, 12];
    let list5 = vec![4, 14, 23];
    let list6 = vec![0, 1];
    let list7 = vec![1, 2, 3];
    let list8 = vec![30];
    let list9 = vec![500, 100];

    for sequence_list in vec![
        vec![&list1, &list2],
        vec![&list2, &list1],
        vec![&list1, &empty],
        vec![&empty, &list1],
        vec![&list3, &list4, &list5, &list6],
        vec![&list7, &list8, &list9],
        vec![&list7, &empty, &list9],
    ] {
        let cart = sequence_list
           .iter()
           .cartesian_product()
           .map(|tuple| format!("({:?})", tuple));
        println!("{:?}", cart);
    }
}

trait CartesianProduct {
    fn cartesian_product<T>(self) -> CartesianProductIterator<Self, T>
    where
        Self: Iterator<Item = T>,
        T: Iterator;
}

impl<I> CartesianProduct for I
where
    I: Iterator,
{
    fn cartesian_product<T>(self) -> CartesianProductIterator<Self, T>
    where
        Self: Iterator<Item = T>,
        T: Iterator,
    {
        CartesianProductIterator {
            outer: self,
            inner: None,
        }
    }
}

struct CartesianProductIterator<I, T>
where
    I: Iterator,
    T: Iterator,
{
    outer: I,
    inner: Option<T>,
}

impl<I, T> Iterator for CartesianProductIterator<I, T>
where
    I: Iterator,
    T: Iterator,
{
    type Item = Vec<T::Item>;

    fn next(&mut self) -> Option<Self::Item> {
        if let Some(ref mut inner) = self.inner {
            if let Some(item) = inner.next() {
                return Some(vec![item]);
            }
        }

        while let Some(outer_item) = self.outer.next() {
            self.inner = Some(outer_item);
            if let Some(inner_item) = self.inner.as_mut().unwrap().next() {
                return Some(vec![inner_item]);
            }
        }

        None
    }
}

impl<I, T> Iterator for CartesianProductIterator<I, T>
where
    I: Iterator,
    T: Iterator,
    T::Item: Clone,
{
    type Item = Vec<T::Item>;

    fn next(&mut self) -> Option<Self::Item> {
        if let Some(ref mut inner) = self.inner {
            if let Some(item) = inner.next() {
                let mut result = self.next().unwrap();
                result.push(item);
                return Some(result);
            }
        }

        while let Some(outer_item) = self.outer.next() {
            self.inner = Some(outer_item);
            if let Some(inner_item) = self.inner.as_mut().unwrap().next() {
                let mut result = self.next().unwrap();
                result.push(inner_item);
                return Some(result);
            }
        }

        None
    }
}

