use std::f64;
use std::fmt;
use std::ops;
 
fn main() {
    let test1 = Matrix::new(3, 3, vec![25.0, 15.0, -5.0, 15.0, 18.0, 0.0, -5.0, 0.0, 11.0]);
    let test2 = Matrix::new(4, 4, vec![18.0, 22.0, 54.0, 42.0, 22.0, 70.0, 86.0, 62.0, 54.0, 86.0, 174.0, 134.0, 42.0, 62.0, 134.0, 106.0]);
 
    let chol1 = cholesky(&test1);
    let chol2 = cholesky(&test2);
 
    println!("Test 1: ");
    println!("{}", test1);
    println!("");
    println!("Lower Cholesky 1: ");
    println!("{}", chol1);
    println!("");
    println!("Test 2: ");
    println!("{}", test2);
    println!("");
    println!("Lower Cholesky 2: ");
    println!("{}", chol2);
}
 
fn cholesky(a: &Matrix) -> Matrix {
    let n = a.rows;
 
    let mut ret = Matrix::new(n, n, vec![0.0; n * n]);
    for r in 0..n {
        for c in 0..=r {
            if c == r {
                let mut sum = 0.0;
                for j in 0..c {
                    sum += ret[(c, j)] * ret[(c, j)];
                }
                ret[(c, c)] = (a[(c, c)] - sum).sqrt();
            } else {
                let mut sum = 0.0;
                for j in 0..c {
                    sum += ret[(r, j)] * ret[(c, j)];
                }
                ret[(r, c)] = (a[(r, c)] - sum) / ret[(c, c)];
            }
        }
    }
 
    ret
}
 
#[derive(Debug, Clone)]
struct Matrix {
    rows: usize,
    cols: usize,
    data: Vec<f64>,
}
 
impl Matrix {
    fn new(rows: usize, cols: usize, data: Vec<f64>) -> Matrix {
        assert_eq!(data.len(), rows * cols);
        Matrix { rows, cols, data }
    }
 
    fn index(&self, row: usize, col: usize) -> usize {
        assert!(row < self.rows);
        assert!(col < self.cols);
        row * self.cols + col
    }
}
 
impl ops::Index<(usize, usize)> for Matrix {
    type Output = f64;
 
    fn index(&self, index: (usize, usize)) -> &f64 {
        &self.data[self.index(index.0, index.1)]
    }
}
 
impl ops::IndexMut<(usize, usize)> for Matrix {
    fn index_mut(&mut self, index: (usize, usize)) -> &mut f64 {
        &mut self.data[self.index(index.0, index.1)]
    }
}
 
impl fmt::Display for Matrix {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        for r in 0..self.rows {
            for c in 0..self.cols {
                write!(f, "{:>9.5}", self[(r, c)])?;
            }
            writeln!(f)?;
        }
        Ok(())
    }
}

fn sieve(max: i32) -> Vec<i32> {
    let mut xs = (2..max).collect::<Vec<i32>>();
    let limit = (max as f64).sqrt() as i32;
    for x in 2..limit {
        xs.retain(|&x| x % x!= 0);
    }
    xs
}
 
fn main() {
    println!("{:?}", sieve(100));
}

fn gcd_iter(mut u: i32, mut v: i32) -> i32 {
    if u < 0 {
        u = -u;
    }
    if v < 0 {
        v = -v;
    }
    if v!= 0 {
        while u %= v!= 0 && v %= u!= 0 {}
    }
    return u + v;
}

use std::f64;

const EPSILON: f64 = 1.0e-15;

fn main() {
    let mut fact: u64 = 1;
    let mut e: f64 = 2.0;
    let mut e0: f64;
    let mut n: u32 = 2;
    loop {
        e0 = e;
        fact *= n;
        n += 1;
        e += 1.0 / fact as f64;
        if (e - e0).abs() < EPSILON {
            break;
        }
    }
    println!("e = {:.15}", e);
}

use std::collections::HashMap;
 
// Compress a string to a list of output symbols.
fn compress(uncompressed: &str) -> Vec<u8> {
    // Build the dictionary.
    let mut dict_size = 256;
    let mut dictionary: HashMap<String, u8> = HashMap::new();
    for i in 0..dict_size {
        dictionary.insert(i.to_string(), i as u8);
    }
 
    let mut w = String::new();
    let mut result = Vec::new();
    for c in uncompressed.chars() {
        let wc = w.clone() + &c.to_string();
        if dictionary.contains_key(&wc) {
            w = wc;
        } else {
            result.push(dictionary[&w]);
            // Add wc to the dictionary.
            dictionary.insert(wc.clone(), dict_size as u8);
            dict_size += 1;
            w = c.to_string();
        }
    }
 
    // Output the code for w.
    if!w.is_empty() {
        result.push(dictionary[&w]);
    }
    result
}
 
// Decompress a list of output ks to a string.
fn decompress(compressed: Vec<u8>) -> String {
    // Build the dictionary.
    let mut dict_size = 256;
    let mut dictionary: HashMap<u8, String> = HashMap::new();
    for i in 0..dict_size {
        dictionary.insert(i as u8, i.to_string());
    }
 
    let mut w = dictionary[&compressed[0]].clone();
    let mut result = w.clone();
    for k in &compressed[1..] {
        let entry = if dictionary.contains_key(k) {
            dictionary[k].clone()
        } else if *k == dict_size {
            w.clone() + &w[0..1]
        } else {
            panic!("Bad compressed k: {}", k);
        };
        result += &entry;
 
        // Add w+entry[0] to the dictionary.
        dictionary.insert(dict_size as u8, w.clone() + &entry[0..1]);
        dict_size += 1;
 
        w = entry;
    }
    result
}
 
// How to use:
fn main() {
    let compressed = compress("TOBEORNOTTOBEORTOBEORNOT");
    println!("{:?}", compressed);
    let decompressed = decompress(compressed);
    println!("{}", decompressed);
}

