// version 1.1.3
 
type Vector = Vec<f64>;
type Matrix = Vec<Vector>;
 
fn transpose(matrix: &Matrix) -> Matrix {
    let rows = matrix.len();
    let cols = matrix[0].len();
    let mut trans = vec![vec![0.0; rows]; cols];
    for i in 0..cols {
        for j in 0..rows {
            trans[i][j] = matrix[j][i];
        }
    }
    trans
}
 
// Alternate version
type Matrix<T> = Vec<Vec<T>>;
fn transpose<T>(matrix: &Matrix<T>) -> Matrix<T> {
    (0..matrix[0].len()).map(|x| {
        (0..matrix.len()).map(|y| {
            matrix[y][x].clone()
        }).collect()
    }).collect()
}

use image::{ImageBuffer, Rgb};
use std::f64::consts::PI;
 
fn main() {
    let mut img = ImageBuffer::new(300, 300);
    let radius = (img.width() * img.width() + img.height() * img.height()) as f64 / 4.0;
    let cx = img.width() / 2;
    let cy = img.height() / 2;
 
    for (x, y, pixel) in img.enumerate_pixels_mut() {
        let rx = x as f64 - cx as f64;
        let ry = y as f64 - cy as f64;
        let s = (rx * rx + ry * ry).sqrt() / radius;
        if s <= 1.0 {
            let h = ((ry.atan2(rx) / PI) + 1.0) / 2.0;
            let rgb = colorsys::hsv_to_rgb(h, s, 1.0);
            *pixel = Rgb([
                (rgb[0] * 255.0) as u8,
                (rgb[1] * 255.0) as u8,
                (rgb[2] * 255.0) as u8,
            ]);
        }
    }
 
    img.save("image.png").unwrap();
}

use std::collections::HashSet;
use std::iter::FromIterator;
 
fn print_collection<T: std::fmt::Display>(x: &HashSet<T>) {
    println!("{}", x.iter().map(|x| x.to_string()).collect::<Vec<String>>().join(" "));
}
 
fn main() {
    println!("Set creation");
    let mut A = HashSet::from_iter(vec![4, 12, 14, 17, 18, 19, 20]);
    let mut B = HashSet::from_iter(vec![2, 5, 8, 11, 12, 13, 17, 18, 20]);
 
    print_collection(&A);
    print_collection(&B);
 
    println!("Test m ∈ S -- \"m is an element in set S\"");
    println!("14 is an element in set A: {}", A.contains(&14));
    println!("15 is an element in set A: {}", A.contains(&15));
 
    println!("A ∪ B -- union; a set of all elements either in set A or in set B.");
    let aUb = A.union(&B).cloned().collect::<HashSet<i32>>();
    print_collection(&aUb);
 
    println!("A ∖ B -- difference; a set of all elements in set A, except those in set B.");
    let aDb = A.difference(&B).cloned().collect::<HashSet<i32>>();
    print_collection(&aDb);
 
    println!("A ⊆ B -- subset; true if every element in set A is also in set B.");
    println!("{}", A.is_subset(&B));
    let C = HashSet::from_iter(vec![14, 17, 18]);
    println!("{}", C.is_subset(&A));
 
    println!("A = B -- equality; true if every element of set A is in set B and vice versa.");
    println!("{}", A.eq(&B));
    let D = HashSet::from_iter(vec![4, 12, 14, 17, 18, 19, 20]);
    println!("{}", A.eq(&D));
 
    println!("If A ⊆ B, but A ≠ B, then A is called a true or proper subset of B, written A ⊂ B or A ⊊ B");
    println!("{}", A.is_proper_subset(&B));
    println!("{}", C.is_proper_subset(&A));
 
    println!("Modify a mutable set.  (Add 10 to A; remove 12 from B).");
    A.insert(10);
    B.remove(&12);
    print_collection(&A);
    print_collection(&B);
}

