fn make_list(separator: &str) -> String {
    let mut counter = 1;
 
    let make_item = |item: &str| {
        let result = format!("{} {} {}", counter, separator, item);
        counter += 1;
        result
    };
 
    format!(
        "{}\n{}\n{}\n",
        make_item("first"),
        make_item("second"),
        make_item("third")
    )
}
 
fn main() {
    println!("{}", make_list(". "));
}

use num::BigRational;
 
fn main() {
    for n in 0..=60 {
        let b = bernouilli(n);
        if b!= BigRational::new(0, 1) {
            println!("B({:2}) = {:1}", n, b);
        }
    }
}
 
fn bernouilli(n: i32) -> BigRational {
    let mut a = vec![BigRational::new(1, n + 1); n + 1];
    for m in 0..=n {
        for j in (1..=m).rev() {
            a[j - 1] = (a[j - 1] - a[j]) * BigRational::new(j, 1);
        }
    }
    a[0]
}

fn main() {
    let n = 121;
    let mut temp = n;
    let mut rev = 0;
    while temp!= 0 {
        let r = temp % 10;
        rev = rev * 10 + r;
        temp = temp / 10;
    }
    if n == rev {
        println!("Palindrome");
    } else {
        println!("Not Palindrome");
    }
}

