pub trait Animal {
    fn to_string(&self) -> String;
}
 
pub trait Dog: Animal {
    fn to_string(&self) -> String;
}
 
pub struct Cat;
 
impl Animal for Cat {
    fn to_string(&self) -> String {
        "cat".to_string()
    }
