use std::io;

async fn menu_select(question: &str, choices: &[&str]) -> String {
    if choices.is_empty() {
        return String::new();
    }

    let prompt = choices
       .iter()
       .enumerate()
       .map(|(i, choice)| format!("{}. {}\n", i + 1, choice))
       .collect::<String>();

    let mut input_choice = -1;
    while input_choice < 1 || input_choice > choices.len() as i32 {
        input_choice = get_selection(&format!("\n{}{}", prompt, question)).await;
    }

    choices[input_choice as usize - 1].to_string()
}

async fn get_selection(prompt: &str) -> i32 {
    let mut input = String::new();
    print!("{}", prompt);
    io::stdout().flush().unwrap();
    io::stdin().read_line(&mut input).unwrap();
    input.trim().parse::<i32>().unwrap_or(-1)
}

#[tokio::main]
async fn main() {
    let choices = ["fee fie", "huff and puff", "mirror mirror", "tick tock"];
    let question = "Which is from the three pigs?";
    let answer = menu_select(question, &choices).await;
    println!("\nYou chose {}", answer);
}

use std::f64::consts::PI;
 
fn main() {
    let mut i = 0;
    while i < 33 {
        let d = i as f64 * 11.25;
        let m = i % 3;
        let d = match m {
            1 => d + 5.62,
            2 => d - 5.62,
            _ => d,
        };
        let n = i % 32 + 1;
        println!("{:2} {:18} {:7.2}°", n, degrees2compasspoint(d), d);
        i += 1;
    }
}
 
fn degrees2compasspoint(d: f64) -> String {
    let d = (d % 360.0) + 360.0 / 64.0;
    let majorindex = (d / 90.0).floor() as usize;
    let minor = d - majorindex as f64 * 90.0;
    let minorindex = (minor * 4.0 / 45.0).floor() as usize;
    let p1 = match majorindex {
        0 => "north",
        1 => "east",
        2 => "south",
        3 => "west",
        _ => "error",
    };
    let p2 = match majorindex {
        0 => "east",
        1 => "south",
        2 => "west",
        3 => "north",
        _ => "error",
    };
    let q = if p1 == "north" || p1 == "south" {
        "N,N by E,N-NE,NE by N,NE,NE by E,E-NE,E by N".split(',')
    } else {
        "N,N by E,N-NE,NE by N,NE,NE by E,E-NE,E by N".split(',')
           .map(|s| s.replace("NE", "EN"))
           .collect::<Vec<&str>>()
           .iter()
    };
    let q = q.collect::<Vec<&str>>();
    let q = q[minorindex];
    let q = q.replace("N", p1).replace("E", p2);
    q.to_uppercase()
}

