use std::collections::HashSet;
 
fn get_divisors(n: i32) -> HashSet<i32> {
    let mut divs = HashSet::new();
    divs.insert(1);
    divs.insert(n);
    for i in 2..((n as f64).sqrt() as i32 + 1) {
        if n % i == 0 {
            divs.insert(i);
            let j = n / i;
            if i!= j {
                divs.insert(j);
            }
        }
    }
    divs
}
 
fn is_part_sum(divs: &HashSet<i32>, sum: i32) -> bool {
    if sum == 0 {
        return true;
    }
    let mut new_divs = divs.clone();
    let last = *divs.iter().last().unwrap();
    if last > sum {
        new_divs.remove(&last);
        return is_part_sum(&new_divs, sum);
    }
    is_part_sum(&new_divs, sum) || is_part_sum(&new_divs, sum - last)
}
 
fn is_zumkeller(n: i32) -> bool {
    let divs = get_divisors(n);
    let sum: i32 = divs.iter().sum();
    // if sum is odd can't be split into two partitions with equal sums
    if sum % 2 == 1 {
        return false;
    }
    // if n is odd use 'abundant odd number' optimization
    if n % 2 == 1 {
        let abundance = sum - 2 * n;
        return abundance > 0 && abundance % 2 == 0;
    }
    // if n and sum are both even check if there's a partition which totals sum / 2
    is_part_sum(&divs, sum / 2)
}
 
fn main() {
    println!("The first 220 Zumkeller numbers are:");
    let mut i = 2;
    let mut count = 0;
    while count < 220 {
        if is_zumkeller(i) {
            print!("{0:3} ", i);
            count += 1;
            if count % 20 == 0 {
                println!();
            }
        }
        i += 1;
    }
 
    println!("\nThe first 40 odd Zumkeller numbers are:");
    i = 3;
    count = 0;
    while count < 40 {
        if is_zumkeller(i) {
            print!("{0:5} ", i);
            count += 1;
            if count % 10 == 0 {
                println!();
            }
        }
        i += 2;
    }
 
    println!("\nThe first 40 odd Zumkeller numbers which don't end in 5 are:");
    i = 3;
    count = 0;
    while count < 40 {
        if i % 10!= 5 && is_zumkeller(i) {
            print!("{0:7} ", i);
            count += 1;
            if count % 8 == 0 {
                println!();
            }
        }
        i += 2;
    }
}

