#[derive(Debug)]
struct BinaryTreeNode {
    value: i32,
    left: Option<Box<BinaryTreeNode>>,
    right: Option<Box<BinaryTreeNode>>,
}

impl BinaryTreeNode {
    fn from_array(array: Vec<i32>) -> BinaryTreeNode {
        let mut array = array;
        let value = array.remove(0);
        let left = if array.len() > 0 {
            Some(Box::new(BinaryTreeNode::from_array(array.remove(0))))
        } else {
            None
        };
        let right = if array.len() > 0 {
            Some(Box::new(BinaryTreeNode::from_array(array.remove(0))))
        } else {
            None
        };
        BinaryTreeNode {
            value: value,
            left: left,
            right: right,
        }
    }
}

use std::collections::HashMap;
use std::collections::HashSet;
use std::collections::VecDeque;
 
#[derive(Debug)]
struct Node {
    id: usize,
    root: Option<usize>,
    succ: Vec<usize>,
}
 
fn from_edges(edges: &[(usize, usize)]) -> Vec<Node> {
    let mut nodes: HashMap<usize, Node> = HashMap::new();
    for (v, w) in edges {
        let v = nodes.entry(*v).or_insert(Node {
            id: *v,
            root: None,
            succ: Vec::new(),
        });
        let w = nodes.entry(*w).or_insert(Node {
            id: *w,
            root: None,
            succ: Vec::new(),
        });
        v.succ.push(w.id);
    }
    nodes.values().cloned().collect()
}
 
fn trajan(V: &mut [Node]) -> Vec<Vec<usize>> {
    let mut res = Vec::new();
    let mut S = VecDeque::new();
    let mut pos = 0;
 
    fn strongconnect(v: &mut Node, S: &mut VecDeque<usize>) {
        v.root = Some(pos);
        S.push_back(v.id);
 
        for w in &v.succ {
            if V[*w].root.is_none() {
                strongconnect(&mut V[*w], S);
            }
 
            if let Some(w_root) = V[*w].root {
                if w_root >= pos {
                    v.root = Some(v.root.unwrap().min(w_root));
                }
            }
        }
 
        if v.root.unwrap() == pos {
            let mut res = Vec::new();
            while let Some(w) = S.pop_back() {
                res.push(w);
                V[w].root = Some(-1);
            }
            res.reverse();
            res
        }
    }
 
    for v in V {
        if v.root.is_none() {
            res.push(strongconnect(v, &mut S));
        }
    }
    res
}
 
fn main() {
    let tables = [
        // table 1
        [(1, 2), (3, 1), (3, 6), (6, 7), (7, 6), (2, 3), (4, 2), (4, 3), (4, 5), (5, 6), (5, 4),
         (8, 5), (8, 7), (8, 6)],
        // table 2
        [
            ('A', 'B'),
            ('B', 'C'),
            ('C', 'A'),
            ('A', 'Other'),
        ],
    ];
 
    for table in tables.iter() {
        let mut V = from_edges(table);
        for g in trajan(&mut V) {
            println!("{:?}", g);
        }
        println!();
    }
}

