use std::char;

fn main() {
    let mut input = String::new();
    stdin().read_line(&mut input).unwrap();
    let input = input.trim();
    let mut robot = Robot::new();
    for ch in input.chars() {
        if ch.is_uppercase() {
            robot.key_press(KeyEvent::SHIFT);
            robot.key_press(ch as i32);
            robot.key_release(ch as i32);
            robot.key_release(KeyEvent::SHIFT);
        } else {
            let up_ch = char::from_u32(ch as u32).unwrap().to_uppercase().next().unwrap();
            robot.key_press(up_ch as i32);
            robot.key_release(up_ch as i32);
        }
    }
}

struct Robot {
    delay: u64,
}

impl Robot {
    fn new() -> Robot {
        Robot { delay: 10 }
    }

    fn key_press(&mut self, key_code: i32) {
        unsafe {
            ffi::keybd_event(key_code as u8, 0, 0, 0);
        }
        thread::sleep(Duration::from_millis(self.delay));
    }

    fn key_release(&mut self, key_code: i32) {
        unsafe {
            ffi::keybd_event(key_code as u8, 0, 2, 0);
        }
        thread::sleep(Duration::from_millis(self.delay));
    }
}

#[derive(Debug)]
enum KeyEvent {
