use std::fs;
use std::io::Read;
use std::cmp;
 
fn jaro_sim(str1: &str, str2: &str) -> f64 {
    if str1.is_empty() && str2.is_empty() {
        return 1.0;
    }
    if str1.is_empty() || str2.is_empty() {
        return 0.0;
    }
    let mut str1_matches = vec![false; str1.len()];
    let mut str2_matches = vec![false; str2.len()];
    let mut matches = 0.0;
    let mut transpositions = 0.0;
    let match_distance = cmp::max(str1.len(), str2.len()) / 2 - 1;
    for (i, c1) in str1.chars().enumerate() {
        let start = cmp::max(0, i - match_distance);
        let end = cmp::min(str2.len(), i + match_distance + 1);
        for k in start..end {
            if str2_matches[k] {
                continue;
            }
            if c1!= str2.chars().nth(k).unwrap() {
                continue;
            }
            str1_matches[i] = true;
            str2_matches[k] = true;
            matches += 1.0;
            break;
        }
    }
    if matches == 0.0 {
        return 0.0;
    }
    let mut k = 0;
    for (i, c1) in str1.chars().enumerate() {
        if!str1_matches[i] {
            continue;
        }
        while!str2_matches[k] {
            k += 1;
        }
        if c1!= str2.chars().nth(k).unwrap() {
            transpositions += 1.0;
        }
        k += 1;
    }
    transpositions /= 2.0;
    (matches / str1.len() as f64 + matches / str2.len() as f64 + (matches - transpositions) / matches) / 3.0
}
 
fn jaro_winkler_dist(s: &str, t: &str) -> f64 {
    let ls = s.len();
    let lt = t.len();
    let lmax = cmp::max(lt, ls);
    let l = (0..cmp::min(4, lmax))
       .filter(|i| s.chars().nth(*i).unwrap() == t.chars().nth(*i).unwrap())
       .count();
    let js = jaro_sim(s, t);
    let p = 0.1;
    let ws = js + l as f64 * p * (1.0 - js);
    1.0 - ws
}
 
fn main() {
    let misspelt = vec![
        "accomodate", "definately", "goverment", "occured", "publically", "recieve", "seperate",
        "untill", "wich",
    ];
    let mut words = fs::read_to_string("unixdict.txt").unwrap();
    words.retain(|c| c!= '\n');
    let words = words.split_whitespace().collect::<Vec<&str>>();
    for ms in misspelt {
        let mut closest = vec![];
        for w in &words {
            let jwd = jaro_winkler_dist(ms, w);
            if jwd < 0.15 {
                closest.push((jwd, w));
            }
        }
        println!("Misspelt word: {}", ms);
        closest.sort_by(|a, b| a.partial_cmp(b).unwrap());
        for (i, c) in closest.iter().take(6).enumerate() {
            println!("{:.4} {}", c.0, c.1);
            if i == 5 {
                break;
            }
        }
        println!();
    }
}

