use std::fs;
use std::path::Path;
use regex::Regex;

fn walk_directory_tree(folder: &Path, folder_name: &str, re_pattern: &str) {
    println!("Files in {} matching '{}':", folder_name, re_pattern);
    walk_directory_filter(folder, re_pattern);

    println!("Folders in {} matching '{}':", folder_name, re_pattern);
    walk_directory_filter(folder, re_pattern);

    for entry in fs::read_dir(folder).unwrap() {
        let entry = entry.unwrap();
        let path = entry.path();
        if path.is_dir() {
            walk_directory_tree(&path, &format!("{}/{}", folder_name, path.file_name().unwrap().to_str().unwrap()), re_pattern);
        }
    }
}

fn walk_directory_filter(folder: &Path, re_pattern: &str) {
    let re = Regex::new(re_pattern).unwrap();
    for entry in fs::read_dir(folder).unwrap() {
        let entry = entry.unwrap();
        let path = entry.path();
        if re.is_match(path.file_name().unwrap().to_str().unwrap()) {
            println!("{}", path.file_name().unwrap().to_str().unwrap());
        }
    }
}

fn main() {
    let dir = Path::new(".");
    walk_directory_tree(dir, dir.file_name().unwrap().to_str().unwrap(), "\\.txt$");
}

