use std::fmt;
use std::error::Error;
use std::rc::Rc;
use std::cell::RefCell;

#[derive(Debug)]
struct ExhaustedError;

impl fmt::Display for ExhaustedError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "amb tree exhausted")
    }
}

impl Error for ExhaustedError {
    fn description(&self) -> &str {
        "amb tree exhausted"
    }
}

struct Amb {
    fail: Rc<RefCell<Option<Box<Fn() -> () +'static>>>>,
}

impl Amb {
    fn new() -> Amb {
        Amb {
            fail: Rc::new(RefCell::new(None)),
        }
    }

    fn choose<T>(&self, choices: &[T]) -> T
        where T: Clone
    {
        let prev_fail = self.fail.clone();
        let mut sk = None;
        for choice in choices {
            let fk = self.fail.clone();
            let choice = choice.clone();
            let fail = move || {
                *fk.borrow_mut() = prev_fail.borrow().clone();
                sk.take().unwrap()();
            };
            sk = Some(callcc(move |cc: Continuation<T>| {
                *fk.borrow_mut() = Some(Box::new(fail));
                if choice.is_fn() {
                    cc.call(choice.call())
                } else {
                    cc.call(choice)
                }
            }));
        }
        sk.unwrap()();
        self.fail.borrow().as_ref().unwrap()();
        unreachable!()
    }

    fn failure(&self) ->! {
        self.choose(&[])
    }

    fn assert(&self, cond: bool) {
        if!cond {
            self.failure();
        }
    }
}

fn main() {
    let a = Amb::new();
    let w1 = a.choose(&["the", "that", "a"]);
    let w2 = a.choose(&["frog", "elephant", "thing"]);
    let w3 = a.choose(&["walked", "treaded", "grows"]);
    let w4 = a.choose(&["slowly", "quickly"]);

    a.assert(w1.ends_with(&w2[0..1]));
    a.assert(w2.ends_with(&w3[0..1]));
    a.assert(w3.ends_with(&w4[0..1]));

    println!("{} {} {} {}", w1, w2, w3, w4);
}

fn main() {
    let q = 929;
    if!is_prime(q) {
        return;
    }
    let mut r = q;
    while r > 0 {
        r <<= 1;
    }
    let mut d = 2 * q + 1;
    loop {
        let mut i = 1;
        let mut p = r;
        while p!= 0 {
            i = (i * i) % d;
            if p < 0 {
                i *= 2;
            }
            if i > d {
                i -= d;
            }
            p <<= 1;
        }
        if i!= 1 {
            d += 2 * q;
        } else {
            break;
        }
    }
    println!("2^{}-1 = 0 (mod {})", q, d);
}
 
fn is_prime(n: i32) -> bool {
    if n % 2 == 0 {
        return n == 2;
    }
    if n % 3 == 0 {
        return n == 3;
    }
    let mut d = 5;
    while d * d <= n {
        if n % d == 0 {
            return false;
        }
        d += 2;
        if n % d == 0 {
            return false;
        }
        d += 4;
    }
    true
}

