class MyClass {
public:
    int myInt;
 
    MyClass(int myInt) {
        this->myInt = myInt;
    }
 
    ~MyClass() {
        std::cout << "MyClass being finalized..." << std::endl;
    }
};
 
void myFun() {
    MyClass mc = MyClass(2); // new non-nullable MyClass object allocated on the stack
    std::cout << mc.myInt << std::endl;
    MyClass* mc2 = new MyClass(3); // new nullable MyClass object allocated on the heap
    std::cout << mc2->myInt << std::endl;
    delete mc2;
    mc2 = NULL; // allowed as mc2 is nullable
    std::cout << mc2->myInt << std::endl;
    //'mc' and'mc2' both become eligible for garbage collection here as no longer used
}
 
int main(int argc, char** argv) {
    myFun();
    std::this_thread::sleep_for(std::chrono::milliseconds(3000)); // allow time for GC to execute
    int i = 4; // new non-nullable Int allocated on stack
    std::cout << i << std::endl;
    int* j = new int(5); // new nullable Int allocated on heap
    std::cout << *j << std::endl;
    delete j;
    j = NULL; // allowed as 'j' is nullable
    std::cout << *j << std::endl;
    // 'j' becomes eligible for garbage collection here as no longer used
}

use std::cmp::Ordering;
use std::iter::Iterator;
 
fn cocktail_shaker_sort<I>(mut begin: I, mut end: I)
where
    I: Iterator,
    I::Item: Ord,
{
    if begin == end {
        return;
    }
    end = end.rev();
    loop {
        let mut new_begin = end.clone();
        let mut new_end = begin.clone();
        for i in begin.by_ref() {
            let j = i.clone();
            match i.cmp(&j) {
                Ordering::Less => {
                    new_end = i;
                }
                _ => {}
            }
        }
        end = new_end;
        for i in end.by_ref() {
            let j = i.clone();
            match i.cmp(&j) {
                Ordering::Less => {
                    new_begin = i;
                }
                _ => {}
            }
        }
        begin = new_begin;
        if begin == end {
            break;
        }
    }
}
 
fn print<I>(begin: I, end: I)
where
    I: Iterator,
    I::Item: std::fmt::Display,
{
    if begin == end {
        return;
    }
    print!("{}", begin.next().unwrap());
    for i in begin {
        print!(" {}", i);
    }
    println!();
}
 
fn main() {
    let mut v = vec![5, 1, -6, 12, 3, 13, 2, 4, 0, 15];
    println!("before: ");
    print(v.iter(), v.iter());
    cocktail_shaker_sort(v.iter_mut(), v.iter_mut());
    assert!(v.windows(2).all(|w| w[0] <= w[1]));
    println!("after: ");
    print(v.iter(), v.iter());
}

