use std::collections::HashMap;

fn best_shuffle(s: &str) -> (String, usize) {
    let mut pos: Vec<usize> = Vec::new();
    let mut g: HashMap<char, Vec<usize>> = HashMap::new();
    for (i, c) in s.chars().enumerate() {
        g.entry(c).or_insert(Vec::new()).push(i);
    }
    let mut k: Vec<char> = g.iter().collect();
    k.sort_by(|a, b| g.get(a).unwrap().len().cmp(&g.get(b).unwrap().len()));
    loop {
        let mut found = false;
        for c in k.iter() {
            if let Some(v) = g.get_mut(c) {
                pos.push(v.pop().unwrap());
                if v.is_empty() {
                    g.remove(c);
                }
                found = true;
            }
        }
        if!found {
            break;
        }
    }
    let mut letters = s.to_string();
    let mut new = String::from("?");
    while!letters.is_empty() {
        let mut i = 0;
        let p = pos.pop().unwrap();
        while i < letters.len() - 1 && letters.chars().nth(i).unwrap() == s.chars().nth(p).unwrap() {
            i += 1;
        }
        new.push(letters.remove(i));
    }
    let score = new.chars().zip(s.chars()).filter(|&(c, d)| c == d).count();
    (new, score)
}

fn main() {
    let words = vec!["abracadabra", "seesaw", "elk", "grrrrrr", "up", "a"];
    for word in words {
        let (new, score) = best_shuffle(word);
        println!("{}, {}, ({})", word, new, score);
    }
}

use std::collections::VecDeque;
 
struct TreeNode<T> {
    value: T,
    left: Option<Box<TreeNode<T>>>,
    right: Option<Box<TreeNode<T>>>,
}
 
impl<T> TreeNode<T> {
    fn new(value: T, left: Option<Box<TreeNode<T>>>, right: Option<Box<TreeNode<T>>>) -> TreeNode<T> {
        TreeNode {
            value: value,
            left: left,
            right: right,
        }
    }
 
    fn preorder_traverse(&self) {
        println!(" {}", self.value);
        if let Some(ref left) = self.left {
            left.preorder_traverse();
        }
        if let Some(ref right) = self.right {
            right.preorder_traverse();
        }
    }
 
    fn inorder_traverse(&self) {
        if let Some(ref left) = self.left {
            left.inorder_traverse();
        }
        println!(" {}", self.value);
        if let Some(ref right) = self.right {
            right.inorder_traverse();
        }
    }
 
    fn postorder_traverse(&self) {
        if let Some(ref left) = self.left {
            left.postorder_traverse();
        }
        if let Some(ref right) = self.right {
            right.postorder_traverse();
        }
        println!(" {}", self.value);
    }
 
    fn levelorder_traverse(&self) {
        let mut queue = VecDeque::new();
        queue.push_back(self);
 
        while!queue.is_empty() {
            let node = queue.pop_front().unwrap();
            println!(" {}", node.value);
 
            if let Some(ref left) = node.left {
                queue.push_back(left);
            }
            if let Some(ref right) = node.right {
                queue.push_back(right);
            }
        }
    }
}
 
fn main() {
    let root = TreeNode::new(1,
        Some(Box::new(TreeNode::new(2,
            Some(Box::new(TreeNode::new(4,
                Some(Box::new(TreeNode::new(7, None, None))),
                None))),
            Some(Box::new(TreeNode::new(5, None, None)))))),
        Some(Box::new(TreeNode::new(3,
            Some(Box::new(TreeNode::new(6,
                Some(Box::new(TreeNode::new(8, None, None))),
                Some(Box::new(TreeNode::new(9, None, None)))))),
            None))));
 
    println!("preorder:   ");
    root.preorder_traverse();
    println!("");
 
    println!("inorder:    ");
    root.inorder_traverse();
    println!("");
 
    println!("postorder:  ");
    root.postorder_traverse();
    println!("");
 
    println!("level-order:");
    root.levelorder_traverse();
    println!("");
}

use std::collections::HashMap;
use std::f64;
use std::io;
use std::io::Write;
use std::mem;
use std::ops::Index;
use std::ops::IndexMut;
use std::slice;
 
const LIMIT: usize = (f64::log(1e6) * 1e6 * 1.2) as usize;
 
fn main() {
    let primes = primes(LIMIT);
    let mut prev_cats = HashMap::new();
    let mut es = vec![Vec::new(); 12];
    println!("First 200 primes:\n");
    for p in &primes[0..200] {
        let c = cat(p, &primes, &mut prev_cats);
        es[c - 1].push(*p);
    }
    for c in 1..7 {
        if!es[c - 1].is_empty() {
            println!("Category {}:", c);
            println!("{:?}", es[c - 1]);
            println!();
        }
    }
    println!("First million primes:\n");
    for p in &primes[200..1_000_000] {
        let c = cat(p, &primes, &mut prev_cats);
        es[c - 1].push(*p);
    }
    for c in 1..13 {
        let e = &es[c - 1];
        if!e.is_empty() {
            println!("Category {:2}: First = {:7}  Last = {:8}  Count = {:6}",
                     c,
                     e[0],
                     e[e.len() - 1],
                     e.len());
        }
    }
}
 
fn cat(p: &usize, primes: &[usize], prev_cats: &mut HashMap<usize, usize>) -> usize {
    if let Some(&c) = prev_cats.get(p) {
        return c;
    }
    let pf = prime_factors(p + 1, primes);
    let mut all = true;
    for f in &pf {
        if *f!= 2 && *f!= 3 {
            all = false;
            break;
        }
    }
    if all {
        return 1;
    }
    if *p > 2 {
        let mut i = pf.len() - 1;
        while i >= 1 {
            if pf[i - 1] == pf[i] {
                pf.remove(i);
            }
            i -= 1;
        }
    }
    for c in 2..12 {
        let mut all = true;
        for f in &pf {
            if cat(f, primes, prev_cats) >= c {
                all = false;
                break;
            }
        }
        if all {
            prev_cats.insert(*p, c);
            return c;
        }
    }
    12
}
 
fn prime_factors(n: usize, primes: &[usize]) -> Vec<usize> {
    let mut n = n;
    let mut i = 0;
    let mut factors = Vec::new();
    while n > 1 {
        let p = primes[i];
        if n % p == 0 {
            factors.push(p);
            while n % p == 0 {
                n /= p;
            }
        }
        i += 1;
    }
    factors
}
 
fn primes(limit: usize) -> Vec<usize> {
    let mut sieve = vec![true; limit];
    sieve[0] = false;
    sieve[1] = false;
    let mut i = 2;
    while i * i < limit {
        if sieve[i] {
            let mut j = i * i;
            while j < limit {
                sieve[j] = false;
                j += i;
            }
        }
        i += 1;
    }
    let mut primes = Vec::new();
    for (i, &is_prime) in sieve.iter().enumerate() {
        if is_prime {
            primes.push(i);
        }
    }
    primes
}

