use std::io;
use std::io::Write;
use std::str;
 
//--------------------------------------------------------------------------------------------------
struct FloydsTri {
    rows: i32,
    last_line_len: Vec<u8>,
}
 
impl FloydsTri {
    fn new() -> FloydsTri {
        FloydsTri {
            rows: 0,
            last_line_len: Vec::new(),
        }
    }
 
    fn create(&mut self, rows: i32) {
        self.rows = rows;
        self.calculate_last_line_len();
        self.display();
    }
 
    fn calculate_last_line_len(&mut self) {
        self.last_line_len.clear();
        let s = 1 + (self.rows * (self.rows - 1)) / 2;
        for x in s..s + self.rows {
            self.last_line_len.push(x.to_string().len() as u8);
        }
    }
 
    fn display(&self) {
        println!("\nFloyd\'s Triangle - {} rows", self.rows);
        println!("===============================================");
        let mut number = 1;
        for r in 0..self.rows {
            for c in 0..=r {
                let str = number.to_string();
                let mut s = str.clone();
                while s.len() < self.last_line_len[c as usize] as usize {
                    s = " ".to_string() + &s;
                }
                print!("{} ", s);
                number += 1;
            }
            println!();
        }
    }
}
 
