use std::io;
 
fn divisor_count(n: u32) -> u32 {
    let mut total = 1;
    // Deal with powers of 2 first
    for _ in 0.. {
        if n & 1 == 0 {
            n >>= 1;
            total += 1;
        } else {
            break;
        }
    }
    // Odd prime factors up to the square root
    for p in (3..).step_by(2) {
        if p * p > n {
            break;
        }
        let mut count = 1;
        while n % p == 0 {
            n /= p;
            count += 1;
        }
        total *= count;
    }
    // If n > 1 then it's prime
    if n > 1 {
        total *= 2;
    }
    total
}
 
fn main() {
    let limit = 100;
    println!("Count of divisors for the first {} positive integers:", limit);
    for n in 1..=limit {
        print!("{:3}", divisor_count(n));
        if n % 20 == 0 {
            println!();
        }
    }
}

fn count_divisors(n: i32) -> i32 {
    let mut count = 0;
    for i in 1..=n {
        if n % i == 0 {
            if i == n / i {
                count += 1;
            } else {
                count += 2;
            }
        }
    }
    count
}
 
fn main() {
