    println!("The first {} terms of the sequence are:", MAX);
    for i in 1.. {
        if let Some(k) = (1..=MAX).find(|&k| count_divisors(i) == k && seq[k - 1] == 0) {
            seq[k - 1] = i;
            if seq.iter().all(|&x| x!= 0) {
                break;
            }
        }
    }
    println!("{:?}", seq);
}

