fn alignment(a: &str, b: &str) -> (String, String) {
    let a = a.to_lowercase();
    let b = b.to_lowercase();
    // i == 0
    let mut costs = vec![vec![0; b.len() + 1]; a.len() + 1];
    for j in 0..=b.len() {
        costs[0][j] = j;
    }
    for i in 1..=a.len() {
        costs[i][0] = i;
        for j in 1..=b.len() {
            costs[i][j] = std::cmp::min(
                1 + std::cmp::min(costs[i - 1][j], costs[i][j - 1]),
                if a.chars().nth(i - 1).unwrap() == b.chars().nth(j - 1).unwrap() {
                    costs[i - 1][j - 1]
                } else {
                    costs[i - 1][j - 1] + 1
                },
            );
        }
    }

    // walk back through matrix to figure out path
    let mut a_path_rev = String::new();
    let mut b_path_rev = String::new();
    let mut i = a.len();
    let mut j = b.len();
    while i!= 0 && j!= 0 {
        if costs[i][j] == (if a.chars().nth(i - 1).unwrap() == b.chars().nth(j - 1).unwrap() {
            costs[i - 1][j - 1]
        } else {
            costs[i - 1][j - 1] + 1
        }) {
            a_path_rev.push(a.chars().nth(i - 1).unwrap());
            b_path_rev.push(b.chars().nth(j - 1).unwrap());
            i -= 1;
            j -= 1;
        } else if costs[i][j] == 1 + costs[i - 1][j] {
            a_path_rev.push(a.chars().nth(i - 1).unwrap());
            b_path_rev.push('-');
            i -= 1;
        } else if costs[i][j] == 1 + costs[i][j - 1] {
            a_path_rev.push('-');
            b_path_rev.push(b.chars().nth(j - 1).unwrap());
            j -= 1;
        }
    }
    (a_path_rev.chars().rev().collect(), b_path_rev.chars().rev().collect())
}

