use std::cmp;
use std::collections::HashSet;
use std::env;
use std::fmt;
use std::io;
use std::io::Write;
use std::iter;
use std::mem;
use std::ops::Range;
use std::str;
 
const MAX_DEPTH: usize = 6;
const MAX_BASE: usize = 36;
const DIGITS: &'static str = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
 
fn main() {
    let mut max_strings = Vec::new();
    let mut most_bases = -1;
    let mut c = prime_sieve(MAX_BASE.pow(MAX_DEPTH as u32), true);
    for depth in 1..MAX_DEPTH + 1 {
        println!("{} character strings which are prime in most bases: ", depth);
        max_strings.clear();
        most_bases = -1;
        let mut indices = vec![0; depth];
        nested_for(&mut indices, MAX_BASE, 0, &mut c, &mut max_strings, &mut most_bases);
        print_results(&max_strings);
        println!();
    }
}
 
fn nested_for(
    indices: &mut [usize],
    length: usize,
    level: usize,
    c: &mut Vec<bool>,
    max_strings: &mut Vec<Vec<Vec<usize>>>,
    most_bases: &mut usize,
) {
    if level == indices.len() {
        process(indices, c, max_strings, most_bases);
    } else {
        indices[level] = 0;
        if level == 0 {
            indices[level] = 1;
        }
        while indices[level] < length {
            nested_for(indices, length, level + 1, c, max_strings, most_bases);
            indices[level] += 1;
        }
    }
}
 
fn process(
    indices: &[usize],
    c: &mut Vec<bool>,
    max_strings: &mut Vec<Vec<Vec<usize>>>,
    most_bases: &mut usize,
) {
    let min_base = cmp::max(2, max_slice(indices) + 1);
    if MAX_BASE - min_base + 1 < *most_bases {
        return; // can't affect results so return
    }
    let mut bases = Vec::new();
    for b in min_base..MAX_BASE + 1 {
        let mut n = 0;
        for &i in indices {
            n = n * b + i;
        }
        if!c[n] {
            bases.push(b);
        }
    }
    let count = bases.len();
    if count > *most_bases {
        *most_bases = count;
        let mut indices2 = Vec::new();
        indices2.extend_from_slice(indices);
        max_strings.clear();
        max_strings.push(vec![indices2, bases]);
    } else if count == *most_bases {
        let mut indices2 = Vec::new();
        indices2.extend_from_slice(indices);
        max_strings.push(vec![indices2, bases]);
    }
}
 
fn print_results(max_strings: &[Vec<Vec<usize>>]) {
    println!("{}", max_strings[0][1].len());
    for m in max_strings {
        let s = str::from_utf8(&m[0]).unwrap();
        println!("{} -> {:?}", s, m[1]);
    }
}
 
fn max_slice(a: &[usize]) -> usize {
    let mut max = 0;
    for &e in a {
        if e > max {
            max = e;
        }
    }
    max
}
 
fn prime_sieve(n: usize, include_one: bool) -> Vec<bool> {
    let mut c = vec![true; n + 1];
    c[0] = false;
    c[1] = include_one;
    let mut i = 2;
    while i * i <= n {
        if c[i] {
            let mut j = i * i;
            while j <= n {
                c[j] = false;
                j += i;
            }
        }
        i += 1;
    }
    c
}

