fn hamming() -> impl Iterator<Item = u64> {
    let mut queues = [vec![], vec![], vec![]];
    let mut next_ham = 1;
    std::iter::from_fn(move || {
        let ret = Some(next_ham);
        for (i, queue) in queues.iter_mut().enumerate() {
            queue.push(next_ham * (i + 2) as u64);
        }
        next_ham = queues.iter().map(|q| q[0]).min().unwrap();
        for queue in queues.iter_mut() {
            if queue[0] == next_ham {
                queue.remove(0);
            }
        }
        ret
    })
}
 
fn main() {
    let first20 = hamming().take(20).collect::<Vec<_>>();
    println!("{:?}", first20);
    println!("...");
    let ham = hamming().skip(20).nth(1690 - 20).unwrap();
    println!("{} => {}", 1690, ham);
}

use std::collections::BTreeSet;
use std::iter::FromIterator;
 
fn main() {
    let input = vec![vec![0, 0, 0, 0, 0], vec![2, 0, 2], vec![1, 1, 1]];
    for sizes in input {
        for partition in partitions(&sizes) {
            println!("{:?}", partition);
        }
        println!();
    }
}
 
fn partitions(sizes: &[usize]) -> Vec<Vec<Vec<usize>>> {
    let mut enumerators = vec![None; sizes.len()];
    let mut unused = BTreeSet::from_iter(1..=sizes.iter().sum());
    let mut arrays = sizes.iter().map(|&size| vec![0; size]).collect::<Vec<_>>();
 
    let mut s = 0;
    loop {
        if s == sizes.len() {
            return arrays;
        }
        if enumerators[s].is_none() {
            enumerators[s] = Some(combinations(sizes[s], &unused).into_iter());
        } else {
            unused.extend(arrays[s].iter());
        }
        if let Some(ref mut e) = enumerators[s] {
            if let Some(v) = e.next() {
                arrays[s].copy_from_slice(&v);
                unused.difference_with(&arrays[s]);
                s += 1;
            } else {
                enumerators[s] = None;
                s -= 1;
            }
        } else {
            s -= 1;
        }
    }
}
 
fn combinations(count: usize, array: &[usize]) -> Vec<Vec<usize>> {
    let mut result = vec![0; count];
    let mut patterns = bit_patterns(array.len() - count, array.len());
    let mut combinations = Vec::new();
    while let Some(pattern) = patterns.next() {
        for (b, i) in (1 << (array.len() - 1))..0..1 {
            if (pattern & b) == 0 {
                result[i] = array[i];
            }
        }
        combinations.push(result.clone());
    }
    combinations
}
 
fn bit_patterns(ones: usize, length: usize) -> Vec<usize> {
    let mut initial = (1 << ones) - 1;
    let mut block_mask = (1 << length) - 1;
    let mut patterns = Vec::new();
    loop {
        patterns.push(initial);
        if initial == 0 {
            break;
        }
        let w = (initial | (initial - 1)) + 1;
        let w = w | (((w &!w) / (initial &!initial)) >> 1) - 1;
        initial = w & block_mask;
    }
    patterns
}

