use rand::Rng;

fn ch960start_pos() -> [char; 8] {
    let mut rank = [0 as char; 8];
    let mut rng = rand::thread_rng();
    let mut empty_squares = Vec::new();
    for i in 0..8 {
        if rank[i] == 0 {
            empty_squares.push(i);
        }
    }
    // place one bishop on any black square
    rank[rng.gen_range(0, 2) * 2] = '♗';
    // place the other bishop on any white square
    rank[rng.gen_range(0, 2) * 2 + 1] = '♗';
    // place the queen on any empty square
    rank[empty_squares[rng.gen_range(0, 5)]] = '♕';
    // place one knight on any empty square
    rank[empty_squares[rng.gen_range(0, 4)]] = '♘';
    // place the other knight on any empty square
    rank[empty_squares[rng.gen_range(0, 3)]] = '♘';
    // place the rooks and the king on the squares left, king in the middle
    for x in 1..4 {
        rank[empty_squares[0]] = match x {
            1 => '♔',
            2 => '♖',
            3 => '♖',
            _ =>'',
        };
    }
    rank
}

fn main() {
    for _ in 0..10 {
        println!("{:?}", ch960start_pos());
    }
}

