fn main() {
    let (x, y, z) = (77444, -12, 0);

    //Sort directly:
    if x > y {
        (x, y) = (y, x);
    }
    if x > z {
        (x, z) = (z, x);
    }
    if y > z {
        (y, z) = (z, y);
    }
    println!("{:?}", (x, y, z));

    let (a, b, c) = (
        "lions, tigers, and",
        "bears, oh my!",
        "(from the 'Wizard of OZ')",
    );

    //Sort with generic method:
    sort(&mut a, &mut b, &mut c);
    println!("{:?}", (a, b, c));
}

fn sort<T: std::cmp::Ord>(a: &mut T, b: &mut T, c: &mut T) {
    if a > b {
        (a, b) = (b, a);
    }
    if a > c {
        (a, c) = (c, a);
    }
    if b > c {
        (b, c) = (c, b);
    }
}

use std::collections::HashMap;
use std::env;
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len()!= 2 {
        println!("Usage: {} <limit>", args[0]);
        process::exit(1);
    }
    let limit: i64 = args[1].parse().unwrap();
    let mut gap_starts: HashMap<i64, i64> = HashMap::new();
    let primes = rcu::primes(limit * 5);
    for i in 1..primes.len() {
        let gap = primes[i] - primes[i - 1];
        if!gap_starts.contains_key(&gap) {
            gap_starts.insert(gap, primes[i - 1]);
        }
    }
    let mut pm = 10;
    let mut gap1 = 2;
    loop {
        while!gap_starts.contains_key(&gap1) {
            gap1 += 2;
        }
        let start1 = gap_starts[&gap1];
        let gap2 = gap1 + 2;
        if!gap_starts.contains_key(&gap2) {
            gap1 = gap2 + 2;
            continue;
        }
        let start2 = gap_starts[&gap2];
        let diff = start2 - start1;
        if diff < 0 {
            pm = -diff;
        }
        if diff > pm {
            let cpm = rcu::commatize(pm);
            let cst1 = rcu::commatize(start1);
            let cst2 = rcu::commatize(start2);
            let cd = rcu::commatize(diff);
            println!(
                "Earliest difference > {} between adjacent prime gap starting primes:\n",
                cpm
            );
            println!(
                "Gap {} starts at {}, gap {} starts at {}, difference is {}.\n",
                gap1, cst1, gap2, cst2, cd
            );
            if pm == limit {
                break;
            }
            pm *= 10;
        } else {
            gap1 = gap2;
        }
    }
}

//using chained methods
fn reverse_str(s: &str) -> String {
    s.chars().rev().collect()
}
 
//fast method using for loop
fn reverse_str(s: &str) -> String {
    let mut o = String::new();
    for c in s.chars().rev() {
        o.push(c);
    }
    o
}
 
//fast method using while loop (faster with long strings in some browsers when compared with for loop)
fn reverse_str(s: &str) -> String {
    let mut o = String::new();
    let mut i = s.len();
    while i > 0 {
        i -= 1;
        o.push(s.chars().nth(i).unwrap());
    }
    o
}

