extern crate glutin;
extern crate gl;
 
use glutin::GlContext;
use glutin::GlRequest;
use glutin::WindowBuilder;
use glutin::EventsLoop;
use glutin::ContextBuilder;
use glutin::Api;
use glutin::GlProfile;
use glutin::GlRequest;
use glutin::GlWindow;
use glutin::Event;
use glutin::WindowEvent;
use glutin::ControlFlow;
 
fn paint() {
    unsafe {
        gl::ClearColor(0.3, 0.3, 0.3, 0.0);
        gl::Clear(gl::COLOR_BUFFER_BIT | gl::DEPTH_BUFFER_BIT);
 
        gl::ShadeModel(gl::SMOOTH);
 
        gl::LoadIdentity();
        gl::Translatef(-15.0, -15.0, 0.0);
 
        gl::Begin(gl::TRIANGLES);
        gl::Color3f(1.0, 0.0, 0.0);
        gl::Vertex2f(0.0, 0.0);
        gl::Color3f(0.0, 1.0, 0.0);
        gl::Vertex2f(30.0, 0.0);
        gl::Color3f(0.0, 0.0, 1.0);
        gl::Vertex2f(0.0, 30.0);
        gl::End();
 
        gl::Flush();
    }
}
 
fn reshape(width: i32, height: i32) {
    unsafe {
        gl::Viewport(0, 0, width, height);
        gl::MatrixMode(gl::PROJECTION);
        gl::LoadIdentity();
        gl::Ortho(-30.0, 30.0, -30.0, 30.0, -30.0, 30.0);
        gl::MatrixMode(gl::MODELVIEW);
    }
}
 
fn main() {
    let el = EventsLoop::new();
    let wb = WindowBuilder::new()
       .with_title("Triangle")
       .with_dimensions(640, 480);
    let context = ContextBuilder::new()
       .with_gl(GlRequest::Specific(Api::OpenGl, (3, 2)))
       .with_gl_profile(GlProfile::Core)
       .with_vsync(true);
    let window = GlWindow::new(wb, context, &el).unwrap();
 
    unsafe {
        window.make_current().unwrap();
        gl::load_with(|symbol| window.get_proc_address(symbol) as *const _);
    }
 
    el.run_forever(|event| {
        match event {
            Event::WindowEvent { event,.. } => match event {
                WindowEvent::CloseRequested => {
                    println!("The close button was pressed; stopping");
                    ControlFlow::Break
                },
                WindowEvent::Resized(logical_size) => {
                    let dpi_factor = window.get_hidpi_factor();
                    window.resize(logical_size.to_physical(dpi_factor));
                    reshape(logical_size.width as i32, logical_size.height as i32);
                    ControlFlow::Continue
                },
                _ => ControlFlow::Continue,
            },
            Event::MainEventsCleared => {
                window.swap_buffers().unwrap();
                paint();
                ControlFlow::Continue
            },
            _ => ControlFlow::Continue,
        }
    });
}

