use std::cmp;
use std::f64;
 
type Xint = u64;
 
static mut TENS: [Xint; 20] = [0; 20];
 
fn max(a: Xint, b: Xint) -> Xint {
    if a > b { a } else { b }
}
 
fn min(a: Xint, b: Xint) -> Xint {
    if a < b { a } else { b }
}
 
fn ndigits(x: Xint) -> i32 {
    let mut n = 0;
    let mut x = x;
    while x > 0 {
        n += 1;
        x /= 10;
    }
    n
}
 
fn dtally(x: Xint) -> Xint {
    let mut t = 0;
    let mut x = x;
    while x > 0 {
        t += 1 << ((x % 10) * 6);
        x /= 10;
    }
    t
}
 
fn fangs(x: Xint, f: &mut [Xint]) -> i32 {
    let mut n = 0;
    let nd = ndigits(x);
    if nd & 1!= 0 { return 0; }
    let nd = nd / 2;
    let mut lo = max(unsafe { TENS[nd-1] }, (x + unsafe { TENS[nd] } - 2) / (unsafe { TENS[nd] } - 1));
    let mut hi = min(x / lo, f64::sqrt(x as f64) as Xint);
    let mut a: Xint;
    let mut b: Xint;
    let mut t = dtally(x);
    for a in lo..hi+1 {
        b = x / a;
        if a * b == x && (a % 10!= 0 || b % 10!= 0) && t == dtally(a) + dtally(b) {
            f[n] = a;
            n += 1;
        }
    }
    n
}
 
fn show_fangs(x: Xint, f: &[Xint], cnt: i32) {
    print!("{} = ", x);
    let mut i = 0;
    while i < cnt {
        print!("{} x {} ", f[i], x / f[i]);
        i += 1;
    }
    println!("");
}
 
fn main() {
    let mut i: i32;
    let mut j: i32;
    let mut n: i32;
    let mut x: Xint;
    let mut f: [Xint; 16] = [0; 16];
    let bigs: [Xint; 4] = [16758243290880, 24959017348650, 14593825548650, 0];
    unsafe {
        TENS[0] = 1;
        for i in 1..20 {
            TENS[i] = TENS[i-1] * 10;
        }
    }
    for x in 1.. {
        if (j = fangs(x, &mut f)) == 0 { continue; }
        print!("{}: ", n);
        show_fangs(x, &f, j);
        n += 1;
        if n == 25 { break; }
    }
    println!("");
    for i in 0..3 {
        if (j = fangs(bigs[i], &mut f))!= 0 {
            show_fangs(bigs[i], &f, j);
        } else {
            println!("{} is not vampiric", bigs[i]);
        }
    }
}

