use std::io::{self, BufRead};
use std::fs::File;
use std::path::Path;
 
fn is_opp_plausible_word(word: &str) -> bool {
    if!word.contains("c") && word.contains("ei") {
        return true;
    }
    if word.contains("cie") {
        return true;
    }
    return false;
}
 
fn is_plausible_word(word: &str) -> bool {
    if!word.contains("c") && word.contains("ie") {
        return true;
    }
    if word.contains("cei") {
        return true;
    }
    return false;
}
 
fn is_plausible_rule(filename: &str) -> bool {
    let path = Path::new(filename);
    let file = match File::open(&path) {
        Err(why) => panic!("couldn't open {}: {}", path.display(), why),
        Ok(file) => file,
    };
    let mut true_count = 0;
    let mut false_count = 0;
    for line in io::BufReader::new(file).lines() {
        let word = line.unwrap();
        if is_plausible_word(&word) {
            true_count += 1;
        }
        else if is_opp_plausible_word(&word) {
            false_count += 1;
        }
    }
    println!("Plausible count: {}", true_count);
    println!("Implausible count: {}", false_count);
    return true_count > 2 * false_count;
}
 
fn main() {
    if is_plausible_rule("unixdict.txt") {
        println!("Rule is plausible.");
    }
    else {
        println!("Rule is not plausible.");
    }
}

use std::collections::VecDeque;
 
fn hcseq(n: usize) -> usize {
    let mut seq = VecDeque::from(vec![1, 1]);
    while seq.len() < n {
        let x = seq.back().unwrap();
        seq.push_back(seq[x-1] + seq[seq.len()-x]);
    }
    seq[n-1]
}
 
fn main() {
    let mut pow2 = 1;
    for i in 0..20 {
        let pow2next = 2*pow2;
        let mut max = 0.0;
        for n in pow2..pow2next {
            let anon = hcseq(n) as f64 / n as f64;
            if anon > max {
                max = anon;
            }
        }
        println!("maximum of a(n)/n between 2^{} ({}) and 2^{} ({}) is {}",
                 i, pow2, i+1, pow2next, max);
        pow2 = pow2next;
    }
}

fn cocktail_sort(a: &mut [i32]) {
    let mut swapped = true;
    while swapped {
        swapped = false;
        for i in 0..a.len() - 1 {
            if a[i] > a[i + 1] {
                a.swap(i, i + 1);
                swapped = true;
            }
        }
        if!swapped {
            break;
        }
        swapped = false;
        for i in (1..a.len()).rev() {
            if a[i] < a[i - 1] {
                a.swap(i, i - 1);
                swapped = true;
            }
        }
    }
}

