use std::f64::consts::PI;
 
const N: usize = 32;
const N2: usize = N * (N - 1) / 2;
const STEP: f64 = 0.05;
 
fn main() {
	let mut xval = [0.0; N];
	let mut t_sin = [0.0; N];
	let mut t_cos = [0.0; N];
	let mut t_tan = [0.0; N];
	let mut r_sin = [0.0; N2];
	let mut r_cos = [0.0; N2];
	let mut r_tan = [0.0; N2];
	for i in 0..N {
		xval[i] = i as f64 * STEP;
		t_sin[i] = xval[i].sin();
		t_cos[i] = xval[i].cos();
		t_tan[i] = t_sin[i] / t_cos[i];
	}
	for i in 0..N2 {
		r_sin[i] = std::f64::NAN;
		r_cos[i] = std::f64::NAN;
		r_tan[i] = std::f64::NAN;
	}
	println!("{:.14}", 6.0 * i_sin(0.5));
	println!("{:.14}", 3.0 * i_cos(0.5));
	println!("{:.14}", 4.0 * i_tan(1.0));
}
 
fn rho(x: &[f64], y: &[f64], r: &mut [f64], i: usize, n: usize) -> f64 {
	if n < 0 {
		return 0.0;
	}
	if n == 0 {
		return y[i];
	}
	let idx = (N - 1 - n) * (N - n) / 2 + i;
	if r[idx].is_nan() {
		r[idx] = (x[i] - x[i + n])
			/ (rho(x, y, r, i, n - 1) - rho(x, y, r, i + 1, n - 1))
			+ rho(x, y, r, i + 1, n - 2);
	}
	r[idx]
}
 
fn thiele(x: &[f64], y: &[f64], r: &mut [f64], xin: f64, n: usize) -> f64 {
	if n > N - 1 {
		return 1.0;
	}
	rho(x, y, r, 0, n) - rho(x, y, r, 0, n - 2)
		+ (xin - x[n]) / thiele(x, y, r, xin, n + 1)
}
 
fn i_sin(x: f64) -> f64 {
	thiele(&t_sin, &xval, &mut r_sin, x, 0)
}
 
fn i_cos(x: f64) -> f64 {
	thiele(&t_cos, &xval, &mut r_cos, x, 0)
}
 
fn i_tan(x: f64) -> f64 {
	thiele(&t_tan, &xval, &mut r_tan, x, 0)
}

//  version 1.0.5-2
 
fn is_prime(n: i32) -> bool {
    if n < 2 {
        return false;
    }
    if n % 2 == 0 {
        return n == 2;
    }
    if n % 3 == 0 {
        return n == 3;
    }
    let mut d: i32 = 5;
    while d * d <= n {
        if n % d == 0 {
            return false;
        }
        d += 2;
        if n % d == 0 {
            return false;
        }
        d += 4;
    }
    true
}
 
fn get_population_count(n: i32) -> i32 {
    if n <= 0 {
        return 0;
    }
    let mut nn = n;
    let mut sum = 0;
    while nn > 0 {
        sum += nn % 2;
        nn /= 2;
    }
    sum
}
 
fn is_pernicious(n: i32) -> bool {
    is_prime(get_population_count(n))
}
 
fn main() {
    let mut n = 1;
    let mut count = 0;
    println!("The first 25 pernicious numbers are:\n");
    loop {
        if is_pernicious(n) {
            print!("{} ", n);
            count += 1;
        }
        n += 1;
        if count == 25 {
            break;
        }
    }
    println!("\n");
    println!("The pernicious numbers between 888,888,877 and 888,888,888 inclusive are:\n");
    for i in 888888877..888888888 {
        if is_pernicious(i) {
            print!("{} ", i);
        }
    }
}

