use rand::Rng;
use std::io;
 
fn basic_stats(sample_size: i32) {
    if sample_size < 1 {
        return;
    }
    let mut r = vec![0.0; sample_size as usize];
    let mut h = vec![0; 10];
    /*
       Generate'sample_size' random numbers in the interval [0, 1)
       and calculate in which box they will fall when drawing the histogram
    */
    for i in 0..sample_size {
        r[i as usize] = rand::thread_rng().gen_range(0.0, 1.0);
        h[(r[i as usize] * 10.0) as usize] += 1;
    }
 
    // adjust one of the h[] values if necessary to ensure they sum to sample_size
    let mut adj = sample_size - h.iter().sum::<i32>();
    if adj!= 0 {
        for i in 0..10 {
            h[i as usize] += adj;
            if h[i as usize] >= 0 {
                break;
            }
            h[i as usize] -= adj;
        }
    }
 
    let mean = r.iter().sum::<f64>() / sample_size as f64;
    let sd = (r.iter().map(|x| (x - mean) * (x - mean)).sum::<f64>() / sample_size as f64).sqrt();
 
    // Draw a histogram of the data with interval 0.1 
    let mut num_stars: i32;
    // If sample size > 500 then normalize histogram to 500 
    let scale = if sample_size <= 500 { 1.0 } else { 500.0 / sample_size as f64 };
    println!("Sample size {}\n", sample_size);
    println!("  Mean {:1.6}  SD {:1.6}\n", mean, sd);
    for i in 0..10 {
        print!("  {:1.2} : ", i as f64 / 10.0);
        print!("{:5} ", h[i as usize]);
        num_stars = (h[i as usize] as f64 * scale + 0.5) as i32;
        println!("{}", "*".repeat(num_stars as usize));
    }
    println!();
}
 
fn main() {
    let sample_sizes = [100, 1_000, 10_000, 100_000];
    for sample_size in sample_sizes.iter() {
        basic_stats(*sample_size);
    }
}

