use std::time::{Duration, SystemTime};

const FIRST_YEAR: i32 = 1900;
const LAST_YEAR: i32 = 2100;
const _31_MONTHS: [i32; 7] = [1, 3, 5, 7, 8, 10, 12];

fn main() {
    let mut total_num = 0;
    let mut total_no_5_weekends = 0;

    for year in FIRST_YEAR..=LAST_YEAR {
        let mut has_5_weekends = false;

        for month in _31_MONTHS.iter() {
            let first_day = SystemTime::now()
               .duration_since(SystemTime::UNIX_EPOCH)
               .unwrap()
               .as_secs()
                + (year - 1970) as u64 * 31536000
                + (*month - 1) as u64 * 2678400;
            let first_day = SystemTime::UNIX_EPOCH + Duration::from_secs(first_day);
            let first_day = first_day.duration_since(SystemTime::UNIX_EPOCH).unwrap();
            let first_day = first_day.as_secs();
            let first_day = first_day / 86400;
            let first_day = first_day % 7;
            if first_day == 5 {
                total_num += 1;
                has_5_weekends = true;
                println!("{} - {}", year, month);
            }
        }

        if!has_5_weekends {
            total_no_5_weekends += 1;
        }
    }
    println!(
        "Total 5-weekend months between {} and {}: {}",
        FIRST_YEAR, LAST_YEAR, total_num
    );
    println!("Total number of years with no 5-weekend months {}", total_no_5_weekends);
}

