    run_matrix_chain_multiplication(vec![1, 5, 25, 30, 100, 70, 2, 1, 100, 250, 1, 1000, 2]);
    run_matrix_chain_multiplication(vec![1000, 1, 500, 12, 1, 700, 2500, 3, 2, 5, 14, 10]);
}
 
fn run_matrix_chain_multiplication(dims: Vec<i32>) {
    println!("Array Dimension  = {:?}", dims);
    println!("Cost             = {}", matrix_chain_order(&dims));
    println!("Optimal Multiply = {}", get_optimal_parenthesizations());
}
 
struct MatrixChainMultiplication {
    cost: Vec<Vec<i32>>,
    order: Vec<Vec<i32>>,
}
 
impl MatrixChainMultiplication {
    fn new(dims: &Vec<i32>) -> MatrixChainMultiplication {
        let n = dims.len() - 1;
        let mut cost = Vec::with_capacity(n);
        let mut order = Vec::with_capacity(n);
        for _ in 0..n {
            cost.push(Vec::with_capacity(n));
            order.push(Vec::with_capacity(n));
        }
        MatrixChainMultiplication {
            cost: cost,
            order: order,
        }
    }
 
    fn matrix_chain_order(&mut self, dims: &Vec<i32>) -> i32 {
        let n = dims.len() - 1;
        for len_minus_one in 1..n {
            for i in 0..n - len_minus_one {
                let j = i + len_minus_one;
                self.cost[i][j] = i32::MAX;
                for k in i..j {
                    let current_cost = self.cost[i][k] + self.cost[k+1][j] + dims[i]*dims[k+1]*dims[j+1];
                    if current_cost < self.cost[i][j] {
                        self.cost[i][j] = current_cost;
                        self.order[i][j] = k;
                    }
                }
            }
        }
        self.cost[0][n-1]
    }
 
    fn get_optimal_parenthesizations(&self) -> String {
        self.get_optimal_parenthesizations(0, self.order.len() - 1)
    }
 
    fn get_optimal_parenthesizations(&self, i: usize, j: usize) -> String {
        if i == j {
            format!("{}", (i as u8 + 65) as char)
        }
        else {
            let mut sb = String::new();
            sb.push('(');
            sb.push_str(&self.get_optimal_parenthesizations(i, self.order[i][j] as usize));
            sb.push_str(" * ");
            sb.push_str(&self.get_optimal_parenthesizations(self.order[i][j] as usize + 1, j));
            sb.push(')');
            sb
        }
    }
}

use std::cmp::Ordering;
use std::fmt;
 
#[derive(Debug, Clone, Copy)]
struct Range {
    lower: f64,
    upper: f64,
}
 
impl Range {
    fn norm(&self) -> Range {
        if self.lower > self.upper {
            Range {
                lower: self.upper,
                upper: self.lower,
            }
        } else {
            *self
        }
    }
}
 
impl fmt::Display for Range {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "[{}, {}]", self.lower, self.upper)
    }
}
 
impl Range {
    fn union(&self, r2: Range) -> Vec<Range> {
        if self.upper < r2.lower {
            return vec![*self, r2];
        }
        let r = Range {
            lower: self.lower,
            upper: self.upper.max(r2.upper),
        };
        vec![r]
    }
}
 
fn consolidate(rs: Vec<Range>) -> Vec<Range> {
    let mut rs = rs
       .into_iter()
       .map(|r| r.norm())
       .collect::<Vec<Range>>();
    let le = rs.len();
    if le < 2 {
        return rs;
    }
    rs.sort_by(|r1, r2| {
        if r1.lower < r2.lower {
            Ordering::Less
        } else if r1.lower > r2.lower {
            Ordering::Greater
        } else {
            Ordering::Equal
        }
    });
    if le == 2 {
        return rs[0].union(rs[1]);
    }
    for i in 0..le - 1 {
        for j in i + 1..le {
            let ru = rs[i].union(rs[j]);
            if ru.len() == 1 {
                rs[i] = ru[0];
                rs.remove(j);
                rs.shrink_to_fit();
                break;
            }
        }
    }
    rs
}
 
fn main() {
    let rss = vec![
        vec![Range {
            lower: 1.1,
            upper: 2.2,
        }],
        vec![
            Range {
                lower: 6.1,
                upper: 7.2,
            },
            Range {
                lower: 7.2,
                upper: 8.3,
            },
        ],
        vec![
            Range {
                lower: 4.0,
                upper: 3.0,
            },
            Range {
                lower: 2.0,
                upper: 1.0,
            },
        ],
        vec![
            Range {
                lower: 4.0,
                upper: 3.0,
            },
            Range {
                lower: 2.0,
                upper: 1.0,
            },
            Range {
                lower: -1.0,
                upper: -2.0,
            },
            Range {
                lower: 3.9,
                upper: 10.0,
            },
        ],
        vec![
            Range {
                lower: 1.0,
                upper: 3.0,
            },
            Range {
                lower: -6.0,
                upper: -1.0,
            },
            Range {
                lower: -4.0,
                upper: -5.0,
            },
            Range {
                lower: 8.0,
                upper: 2.0,
            },
            Range {
                lower: -6.0,
                upper: -6.0,
            },
        ],
    ];
    for rs in rss {
        let s = format!("{:?}", rs);
        print!("{:40} => ", &s[1..s.len() - 1]);
        let rs2 = consolidate(rs);
        let s = format!("{:?}", rs2);
        println!("{}", &s[1..s.len() - 1]);
    }
}

