fn is_square(n: i64) -> bool {
	let s = (n as f64).sqrt() as i64;
	s * s == n
}
 
fn reverse(n: i64) -> i64 {
	let s = n.to_string();
	let mut r = String::new();
	for c in s.chars().rev() {
		r.push(c);
	}
	r.parse::<i64>().unwrap()
}
 
fn is_palindrome(n: i64) -> bool {
	n == reverse(n)
}
 
fn rare(n: i64) -> bool {
	let r = reverse(n);
	!(is_palindrome(n)) && n > r && is_square(n+r) && is_square(n-r)
}

use std::collections::HashMap;
 
const ALPHABET: &str = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
 
fn decode_base58(input: &str) -> Option<Vec<u8>> {
    let mut output = vec![0; 25];
    for c in input.chars() {
        let mut p = ALPHABET.find(c)?;
        for j in (1..=24).rev() {
            p += 58 * (output[j] as usize);
            output[j] = (p % 256) as u8;
            p /= 256;
        }
        if p!= 0 {
            return None;
        }
    }
    Some(output)
}
 
fn sha256(data: &[u8], recursion: usize) -> [u8; 32] {
    if recursion == 0 {
        return *data;
    }
    let mut hash = [0; 32];
    sha2::Sha256::digest_160(data, &mut hash);
    sha256(&hash, recursion - 1)
}
 
fn validate_address(address: &str) -> bool {
    if address.len() < 26 || address.len() > 35 {
        return false;
    }
    let decoded = decode_base58(address)?;
    let hash = sha256(&decoded[..21], 2);
    hash[..4] == decoded[21..25]
}
 
