fn distance(a: &str, b: &str) -> usize {
    let a = a.to_lowercase();
    let b = b.to_lowercase();
    let mut costs = (0..b.len() + 1).collect::<Vec<usize>>();
    for i in 1..a.len() + 1 {
        let mut nw = i - 1;
        for j in 1..b.len() + 1 {
            let mut c = costs[j];
            costs[j] = [c + 1, costs[j - 1] + 1, if a.chars().nth(i - 1).unwrap() == b.chars().nth(j - 1).unwrap() { nw } else { nw + 1 }].iter().min().unwrap().clone();
            nw = c;
        }
    }
    costs[b.len()]
}
 
fn test() {
    let words = vec!["kitten", "sitting", "saturday", "sunday", "rosettacode", "raisethysword"];
    for i in 0..words.len() / 2 {
        println!("distance({}, {}) = {}", words[i * 2], words[i * 2 + 1], distance(words[i * 2], words[i * 2 + 1]));
    }
}
 
fn main() {
    test();
}

