use std::io::Error;
use std::path::Path;
use image::{ImageBuffer, RgbImage, Rgb};

fn main() -> Result<(), Error> {
    let img = image::open("example.png")?;
    let bwimg = to_black_and_white(&img);
    bwimg.save("example-bw.png")?;
    Ok(())
}

fn to_black_and_white(img: &RgbImage) -> RgbImage {
    let width = img.width();
    let height = img.height();

    let histo = compute_histogram(img);

    let median = get_median(width * height, &histo);

    let mut bwimg = ImageBuffer::new(width, height);
    for y in 0..height {
        for x in 0..width {
            let pixel = img.get_pixel(x, y);
            let luminance = luminance(pixel);
            let color = if luminance >= median {
                Rgb([255, 255, 255])
            } else {
                Rgb([0, 0, 0])
            };
            bwimg.put_pixel(x, y, color);
        }
    }
    bwimg
}

fn compute_histogram(img: &RgbImage) -> [usize; 256] {
    let width = img.width();
    let height = img.height();

    let mut histo = [0; 256];
    for y in 0..height {
        for x in 0..width {
            let pixel = img.get_pixel(x, y);
            let luminance = luminance(pixel);
            histo[luminance] += 1;
        }
    }
    histo
}

fn get_median(total: u32, histo: &[usize]) -> u8 {
    let mut median = 0;
    let mut sum = 0;
    for i in 0..histo.len() {
        sum += histo[i];
        if sum >= total / 2 {
            median = i as u8;
            break;
        }
    }
    median
}

fn luminance(pixel: &Rgb<u8>) -> u8 {
    let r = pixel[0];
    let g = pixel[1];
    let b = pixel[2];
    (r + g + b) / 3
}

use std::collections::HashSet;
 
fn is_happy(n: i32) -> bool {
    let mut cache = HashSet::new();
    let mut sum = 0;
    let mut n = n;
    while n!= 1 {
        if cache.contains(&n) {
            return false;
        }
        cache.insert(n);
        while n!= 0 {
            let digit = n % 10;
            sum += digit * digit;
            n /= 10;
        }
        n = sum;
        sum = 0;
    }
    true
}
 
fn main() {
    let mut num = 1;
    let mut happynums = Vec::new();
    while happynums.len() < 8 {
        if is_happy(num) {
            happynums.push(num);
        }
        num += 1;
    }
    println!("First 8 happy numbers : {:?}", happynums);
}

