const MAX: usize = 2200;
const MAX2: usize = MAX * MAX * 2;

fn main() {
    let mut found = vec![false; MAX + 1];
    let mut a2b2 = vec![false; MAX2 + 1];
    let mut s = 3;

    for a in 1..=MAX {
        let a2 = a * a;
        for b in a..=MAX {
            a2b2[a2 + b * b] = true;
        }
    }

    for c in 1..=MAX {
        let s1 = s;
        s += 2;
        let s2 = s;
        for d in c + 1..=MAX {
            if a2b2[s1] {
                found[d] = true;
            }
            s1 += s2;
            s2 += 2;
        }
    }

    println!("The values of d <= {} which can't be represented:", MAX);
