use rand::Rng;
 
const NMAX: usize = 20;
const TESTS: usize = 1000000;
 
fn avg(n: usize) -> f64 {
    let mut sum = 0.0;
    for _ in 0..TESTS {
        let mut v = [false; NMAX];
        let mut x = 0;
        while!v[x] {
            v[x] = true;
            sum += 1.0;
            x = rand::thread_rng().gen_range(0, n);
        }
    }
    sum / TESTS as f64
}
 
fn ana(n: usize) -> f64 {
    let nn = n as f64;
    let mut term = 1.0;
    let mut sum = 1.0;
    for i in (1..n).rev() {
        term *= i as f64 / nn;
        sum += term;
    }
    sum
}
 
fn main() {
    println!(" N    average    analytical    (error)");
    println!("===  =========  ============  =========");
    for n in 1..=NMAX {
        let a = avg(n);
        let b = ana(n);
        println!(
            "{:3}   {:6.4}   {:10.4}      ({:4.2}%)",
            n,
            a,
            b,
            (a - b).abs() / b * 100.0
        );
    }
}

// version 1.1.2
 
fn utf8_encode(code_point: i32) -> Vec<u8> {
    let mut bytes = Vec::new();
    if code_point <= 0x7F {
        bytes.push(code_point as u8);
    } else if code_point <= 0x7FF {
        bytes.push(((code_point >> 6) & 0x1F) as u8 | 0xC0);
        bytes.push((code_point & 0x3F) as u8 | 0x80);
    } else if code_point <= 0xFFFF {
        bytes.push(((code_point >> 12) & 0x0F) as u8 | 0xE0);
        bytes.push(((code_point >> 6) & 0x3F) as u8 | 0x80);
        bytes.push((code_point & 0x3F) as u8 | 0x80);
    } else if code_point <= 0x10FFFF {
        bytes.push(((code_point >> 18) & 0x07) as u8 | 0xF0);
        bytes.push(((code_point >> 12) & 0x3F) as u8 | 0x80);
        bytes.push(((code_point >> 6) & 0x3F) as u8 | 0x80);
        bytes.push((code_point & 0x3F) as u8 | 0x80);
    }
    bytes
}
 
fn utf8_decode(bytes: &[u8]) -> i32 {
    let mut code_point = 0;
    let mut i = 0;
    let mut byte = bytes[i];
    if byte <= 0x7F {
        code_point = byte as i32;
    } else if byte <= 0xDF {
        code_point = (byte & 0x1F) as i32;
        i += 1;
        byte = bytes[i];
        code_point = (code_point << 6) | (byte & 0x3F) as i32;
    } else if byte <= 0xEF {
        code_point = (byte & 0x0F) as i32;
        i += 1;
        byte = bytes[i];
        code_point = (code_point << 6) | (byte & 0x3F) as i32;
        i += 1;
        byte = bytes[i];
        code_point = (code_point << 6) | (byte & 0x3F) as i32;
    } else if byte <= 0xF7 {
        code_point = (byte & 0x07) as i32;
        i += 1;
        byte = bytes[i];
        code_point = (code_point << 6) | (byte & 0x3F) as i32;
        i += 1;
        byte = bytes[i];
        code_point = (code_point << 6) | (byte & 0x3F) as i32;
        i += 1;
        byte = bytes[i];
        code_point = (code_point << 6) | (byte & 0x3F) as i32;
    }
    code_point
}
 
fn main() {
    let code_points = [0x0041, 0x00F6, 0x0416, 0x20AC, 0x1D11E];
    println!("Char  Name                                 Unicode  UTF-8         Decoded");
    for code_point in code_points.iter() {
        let n = if *code_point <= 0xFFFF { 4 } else { 5 };
        print!("{:width$}  ", code_point, width = n);
        print!("{:35}  U+{:05X}  ",
               std::char::from_u32(*code_point).unwrap().name(),
               code_point);
        let bytes = utf8_encode(*code_point);
        let mut s = String::new();
        for byte in bytes.iter() {
            s.push_str(&format!("{:02X} ", byte));
        }
        let decoded = utf8_decode(&bytes);
        let n = if decoded <= 0xFFFF { 12 } else { 11 };
        println!("{:width$}  {}", s, std::char::from_u32(decoded as u32).unwrap(), width = n);
    }
}

use std::f64::consts::PI;
use std::ops::{Add, Sub, Mul, Div, PartialEq};
use std::fmt;
 
#[derive(Debug)]
struct Vector {
    x: f64,
    y: f64,
}
 
impl Vector {
    fn new(x: f64, y: f64) -> Vector {
        Vector { x: x, y: y }
    }
}
 
impl Add for Vector {
    type Output = Vector;
    fn add(self, other: Vector) -> Vector {
        Vector { x: self.x + other.x, y: self.y + other.y }
    }
}
 
impl Sub for Vector {
    type Output = Vector;
    fn sub(self, other: Vector) -> Vector {
        Vector { x: self.x - other.x, y: self.y - other.y }
    }
}
 
impl Mul<f64> for Vector {
    type Output = Vector;
    fn mul(self, other: f64) -> Vector {
        Vector { x: self.x * other, y: self.y * other }
    }
}
 
impl Div<f64> for Vector {
    type Output = Vector;
    fn div(self, other: f64) -> Vector {
        Vector { x: self.x / other, y: self.y / other }
    }
}
 
impl PartialEq for Vector {
    fn eq(&self, other: &Vector) -> bool {
        self.x == other.x && self.y == other.y
    }
}
 
impl fmt::Display for Vector {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "X: {} Y: {}", self.x, self.y)
    }
}
 
fn main() {
    let vec1 = Vector::new(0.0, 1.0);
    let vec2 = Vector::new(2.0, 2.0);
    let vec3 = Vector::new(2.0_f64.sqrt(), 45.0 * PI / 180.0);
    println!("{}", vec3);
    assert!(vec1 + vec2 == Vector::new(2.0, 3.0));
    assert!(vec1 - vec2 == Vector::new(-2.0, -1.0));
    assert!(vec1 * 5.0 == Vector::new(0.0, 5.0));
    assert!(vec2 / 2.0 == Vector::new(1.0, 1.0));
}

// version 1.0.6

use std::cmp::Ordering;

#[derive(Debug)]
struct Oid {
    id: String,
}

impl Oid {
    fn new(id: &str) -> Self {
        Oid {
            id: id.to_string(),
        }
    }
}

impl Ord for Oid {
    fn cmp(&self, other: &Self) -> Ordering {
        let splits1: Vec<&str> = self.id.split('.').collect();
        let splits2: Vec<&str> = other.id.split('.').collect();
        let min_size = if splits1.len() < splits2.len() {
            splits1.len()
        } else {
            splits2.len()
        };
        for i in 0..min_size {
            let a = splits1[i].parse::<i32>().unwrap();
            let b = splits2[i].parse::<i32>().unwrap();
            if a < b {
                return Ordering::Less;
            } else if a > b {
                return Ordering::Greater;
            }
        }
        splits1.len().cmp(&splits2.len())
    }
}

impl PartialOrd for Oid {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl PartialEq for Oid {
    fn eq(&self, other: &Self) -> bool {
        self.cmp(other) == Ordering::Equal
    }
}

impl Eq for Oid {}

fn main() {
    let oids = vec![
        Oid::new("1.3.6.1.4.1.11.2.17.19.3.4.0.10"),
        Oid::new("1.3.6.1.4.1.11.2.17.5.2.0.79"),
        Oid::new("1.3.6.1.4.1.11.2.17.19.3.4.0.4"),
        Oid::new("1.3.6.1.4.1.11150.3.4.0.1"),
        Oid::new("1.3.6.1.4.1.11.2.17.19.3.4.0.1"),
        Oid::new("1.3.6.1.4.1.11150.3.4.0"),
    ];
    println!("{:?}", oids.iter().sorted().collect::<Vec<&Oid>>());
}

