use std::io;

fn minor(a: &Vec<Vec<f64>>, x: usize, y: usize) -> Vec<Vec<f64>> {
    let length = a.len() - 1;
    let mut result = vec![vec![0.0; length]; length];
    for i in 0..length {
        for j in 0..length {
            if i < x && j < y {
                result[i][j] = a[i][j];
            } else if i >= x && j < y {
                result[i][j] = a[i + 1][j];
            } else if i < x && j >= y {
                result[i][j] = a[i][j + 1];
            } else {
                result[i][j] = a[i + 1][j + 1];
            }
        }
    }
    result
}

fn det(a: &Vec<Vec<f64>>) -> f64 {
    if a.len() == 1 {
        return a[0][0];
    } else {
        let mut sign = 1;
        let mut sum = 0.0;
        for i in 0..a.len() {
            sum += sign as f64 * a[0][i] * det(&minor(&a, 0, i));
            sign *= -1;
        }
        return sum;
    }
}

fn perm(a: &Vec<Vec<f64>>) -> f64 {
    if a.len() == 1 {
        return a[0][0];
    } else {
        let mut sum = 0.0;
        for i in 0..a.len() {
            sum += a[0][i] * perm(&minor(&a, 0, i));
        }
        return sum;
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_line(&mut input).unwrap();
    let size: usize = input.trim().parse().unwrap();
    let mut a = vec![vec![0.0; size]; size];
    for i in 0..size {
        for j in 0..size {
            let mut input = String::new();
            io::stdin().read_line(&mut input).unwrap();
            a[i][j] = input.trim().parse().unwrap();
        }
    }
    println!("Determinant: {}", det(&a));
    println!("Permanent: {}", perm(&a));
}

