use rand::Rng;
use std::env;
use std::process;
 
const LOWER: &str = "abcdefghijklmnopqrstuvwxyz";
const UPPER: &str = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
const DIGITS: &str = "0123456789";
const SYMBOLS: &str = "!\"#$%&'()*+,-./:;<=>?@[]^_{|}~";
const FULL: [&str; 5] = [LOWER, UPPER, DIGITS, SYMBOLS, LOWER.to_owned() + UPPER + DIGITS + SYMBOLS];
 
const SIMILAR: &str = "Il1O05S2Z";
const EXCLUDED: [&str; 5] = [
    LOWER.chars().filter(|&c|!SIMILAR.contains(c)).collect::<String>().as_str(),
    UPPER.chars().filter(|&c|!SIMILAR.contains(c)).collect::<String>().as_str(),
    DIGITS.chars().filter(|&c|!SIMILAR.contains(c)).collect::<String>().as_str(),
    SYMBOLS.chars().filter(|&c|!SIMILAR.contains(c)).collect::<String>().as_str(),
    LOWER
       .to_owned()
       .chars()
       .chain(UPPER.chars())
       .chain(DIGITS.chars())
       .chain(SYMBOLS.chars())
       .filter(|&c|!SIMILAR.contains(c))
       .collect::<String>()
       .as_str(),
];
 
fn main() {
    let mut length = 12;
    let mut count = 1;
    let mut rng = rand::thread_rng();
    let mut symbol_set = &FULL;
 
    for arg in env::args().skip(1) {
        let mut parts = arg.split(':');
        let key = parts.next().unwrap();
        let value = parts.next().unwrap();
        match key {
            "-l" => length = value.parse().unwrap(),
            "-c" => count = value.parse().unwrap(),
            "-s" => rng = rand::SeedableRng::seed_from_u64(value.parse().unwrap()),
            "-x" => symbol_set = if value == "true" { &EXCLUDED } else { &FULL },
            _ => {
                show_usage();
                process::exit(1);
            }
        }
    }
 
    for _ in 0..count {
        println!("{}", generate_pass(length, &mut rng, symbol_set));
    }
}
 
fn show_usage() {
    println!("Usage: PASSGEN [-l:length] [-c:count] [-s:seed] [-x:(true|false)]");
    println!("\t-l: the length of the generated passwords");
    println!("\t-c: the number of passwords to generate");
    println!("\t-s: seed for the random number generator");
    println!("\t-x: exclude similar characters: {}", SIMILAR);
    println!("Example: PASSGEN -l:10 -c:5 -s:\"Sample Seed\" -x:true");
}
 
fn generate_pass(length: usize, rng: &mut impl Rng, symbol_set: &[&str]) -> String {
    let min_length = symbol_set.len() - 1;
    if length < min_length {
        panic!("password length must be {} or greater", min_length);
    }
 
    let mut uses_remaining = vec![1; symbol_set.len()];
    uses_remaining[min_length] = length - min_length;
    let mut password = vec![' '; length];
    for ii in 0..length {
        let set = rng.gen_range(0, symbol_set.len());
        if uses_remaining[set] > 0 {
            uses_remaining[set] -= 1;
            password[ii] = symbol_set[set].chars().nth(rng.gen_range(0, symbol_set[set].len())).unwrap();
        } else {
            ii -= 1;
        }
    }
    password.into_iter().collect()
}

fn vdc(mut n: u64, base: u64) -> f64 {
    let mut vdc = 0.0;
    let mut denom = 1.0;
    while n > 0 {
        denom *= base as f64;
        let (n, remainder) = (n / base, n % base);
        vdc += (remainder as f64) / denom;
    }
    vdc
}

fn pancake_sort(a: &mut [i32]) {
    fn index_of_max(a: &[i32], n: usize) -> usize {
        (0..n).max_by_key(|&i| a[i]).unwrap()
    }

    fn flip(a: &mut [i32], index: usize) {
        a.reverse(0..=index);
    }

    for n in (1..a.len()).rev() {
        let index = index_of_max(a, n);
        if index!= n - 1 {
            if index > 0 {
                flip(a, index);
                println!("{:?} after flipping first {}", a, index + 1);
            }
            flip(a, n - 1);
            println!("{:?} after flipping first {}", a, n);
        }
    }
}

fn main() {
    let mut a = [7, 6, 9, 2, 4, 8, 1, 3, 5];
    println!("{:?} initially", a);
    pancake_sort(&mut a);
}

