    let ok = at.is_none();
    let p = if ok { 0 } else { at.unwrap() + 1 };
    let v = if ok { "" } else { arr[at.unwrap()].to_string() };
    let vs = if v == "" { v } else { format!("\"{}\"", v) };
    let h = if ok { "" } else { format!("0x{:x}", v.chars().next().unwrap() as u32) };
    println!("\"{}\" => Length:{}\tSame:{}\tPos:{}\tChar:{}\tHex:{}", s, l, ok, p, vs, h);
}

