use std::f64;
use std::str::FromStr;

fn main() {
    let input = "3 4 2 * 1 5 - 2 3 ^ ^ / +";
    println!("For postfix {}", input);
    println!("\nToken            Action            Stack");
    let mut stack: Vec<f64> = Vec::new();
    for tok in input.split_whitespace() {
        let action = "Apply op to top of stack";
        match tok {
            "+" => {
                stack[stack.len() - 2] += stack[stack.len() - 1];
                stack.pop();
            }
            "-" => {
                stack[stack.len() - 2] -= stack[stack.len() - 1];
                stack.pop();
            }
            "*" => {
                stack[stack.len() - 2] *= stack[stack.len() - 1];
                stack.pop();
            }
            "/" => {
                stack[stack.len() - 2] /= stack[stack.len() - 1];
                stack.pop();
            }
            "^" => {
                stack[stack.len() - 2] = f64::powf(stack[stack.len() - 2], stack[stack.len() - 1]);
                stack.pop();
            }
            _ => {
                action = "Push num onto top of stack";
                let f = f64::from_str(tok).unwrap();
                stack.push(f);
            }
        }
        println!("{:<3}    {:26}  {:?}", tok, action, stack);
    }
    println!("\nThe final value is {}", stack[0]);
}

use std::collections::BinaryHeap;
use std::collections::HashMap;
use std::cmp::Ordering;
 
#[derive(Debug, Clone)]
enum Node {
    Char(char),
    Branch(Box<Node>, Box<Node>),
}
 
impl PartialEq for Node {
    fn eq(&self, other: &Node) -> bool {
        match (self, other) {
            (&Node::Char(c1), &Node::Char(c2)) => c1 == c2,
            (&Node::Branch(ref l1, ref r1), &Node::Branch(ref l2, ref r2)) => {
                l1 == l2 && r1 == r2
            }
            _ => false,
        }
    }
}
 
impl Eq for Node {}
 
impl PartialOrd for Node {
    fn partial_cmp(&self, other: &Node) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
 
impl Ord for Node {
    fn cmp(&self, other: &Node) -> Ordering {
        match (self, other) {
            (&Node::Char(c1), &Node::Char(c2)) => c1.cmp(&c2),
            (&Node::Branch(ref l1, ref r1), &Node::Branch(ref l2, ref r2)) => {
                l1.cmp(l2).then(r1.cmp(r2))
            }
            (&Node::Char(_), &Node::Branch(_, _)) => Ordering::Less,
            (&Node::Branch(_, _), &Node::Char(_)) => Ordering::Greater,
        }
    }
}
 
fn huffman_encoding(str: &str) -> HashMap<char, String> {
    let mut char_count = HashMap::new();
    for c in str.chars() {
        *char_count.entry(c).or_insert(0) += 1;
    }
 
    let mut pq = BinaryHeap::new();
    for (char, count) in char_count {
        pq.push(Node::Char(char));
    }
 
    while pq.len() > 1 {
        let key1 = pq.pop().unwrap();
        let key2 = pq.pop().unwrap();
        pq.push(Node::Branch(Box::new(key1), Box::new(key2)));
    }
 
    let mut encoding = HashMap::new();
    generate_encoding(&pq.pop().unwrap(), &mut encoding, "");
    encoding
}
 
fn generate_encoding(node: &Node, encoding: &mut HashMap<char, String>, prefix: &str) {
    match node {
        &Node::Char(c) => {
            encoding.insert(c, prefix.to_string());
        }
        &Node::Branch(ref l, ref r) => {
            generate_encoding(l, encoding, &format!("{}0", prefix));
            generate_encoding(r, encoding, &format!("{}1", prefix));
        }
    }
}
 
fn encode(str: &str, encoding: &HashMap<char, String>) -> String {
    str.chars()
       .map(|c| encoding.get(&c).unwrap().to_string())
       .collect::<Vec<String>>()
       .join("")
}
 
fn decode(encoded: &str, encoding: &HashMap<char, String>) -> String {
    let mut rev_enc = HashMap::new();
    for (char, code) in encoding {
        rev_enc.insert(code, char);
    }
 
    let mut decoded = String::new();
    let mut pos = 0;
    while pos < encoded.len() {
        let mut key = String::new();
        while rev_enc.get(&key).is_none() {
            key.push(encoded.chars().nth(pos).unwrap());
            pos += 1;
        }
        decoded.push(*rev_enc.get(&key).unwrap());
    }
    decoded
}
 
fn main() {
    let str = "this is an example for huffman encoding";
    let encoding = huffman_encoding(str);
    for (char, code) in encoding.iter() {
        println!("{:?} {:?}", char, code);
    }
 
    let enc = encode(str, &encoding);
    let dec = decode(&enc, &encoding);
    println!("success!");
}

