const POINTS: [(u32, u32); 3] = [(WIDTH / 2, MARGIN), (MARGIN, SIZE), (MARGIN + SIZE, SIZE)];
const COLORS: [Color; 3] = [Color::RGB(255, 0, 0), Color::RGB(0, 255, 0), Color::RGB(0, 0, 255)];
 
fn main() {
    let sdl_context = sdl2::init().unwrap();
    let video_subsystem = sdl_context.video().unwrap();
    let window = video_subsystem
       .window("Chaos Game", WIDTH, HEIGHT)
       .position_centered()
       .build()
       .unwrap();
    let mut canvas = window.into_canvas().build().unwrap();
    let texture_creator = canvas.texture_creator();
    let mut texture = texture_creator.create_texture_target(None, WIDTH, HEIGHT).unwrap();
    let mut rng = StdRng::from_entropy();
    let mut stack = VecDeque::new();
    stack.push_back(Point::new(-1, -1));
 
    let mut event_pump = sdl_context.event_pump().unwrap();
    'running: loop {
        for event in event_pump.poll_iter() {
            match event {
                Event::Quit {.. }
                | Event::KeyDown {
                    keycode: Some(Keycode::Escape),
                   ..
                } => break 'running,
                _ => {}
            }
        }
 
        let start = Instant::now();
        for _ in 0..1000 {
            let color_index = rng.gen_range(0, 3);
            let p1 = stack.back().unwrap();
            let p2 = &POINTS[color_index];
            stack.push_back(halfway_point(p1, p2, color_index));
        }
        let elapsed = start.elapsed();
        println!("Elapsed: {:?}", elapsed);
 
        canvas.set_draw_color(Color::RGB(255, 255, 255));
        canvas.clear();
        draw_points(&mut canvas, &mut texture, &stack);
        canvas.present();
    }
}
 
fn draw_points(canvas: &mut Canvas<Window>, texture: &mut Texture, stack: &VecDeque<Point>) {
    for cp in stack {
        canvas.set_draw_color(COLORS[cp.y as usize]);
        canvas.draw_point(Point::new(cp.x, cp.y)).unwrap();
    }
}
 
fn halfway_point(a: &Point, b: &(u32, u32), idx: usize) -> Point {
    Point::new((a.x + b.0) / 2, (a.y + b.1) / 2)
}

