fn main() {
    let mut rng = thread_rng();
    let mut n: VecDeque<char> = (1..10).map(|_| (rng.gen_range(0, 9) + '1' as u8) as char).collect();
    println!("Your numbers: {:?}", n);
    print!("Enter RPN: ");
    io::stdout().flush().unwrap();
    let mut expr = String::new();
    io::stdin().read_line(&mut expr).unwrap();
    if expr.len()!= 7 {
        println!("invalid. expression length must be 7. (4 numbers, 3 operators, no spaces)");
        return;
    }
    let mut stack: Vec<f64> = Vec::new();
    for r in expr.chars() {
        if r >= '0' && r <= '9' {
            if n.len() == 0 {
                println!("too many numbers.");
                return;
            }
            let mut i = 0;
            while n[i]!= r {
                i += 1;
                if i == n.len() {
                    println!("wrong numbers.");
                    return;
                }
            }
            n.remove(i);
            stack.push((r as u8 - '0' as u8) as f64);
            continue;
        }
        if stack.len() < 2 {
            println!("invalid expression syntax.");
            return;
        }
        match r {
            '+' => stack[stack.len() - 2] += stack[stack.len() - 1],
            '-' => stack[stack.len() - 2] -= stack[stack.len() - 1],
            '*' => stack[stack.len() - 2] *= stack[stack.len() - 1],
            '/' => stack[stack.len() - 2] /= stack[stack.len() - 1],
            _ => {
                println!("{} invalid.", r);
                return;
            }
        }
        stack.pop();
    }
    if (stack[0] - 24.0).abs() > 1e-6 {
        println!("incorrect. {}!= 24", stack[0]);
    } else {
        println!("correct.");
    }
}

use std::iter::Peekable;
use std::str::Chars;
 
fn collapser(txt: &str) -> String {
    let mut chars = txt.chars().peekable();
    let mut result = String::new();
    while let Some(c) = chars.next() {
        result.push(c);
        while let Some(&next) = chars.peek() {
            if c!= next {
                break;
            }
            chars.next();
        }
    }
    result
}
 
fn main() {
    let strings = vec![
        "",
