use std::cmp::Ordering;
use std::mem::swap;

fn dnf_partition<T: Ord>(first: &mut [T], low: T, high: T) {
    let mut next = 0;
    let mut last = first.len();
    while next < last {
        match first[next].cmp(&low) {
            Ordering::Less => {
                swap(&mut first[next], &mut first[0]);
                next += 1;
            }
            Ordering::Greater => {
                last -= 1;
                swap(&mut first[next], &mut first[last]);
            }
            Ordering::Equal => {
                next += 1;
            }
        }
    }
}

