use rand::Rng;
use std::collections::HashSet;
 
fn play_optimal() -> bool {
    let mut secrets = (0..100).collect::<Vec<i32>>();
    let mut ret = true;
    secrets.shuffle(&mut rand::thread_rng());
    'prisoner: for i in 0..100 {
        let mut prev = i;
        'draw: for _ in 0..50 {
            if secrets[prev as usize] == i {
                continue 'prisoner;
            }
            prev = secrets[prev as usize];
        }
        ret = false;
        break 'prisoner;
    }
    ret
}
 
fn play_random() -> bool {
    let mut secrets = (0..100).collect::<Vec<i32>>();
    let mut ret = true;
    secrets.shuffle(&mut rand::thread_rng());
    'prisoner: for i in 0..100 {
        let mut opened = HashSet::new();
        let mut gen_num = || {
            let mut r = rand::thread_rng().gen_range(0, 100);
            while opened.contains(&r) {
                r = rand::thread_rng().gen_range(0, 100);
            }
            r
        };
        for _ in 0..50 {
            let draw = gen_num();
            if secrets[draw as usize] == i {
                continue 'prisoner;
            }
            opened.insert(draw);
        }
        ret = false;
        break 'prisoner;
    }
    ret
}
 
fn exec(n: i32, play: fn() -> bool) -> f64 {
    let mut succ = 0;
    for _ in 0..n {
        succ += if play() { 1 } else { 0 };
    }
    (succ as f64) / (n as f64)
}
 
fn main() {
    let n = 100_000;
    println!("# of executions: {}", n);
    println!(
        "Optimal play success rate: {}%",
        exec(n, play_optimal) * 100.0
    );
    println!(
        "Random play success rate: {}%",
        exec(n, play_random) * 100.0
    );
}

