use std::collections::HashMap;
 
fn flatten(lst: Vec<Vec<i32>>) -> Vec<i32> {
    let mut result = Vec::new();
    for sublst in lst {
        for i in sublst {
            result.push(i);
        }
    }
    result
}
 
fn magic_shuffle(deck: Vec<i32>) -> Vec<i32> {
    let half = deck.len() / 2;
    let mut result = Vec::new();
    for i in 0..half {
        result.push(deck[i]);
        result.push(deck[i + half]);
    }
    result
}
 
fn after_how_many_is_equal(shuffle_type: fn(Vec<i32>) -> Vec<i32>, start: Vec<i32>, end: Vec<i32>) -> i32 {
    let mut start = shuffle_type(start);
    let mut counter = 1;
    while start!= end {
        start = shuffle_type(start);
        counter += 1;
    }
    counter
}
 
fn main() {
    let mut deck = Vec::new();
    for i in 0..8 {
        deck.push(i);
    }
    let shuffles_needed = after_how_many_is_equal(magic_shuffle, deck, deck);
    println!("{} | {}", deck.len(), shuffles_needed);
}

