use std::env;
use std::process;
 
fn cusip_check(cusip: &str) -> bool {
    if cusip.len()!= 9 {
        return false;
    }
 
    let mut total = 0;
    for (i, c) in cusip.chars().enumerate() {
        let mut v = 0;
        if c.is_digit(10) {
            v = c.to_digit(10).unwrap() as i32;
        } else if c.is_alphabetic() {
            let p = c as i32 - 'A' as i32 + 1;
            v = p + 9;
        } else if c == '*' {
            v = 36;
        } else if c == '@' {
            v = 37;
        } else if c == '#' {
            v = 38;
        }
 
        if i % 2!= 0 {
            v *= 2;
        }
 
        total += v / 10 + v % 10;
    }
    let check = (10 - (total % 10)) % 10;
    return check == cusip.chars().last().unwrap() as i32 - '0' as i32;
}
 
fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len()!= 2 {
        println!("Usage: {} <cusip>", args[0]);
        process::exit(1);
    }
 
    let cusip = &args[1];
