// version 1.1.2
 
fn permute<T: Clone>(input: &[T]) -> Vec<Vec<T>> {
    if input.len() == 1 {
        return vec![input.to_vec()];
    }
    let mut perms = Vec::new();
    let to_insert = input[0].clone();
    for perm in permute(&input[1..]) {
        for i in 0..perm.len() + 1 {
            let mut new_perm = perm.clone();
            new_perm.insert(i, to_insert.clone());
            perms.push(new_perm);
        }
    }
    perms
}
 
fn missing_perms<T: Clone + Eq>(input: &[T], perms: &[Vec<T>]) -> Vec<Vec<T>> {
    permute(input).into_iter().filter(|p|!perms.contains(p)).collect()
}
 
fn main() {
    let input = vec!['A', 'B', 'C', 'D'];
    let strings = vec![
        "ABCD", "CABD", "ACDB", "DACB", "BCDA", "ACBD", "ADCB", "CDAB",
        "DABC", "BCAD", "CADB", "CDBA", "CBAD", "ABDC", "ADBC", "BDCA",
        "DCBA", "BACD", "BADC", "BDAC", "CBDA", "DBCA", "DCAB"
    ];
    let perms = strings.iter().map(|s| s.chars().collect()).collect::<Vec<Vec<char>>>();
    let missing = missing_perms(&input, &perms);
    if missing.len() == 1 {
        println!("The missing permutation is {}", missing[0].iter().collect::<String>());
    } else {
        println!("There are {} missing permutations, namely:\n", missing.len());
        for perm in missing {
            println!("{}", perm.iter().collect::<String>());
        }
    }
}

use std::cmp::max;
use std::mem;
use std::ptr;
use std::slice;
use std::str;
 
fn lcs(a: &[u8], b: &[u8], s: &mut Vec<u8>) -> usize {
    let n = a.len();
    let m = b.len();
    let mut c = vec![vec![0; m + 1]; n + 1];
    for i in 1..n + 1 {
        for j in 1..m + 1 {
            if a[i - 1] == b[j - 1] {
                c[i][j] = c[i - 1][j - 1] + 1;
            } else {
                c[i][j] = max(c[i - 1][j], c[i][j - 1]);
            }
        }
    }
    let mut i = n;
    let mut j = m;
    let mut k = c[n][m];
    s.resize(k, 0);
    while k > 0 {
        if a[i - 1] == b[j - 1] {
            s[k - 1] = a[i - 1];
            i -= 1;
            j -= 1;
            k -= 1;
        } else if c[i][j - 1] > c[i - 1][j] {
            j -= 1;
        } else {
            i -= 1;
        }
    }
    c.len() * c[0].len()
}
 
fn main() {
    let a = b"ABCBDAB";
    let b = b"BDCABA";
    let mut s = Vec::new();
    let t = lcs(a, b, &mut s);
    println!("{}: {}", t, str::from_utf8(&s).unwrap());
}

