        let extopenimage: extern "C" fn(in_: *const c_char) -> c_int =
            unsafe {
                std::mem::transmute(dlsym(
                    imglib,
                    CStr::from_bytes_with_nul_unchecked(b"openimage\0")
                       .as_ptr(),
                ))
            };
