use std::io;
use std::f64;
use std::collections::VecDeque;
 
fn is_prime(number: i32) -> bool {
    if number <= 1 {
        return false;
    }
    if number == 2 {
        return true;
    }
    for i in 2..(f64::sqrt(number as f64) as i32 + 1) {
        if number % i == 0 {
            return false;
        }
    }
    return true;
}
 
fn reverse_number(n: i32) -> i32 {
    let mut numberstring = n.to_string();
    numberstring.chars().rev().collect::<String>().parse::<i32>().unwrap()
}
 
fn is_emirp(n: i32) -> bool {
    is_prime(n) && is_prime(reverse_number(n)) && n!= reverse_number(n)
}
 
fn main() {
    let mut emirps: VecDeque<i32> = VecDeque::new();
    let mut i = 1;
    while emirps.len() < 20 {
        if is_emirp(i) {
            emirps.push_back(i);
        }
        i += 1;
    }
    println!("The first 20 emirps:");
    for i in emirps {
        print!("{} ", i);
    }
    println!("");
    let mut newstart = 7700;
    while newstart < 8001 {
        if is_emirp(newstart) {
            println!("{}", newstart);
        }
        newstart += 1;
    }
    while emirps.len() < 10000 {
        if is_emirp(i) {
            emirps.push_back(i);
        }
        i += 1;
    }
    println!("the 10000th emirp is {} !", emirps[9999]);
}

use std::mem;
 
// simple extensible array stuff
#[derive(Debug)]
struct XArray {
	len: usize,
	alloc: usize,
	buf: Vec<u64>,
}
 
impl XArray {
	fn new() -> XArray {
		XArray {
			len: 0,
			alloc: 0,
			buf: Vec::new(),
		}
	}
 
	fn setsize(&mut self, size: usize) {
		let mut n = self.alloc;
		if n == 0 {
			n = 1;
		}
		while n < size {
			n <<= 1;
		}
		if self.alloc < n {
			self.buf.reserve(n - self.alloc);
			self.alloc = n;
		}
	}
 
	fn push(&mut self, v: u64) {
		while self.alloc <= self.len {
			self.setsize(self.alloc * 2);
		}
		self.buf.push(v);
		self.len += 1;
	}
}
 
// sequence stuff
fn R(n: usize) -> u64 {
	while n > RS.len {
		RS_append();
	}
	RS.buf[n - 1]
}
 
fn S(n: usize) -> u64 {
	while n > SS.len {
		RS_append();
	}
	SS.buf[n - 1]
}
 
fn RS_append() {
	let n = RS.len;
	let r = R(n) + S(n);
	let mut s = S(SS.len);
 
	RS.push(r);
	while s < r {
		SS.push(s);
		s += 1;
	}
	SS.push(r + 1); // pesky 3
}
 
static mut RS: XArray = XArray::new();
static mut SS: XArray = XArray::new();
 
fn main() {
	unsafe {
		RS.push(1);
		SS.push(2);
	}
 
	println!("R(1.. 10):");
	for i in 1..11 {
		print!(" {}", R(i));
	}
	println!("");
 
	let mut seen = [false; 1001];
	for i in 1..41 {
		seen[R(i) as usize] = true;
	}
	for i in 1..961 {
		seen[S(i) as usize] = true;
	}
	for i in 1..1001 {
		if!seen[i] {
			panic!("{} not seen", i);
		}
	}
 
	println!("first 1000 ok");
}

use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::process::exit;
use std::thread;
 
fn echo_lines(mut csock: TcpStream) {
    let mut buf = [0; 256];
    loop {
        match csock.read(&mut buf) {
            Ok(0) => break,
            Ok(r) => {
                let _ = csock.write(&buf[0..r]);
            }
            Err(e) => {
                println!("read error: {}", e);
                break;
            }
        }
    }
}
 
fn take_connections_forever(listener: TcpListener) {
    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                thread::spawn(move || {
                    echo_lines(stream);
                });
            }
            Err(e) => {
                println!("connection failed: {}", e);
                break;
            }
        }
    }
}
 
fn main() {
    let listener = match TcpListener::bind("127.0.0.1:12321") {
        Ok(l) => l,
        Err(e) => {
            println!("bind error: {}", e);
            exit(1);
        }
    };
    take_connections_forever(listener);
}

use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

const PI: f64 = std::f64::consts::PI;

fn sine(frequency: f64) -> impl Fn(f64) -> f64 {
    move |t| (2.0 * PI * frequency * t).sin()
}

struct ActiveObject {
    func: Arc<Mutex<Box<dyn Fn(f64) -> f64>>>,
    integral: Arc<Mutex<f64>>,
    value: Arc<Mutex<f64>>,
    timestamp0: Arc<Mutex<Instant>>,
    timestamp: Arc<Mutex<Instant>>,
}

impl ActiveObject {
    fn new(func: impl Fn(f64) -> f64 +'static) -> Self {
        let func = Arc::new(Mutex::new(Box::new(func)));
        let integral = Arc::new(Mutex::new(0.0));
        let value = Arc::new(Mutex::new(0.0));
        let timestamp0 = Arc::new(Mutex::new(Instant::now()));
        let timestamp = Arc::new(Mutex::new(Instant::now()));

        let func_clone = func.clone();
        let integral_clone = integral.clone();
        let value_clone = value.clone();
        let timestamp0_clone = timestamp0.clone();
        let timestamp_clone = timestamp.clone();

        thread::spawn(move || {
            loop {
                thread::yield_now();
                let new_time = Instant::now();
                let new_value;

                {
                    let mut func = func_clone.lock().unwrap();
                    let mut integral = integral_clone.lock().unwrap();
                    let mut value = value_clone.lock().unwrap();
                    let mut timestamp = timestamp_clone.lock().unwrap();
                    let mut timestamp0 = timestamp0_clone.lock().unwrap();

                    new_value = func((new_time - *timestamp0).as_secs_f64());
                    *integral += (new_value + *value)
                        * (new_time - *timestamp).as_secs_f64()
                        / 2.0;
                }

                {
                    let mut timestamp = timestamp_clone.lock().unwrap();
                    let mut value = value_clone.lock().unwrap();
                    *timestamp = new_time;
                    *value = new_value;
                }
            }
        });

        Self {
            func,
            integral,
            value,
            timestamp0,
            timestamp,
        }
    }

    fn change_input(&self, func: impl Fn(f64) -> f64 +'static) {
        let mut func = self.func.lock().unwrap();
        *func = Box::new(func);
    }

    fn value(&self) -> f64 {
        *self.integral.lock().unwrap()
    }
}

fn main() {
    let ao = ActiveObject::new(sine(0.5));
    thread::sleep(Duration::from_secs(2));
    ao.change_input(|_| 0.0);
    thread::sleep(Duration::from_millis(500));
    println!("{}", ao.value());
}

