use std::cmp::{max, min};

fn intersects(a: &[i32; 2], b: &[i32; 2], p: &[f64; 2]) -> bool {
    if a[1] > b[1] {
        return intersects(b, a, p);
    }

    if p[1] == a[1] as f64 || p[1] == b[1] as f64 {
        p[1] += 0.0001;
    }

    if p[1] > b[1] as f64 || p[1] < a[1] as f64 || p[0] >= max(a[0] as f64, b[0] as f64) {
        return false;
    }

    if p[0] < min(a[0] as f64, b[0] as f64) {
        return true;
    }

    let red = (p[1] - a[1] as f64) / (p[0] - a[0] as f64);
    let blue = (b[1] as f64 - a[1] as f64) / (b[0] as f64 - a[0] as f64);
    return red >= blue;
}

fn contains(shape: &[[i32; 2]], pnt: &[f64; 2]) -> bool {
    let mut inside = false;
    let len = shape.len();
    for i in 0..len {
        if intersects(&shape[i], &shape[(i + 1) % len], pnt) {
            inside =!inside;
        }
    }
    return inside;
}

fn main() {
    let test_points = [[10, 10], [10, 16], [-20, 10], [0, 10], [20, 10], [16, 10], [20, 20]];

    for shape in &SHAPES {
        for pnt in &test_points {
            print!("{:7} ", contains(shape, &pnt));
        }
        println!();
    }
}

