use std::fmt;
use std::ops::{Add, Div, Mul, Sub};
use std::cmp::max;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Rational {
    numerator: i32,
    denominator: i32,
}

impl Rational {
    fn new(numerator: i32, denominator: i32) -> Self {
        let gcd = gcd(numerator, denominator);
        Rational {
            numerator: numerator / gcd,
            denominator: denominator / gcd,
        }
    }
}

impl fmt::Display for Rational {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        if self.denominator == 1 {
            write!(f, "{}", self.numerator)
        } else {
            write!(f, "{}/{}", self.numerator, self.denominator)
        }
    }
}

impl Add for Rational {
    type Output = Self;

    fn add(self, other: Self) -> Self {
        let numerator = self.numerator * other.denominator + other.numerator * self.denominator;
        let denominator = self.denominator * other.denominator;
        Rational::new(numerator, denominator)
    }
}

impl Sub for Rational {
    type Output = Self;

    fn sub(self, other: Self) -> Self {
        let numerator = self.numerator * other.denominator - other.numerator * self.denominator;
        let denominator = self.denominator * other.denominator;
        Rational::new(numerator, denominator)
    }
}

impl Mul for Rational {
    type Output = Self;

    fn mul(self, other: Self) -> Self {
        let numerator = self.numerator * other.numerator;
        let denominator = self.denominator * other.denominator;
        Rational::new(numerator, denominator)
    }
}

impl Div for Rational {
    type Output = Self;

    fn div(self, other: Self) -> Self {
        let numerator = self.numerator * other.denominator;
        let denominator = self.denominator * other.numerator;
        Rational::new(numerator, denominator)
    }
}

fn gcd(a: i32, b: i32) -> i32 {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

fn reduced_row_echelon_form(ary: &mut Vec<Vec<Rational>>) {
    let mut lead = 0;
    let rows = ary.len();
    let cols = ary[0].len();
    let mut i = 0;
    let mut v = Rational::new(0, 0);
    loop {
        if cols <= lead {
            break;
        }
        i = lead;
        while ary[i][lead] == Rational::new(0, 1) {
            i += 1;
            if rows == i {
                i = lead;
                lead += 1;
                if cols == lead {
                    break;
                }
            }
        }
        ary.swap(i, lead);
        v = ary[lead][lead];
        for j in 0..cols {
            ary[lead][j] = ary[lead][j] / v;
        }
        for r in 0..rows {
            if r == lead {
                continue;
            }
            v = ary[r][lead];
            for j in 0..cols {
                ary[r][j] = ary[r][j] - v * ary[lead][j];
            }
        }
        lead += 1;
    }
}

fn convert_to<T>(ary: &Vec<Vec<Rational>>, type_: T) -> Vec<Vec<T>>
where
    T: From<Rational>,
{
    ary.iter()
       .map(|row| row.iter().map(|elem| elem.clone().into()).collect())
       .collect()
}

fn print_matrix(m: &Vec<Vec<Rational>>) {
    let mut max = vec![0; m[0].len()];
    for row in m {
        for (i, elem) in row.iter().enumerate() {
            max[i] = max[i].max(elem.to_string().len());
        }
    }
    for row in m {
        for (i, elem) in row.iter().enumerate() {
            print!("{:width$} ", elem, width = max[i]);
        }
        println!();
    }
}

fn main() {
    let mut mtx = vec![
        vec![Rational::new(1, 1), Rational::new(2, 1), Rational::new(-1, 1), Rational::new(-4, 1)],
        vec![Rational::new(2, 1), Rational::new(3, 1), Rational::new(-1, 1), Rational::new(-11, 1)],
        vec![Rational::new(-2, 1), Rational::new(0, 1), Rational::new(-3, 1), Rational::new(22, 1)],
    ];
    reduced_row_echelon_form(&mut mtx);
    print_matrix(&mtx);
    println!();

    let mut mtx = vec![
        vec![Rational::new(1, 1), Rational::new(2, 1), Rational::new(3, 1), Rational::new(7, 1)],
        vec![Rational::new(-4, 1), Rational::new(7, 1), Rational::new(-2, 1), Rational::new(7, 1)],
        vec![Rational::new(3, 1), Rational::new(3, 1), Rational::new(0, 1), Rational::new(7, 1)],
    ];
    reduced_row_echelon_form(&mut mtx);
    print_matrix(&mtx);
    print_matrix(&convert_to(&mtx, f64::from));
}

