use std::fmt;
use std::time::SystemTime;
use rand::Rng;
 
const NUMBER: [&str; 3] = ["1", "2", "3"];
const COLOR: [&str; 3] = ["red", "green", "purple"];
const SHADE: [&str; 3] = ["solid", "open", "striped"];
const SHAPE: [&str; 3] = ["oval", "squiggle", "diamond"];
 
#[derive(Debug, Copy, Clone)]
struct Card(u8);
 
impl fmt::Display for Card {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let Card(c) = *self;
        write!(f, "{} {} {} {}",
            NUMBER[c as usize / 27],
            COLOR[c as usize / 9 % 3],
            SHADE[c as usize / 3 % 3],
            SHAPE[c as usize % 3])
    }
}
 
fn main() {
    game("Basic", 9, 4);
    game("Advanced", 12, 6);
}
 
fn game(level: &str, cards: usize, sets: usize) {
    // create deck
    let mut d = [Card(0); 81];
    for i in 0..81 {
        d[i] = Card(i as u8);
    }
    let mut found = Vec::new();
    while found.len()!= sets {
        found.clear();
        // deal
        let mut rng = rand::thread_rng();
        d.shuffle(&mut rng);
        //  consider all triplets
        for i in 2..cards {
            let c1 = d[i];
            for j in 1..i {
                let c2 = d[j];
                for k in 0..j {
                    let c3 = d[k];
                    let mut f = 1;
                    let mut sum = 0;
                    while f < 81 {
                        sum += (c1.0 / f % 3 + c2.0 / f % 3 + c3.0 / f % 3) % 3;
                        f *= 3;
                    }
                    if sum == 0 {
                        // it's a set
                        found.push([c1, c2, c3]);
                    }
                }
            }
        }
    }
    // found the right number
    println!("{} game.  {} cards, {} sets.", level, cards, sets);
    println!("Cards:");
    for c in &d[..cards] {
        println!("  {}", c);
    }
    println!("Sets:");
    for s in &found {
        println!("  {}", s[0]);
        println!("  {}", s[1]);
        println!("  {}", s[2]);
    }
}

