fn fib(n: i32) -> i32 {
    if n < 2 {
        n
    } else {
        let mut prev = 0;
        let mut fib = 1;
        let mut i = 0;
        loop {
            let tmp = fib;
            fib = fib + prev;
            prev = tmp;
            i = i + 1;
            if i % 2 == 0 {
                continue;
            }
            if i >= n-1 {
                break;
            }
        }
        fib
    }
}
 
