use std::io;
use std::io::prelude::*;
use std::str::FromStr;

struct MyTransform {
    shift: i32,
}

impl MyTransform {
    fn new(shift: i32) -> MyTransform {
        MyTransform { shift: shift }
    }
}

impl FnMut<char> for MyTransform {
    extern "rust-call" fn call_mut(&mut self, c: char) -> char {
        if c.is_whitespace() {
            return'';
        } else {
            let letters = "abcdefghijklmnopqrstuvwxyz";
            let found = letters.find(c.to_lowercase().next().unwrap()).unwrap();
            let shiftedpos = (found as i32 + self.shift) % 26;
            let shifted = letters.chars().nth(shiftedpos as usize).unwrap();
            return shifted;
        }
    }
}

fn main() {
