    let myshift: i32 = FromStr::from_str(&input).unwrap();
    println!("Before encryption:\n{}", input);
    input.chars().for_each(MyTransform::new(myshift));
    println!("encrypted:\n{}", input);
    input.chars().for_each(MyTransform::new(-myshift));
    println!("Decrypted again:\n{}", input);
}

use std::f64::consts::PI;
