use std::iter::Sum;

fn mean_angle(angles: &[f64]) -> f64 {
    let x = angles.iter().map(|a| a.to_radians().cos()).sum::<f64>() / angles.len() as f64;
    let y = angles.iter().map(|a| a.to_radians().sin()).sum::<f64>() / angles.len() as f64;
    atan2(y, x).to_degrees()
}

