use std::io;
use std::io::Write;
 
fn nb(cells: i32, total_block_size: i32, blocks: &mut [i32], block_count: i32, output: &mut [u8], offset: i32, count: &mut i32) {
    if block_count == 0 {
        println!("{:2}  {}", count, String::from_utf8_lossy(output));
        *count += 1;
        return;
    }
    let block_size = blocks[0];
    let max_pos = cells - (total_block_size + block_count - 1);
    total_block_size -= block_size;
    cells -= block_size + 1;
    blocks.remove(0);
    block_count -= 1;
    for i in 0..max_pos + 1 {
        for j in 0..max_pos + block_size {
            output[offset as usize + j as usize] = b'.';
        }
        for j in 0..block_size {
            output[offset as usize + i as usize + j as usize] = b'#';
        }
        nb(cells, total_block_size, blocks, block_count, output, offset + block_size + i + 1, count);
    }
}
 
fn nonoblock(cells: i32, blocks: &mut [i32], block_count: i32) {
    print!("{} cells and blocks [", cells);
    for i in 0..block_count {
        if i == 0 {
            print!("{}", blocks[i as usize]);
        } else {
            print!(", {}", blocks[i as usize]);
        }
    }
    println!("]:");
    let mut total_block_size = 0;
    for i in 0..block_count {
        total_block_size += blocks[i as usize];
    }
    if cells < total_block_size + block_count - 1 {
        println!("no solution");
        return;
    }
    let mut output = vec![b'.'; cells as usize + 1];
    output[cells as usize] = b'\0';
    let mut count = 0;
    nb(cells, total_block_size, blocks, block_count, &mut output, 0, &mut count);
}
 
fn main() {
    let mut blocks1 = [2, 1];
    nonoblock(5, &mut blocks1, 2);
    println!("\n");
 
    nonoblock(5, &mut [], 0);
    println!("\n");
 
    let mut blocks2 = [8];
    nonoblock(10, &mut blocks2, 1);
    println!("\n");
 
    let mut blocks3 = [2, 3, 2, 3];
    nonoblock(15, &mut blocks3, 4);
    println!("\n");
 
    let mut blocks4 = [2, 3];
    nonoblock(5, &mut blocks4, 2);
}

use std::cmp::min;
use std::collections::HashSet;
use std::time::Instant;
 
fn count_triplets(max_perimeter: u64) -> (u64, u64) {
    let mut total_count = 0;
    let mut primitive_count = 0;
    let max_m = (max_perimeter / 2).sqrt() as u64 + 1;
    for m in 2..max_m {
        for n in (1 + m % 2)..m {
            if gcd(m, n)!= 1 {
                continue;
            }
 
            // The formulas below will generate primitive triples if:
            //   0 < n < m
            //   m and n are relatively prime (gcd == 1)
            //   m + n is odd
 
            let a = m * m - n * n;
            let b = 2 * m * n;
            let c = m * m + n * n;
            let perimeter = a + b + c;
            if perimeter <= max_perimeter {
                primitive_count += 1;
                total_count += max_perimeter / perimeter;
            }
        }
    }
 
    (total_count, primitive_count)
}
 
fn gcd(mut a: u64, mut b: u64) -> u64 {
    while b!= 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a
}
 
fn main() {
    let inputs = vec![
        100, 1000, 10_000, 100_000, 1_000_000, 10_000_000, 100_000_000, 1_000_000_000,
        10_000_000_000,
    ];
    for max_perimeter in inputs {
        let start = Instant::now();
        let (total, primitive) = count_triplets(max_perimeter);
        let elapsed = start.elapsed();
        println!(
            "\nMax Perimeter: {}, Total: {}, Primitive: {}, Elapsed: {:?}",
            max_perimeter, total, primitive, elapsed
        );
    }
}

