fn factorial(n: u64) -> u64 {
    (1..n + 1).fold(1, |acc, x| acc * x)
}
 
fn is_wprime(n: u64) -> bool {
    n == 2 || (n > 1 && n % 2!= 0 && (factorial(n - 1) + 1) % n == 0)
}
 
