fn tm(d: &str, s: char, e: char, i: usize, b: char, t: &str, r: &[(char, char, char, char, char, char)]) {
	println!("{}", d);
	if i < 0 || i >= t.len() {
		return;
	}
	let re = Regex::new(b.to_string().as_str()).unwrap();
	write(1, s, i, t.to_string());
	let mut p = HashMap::new();
	for e in r {
		p.insert(format!("{}.{}", e.0, e.1), (e.2, e.3, e.4, e.5));
	}
	let mut n = 1;
	let mut s = s;
	let mut i = i;
	let mut t = t.to_string();
	loop {
		let (w, m, n, s2) = p.get(&format!("{}.{}", s, t.chars().nth(i).unwrap())).unwrap();
		t.replace_range(i..i+1, w);
		s = s2.clone();
		i = match m {
			"L" => i - 1,
			"R" => i + 1,
			"S" => i,
			_ => panic!("Invalid move"),
		};
		if i == -1 {
			i = 0;
			t.insert(0, b);
		} else if i == t.len() {
			t.push(b);
		}
		write(n, s, i, t.clone());
		if s == e {
			break;
		}
		n += 1;
	}
	println!();
	fn write(n: usize, s: char, i: usize, t: String) {
		let mut t = t;
		t.replace_range(i..i+1, format!("<u>{}</u>", t.chars().nth(i).unwrap()).as_str());
		println!("{:>3}: {} [{}]", n, s, re.replace_all(t.as_str(), " "));
	}
}
 
