    for i in 2..500 {
        if is_prime(i) && is_prime(digit_sum(i)) {
            additive_primes += 1;
            print!("{} ", i);
        }
    }
    println!("\nFound {} additive primes less than 500", additive_primes);
}

use std::io;

fn divisor_count_and_sum(n: u32) -> (u32, u32) {
    let mut divisor_count = 0;
    let mut divisor_sum = 0;
    for i in 1..=n {
        let j = n / i;
        if j < i {
            break;
        }
        if i * j!= n {
            continue;
        }
        divisor_sum += i;
        divisor_count += 1;
        if i!= j {
            divisor_sum += j;
            divisor_count += 1;
        }
    }
    (divisor_count, divisor_sum)
}

fn main() {
    let mut arithmetic_count = 0;
    let mut composite_count = 0;

    for n in 1.. {
        let (divisor_count, divisor_sum) = divisor_count_and_sum(n);
        let mean = divisor_sum / divisor_count;
        if mean * divisor_count!= divisor_sum {
            continue;
        }
        arithmetic_count += 1;
        if divisor_count > 2 {
            composite_count += 1;
        }
        if arithmetic_count <= 100 {
            print!("{:3} ", n);
            if arithmetic_count % 10 == 0 {
                println!();
            }
        }
        if arithmetic_count == 1000
            || arithmetic_count == 10000
            || arithmetic_count == 100000
            || arithmetic_count == 1000000
        {
            println!(
                "\n{}th arithmetic number is {}\n",
                arithmetic_count, n
            );
            println!(
                "Number of composite arithmetic numbers <= {}: {}\n",
                n, composite_count
            );
        }
    }
}

// version 1.0.6
 
struct BinaryTree<T> {
    value: T,
    left: Option<Box<BinaryTree<T>>>,
    right: Option<Box<BinaryTree<T>>>
}
 
impl<T> BinaryTree<T> {
    fn new(value: T) -> BinaryTree<T> {
        BinaryTree {
            value: value,
            left: None,
            right: None
        }
    }
 
    fn map<U, F>(&self, f: F) -> BinaryTree<U>
        where F: Fn(&T) -> U
    {
        BinaryTree {
            value: f(&self.value),
            left: self.left.as_ref().map(|x| Box::new(x.map(f))),
            right: self.right.as_ref().map(|x| Box::new(x.map(f)))
        }
    }
 
    fn show_top_three(&self) -> String {
        format!("({}, {}, {})",
                self.left.as_ref().map(|x| x.value).unwrap_or(&""),
                self.value,
                self.right.as_ref().map(|x| x.value).unwrap_or(&""))
    }
}
 
fn main() {
    let b = BinaryTree::new(6);
    let b = {
        let mut b = b;
        b.left = Some(Box::new(BinaryTree::new(5)));
        b.right = Some(Box::new(BinaryTree::new(7)));
        b
    };
    println!("{}", b.show_top_three());
    let b2 = b.map(|x| x * 10.0);
    println!("{}", b2.show_top_three());
}

use std::collections::VecDeque;
 
const N: usize = 8;
 
const MOVES: [(i32, i32); 8] = [ (1,-2), (2,-1), (2,1), (1,2), (-1,2), (-2,1), (-2,-1), (-1,-2) ];
 
struct ListMoves {
	x: i32,
	y: i32,
}
 
fn main() {
	let mut board = [[0; N]; N];
	let mut list = VecDeque::new();
	list.push_back( ListMoves { x: 0, y: 0 } );
	let mut x = 0;
	let mut y = 0;
	loop {
		if move_possible( &board, x, y ) {
			let move_ = board[x as usize][y as usize];
			board[x as usize][y as usize] += 1;
			x += MOVES[move_ as usize].0;
			y += MOVES[move_ as usize].1;
			list.push_back( ListMoves { x: x, y: y } );
		} else {
			if board[x as usize][y as usize] >= 8 {
				board[x as usize][y as usize] = 0;
				list.pop_back();
				if list.len() == 0 {
					println!("No solution found.");
					return;
				}
				x = list[list.len()-1].x;
				y = list[list.len()-1].y;
			}
			board[x as usize][y as usize] += 1;
		}
		if list.len() == N*N {
			break;
		}
	}
	let mut last_x = list[0].x;
	let mut last_y = list[0].y;
	let letters = "ABCDEFGH";
	for i in 1..list.len() {
		println!("{0:>2}:  {1}{2} - {3}{4}", i, letters.chars().nth(last_x as usize).unwrap(), last_y+1, letters.chars().nth(list[i].x as usize).unwrap(), list[i].y+1);
		last_x = list[i].x;
		last_y = list[i].y;
	}
}
 
fn move_possible( board: &[[i32; N]; N], cur_x: i32, cur_y: i32 ) -> bool {
	if board[cur_x as usize][cur_y as usize] >= 8 {
		return false;
	}
	let new_x = cur_x + MOVES[board[cur_x as usize][cur_y as usize] as usize].0;
	let new_y = cur_y + MOVES[board[cur_x as usize][cur_y as usize] as usize].1;
	if new_x >= 0 && new_x < N as i32 && new_y >= 0 && new_y < N as i32 && board[new_x as usize][new_y as usize] == 0 {
		return true;
	}
	return false;
}

