use std::cmp::Ordering;
use std::fmt;
 
#[derive(Debug)]
struct Pair {
    i: i32,
    s: String,
}
 
impl Pair {
    fn new(i: i32, s: String) -> Pair {
        Pair { i: i, s: s }
    }
}
 
impl Ord for Pair {
    fn cmp(&self, other: &Pair) -> Ordering {
        self.i.cmp(&other.i)
    }
}
 
impl PartialOrd for Pair {
    fn partial_cmp(&self, other: &Pair) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
 
impl PartialEq for Pair {
    fn eq(&self, other: &Pair) -> bool {
        self.i == other.i
    }
}
 
impl Eq for Pair {}
 
impl fmt::Display for Pair {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "({}, {})", self.i, self.s)
    }
}
 
fn g_fizz_buzz(c: i32, v: &mut Vec<Pair>) {
    let mut output: bool;
    for x in 1..c + 1 {
        output = false;
        for i in v.iter() {
            if x % i.i == 0 {
                print!("{}", i.s);
                output = true;
            }
        }
        if!output {
            print!("{}", x);
        }
        println!("");
    }
}
 
fn main() {
    let mut v: Vec<Pair> = Vec::new();
    v.push(Pair::new(7, "Baxx".to_string()));
    v.push(Pair::new(3, "Fizz".to_string()));
    v.push(Pair::new(5, "Buzz".to_string()));
    v.sort();
    g_fizz_buzz(20, &mut v);
}

fn sedol_checksum(sedol: &str) -> i32 {
    let len = sedol.len();
    let mut sum = 0;

    if len == 7 {
        return sedol.chars().nth(6).unwrap() as i32 - 48;
    }

    if len > 7 || len < 6 || sedol.contains(|c: char| c.is_ascii_uppercase()) {
        return -1;
    }

    for (i, c) in sedol.chars().enumerate() {
        if c.is_ascii_digit() {
            sum += (c as i32 - 48) * sedol_weights[i];
        } else if c.is_ascii_uppercase() {
            sum += (c as i32 - 55) * sedol_weights[i];
        } else {
            return -1;
        }
    }

    return (10 - (sum % 10)) % 10;
}

use std::ops::Rem;

pub trait EvenOrOdd {
    fn is_even_bitwise(&self) -> bool;
    fn is_odd_bitwise(&self) -> bool;
    fn is_even_remainder(&self) -> bool;
    fn is_odd_remainder(&self) -> bool;
    fn is_even_modulo(&self) -> bool;
    fn is_odd_modulo(&self) -> bool;
}

impl<T> EvenOrOdd for T
where
    T: Rem<Output = T> + PartialEq + Copy,
{
    fn is_even_bitwise(&self) -> bool {
        self & 1 == 0
    }

    fn is_odd_bitwise(&self) -> bool {
        self & 1!= 0
    }

    fn is_even_remainder(&self) -> bool {
        self % 2 == 0
    }

    fn is_odd_remainder(&self) -> bool {
        self % 2!= 0
    }

    fn is_even_modulo(&self) -> bool {
        self % 2 == 0
    }

    fn is_odd_modulo(&self) -> bool {
        self % 2!= 0
    }
}

fn main() {
    let num = 26; //Set this to any integer.
    if num.is_even_bitwise() {
        println!("Even");
    } else {
        println!("Odd");
    }
    //Prints "Even".
    if num.is_odd_bitwise() {
        println!("Odd");
    } else {
        println!("Even");
    }
    //Prints "Even".
}

fn luhn_valid(str: &str) -> bool {
    str.chars()
       .rev()
       .filter_map(|c| c.to_digit(10))
       .enumerate()
       .map(|(i, n)| if i % 2 == 0 { n } else { (n * 2) % 9 })
       .sum::<u32>()
        % 10
        == 0
}
 
