use std::mem;
 
type Byte = u8;
 
static mut GRID: *mut Byte = 0 as *mut Byte;
 
static mut W: i32 = 0;
static mut H: i32 = 0;
static mut LEN: i32 = 0;
static mut CNT: u64 = 0;
 
static NEXT: [i32; 4] = [-1, -W - 1, 1, W + 1];
static DIR: [[i32; 2]; 4] = [[0, -1], [-1, 0], [0, 1], [1, 0]];
 
unsafe fn walk(y: i32, x: i32) {
	let mut i: i32;
	let mut t: i32;
 
	if y == 0 || y == H || x == 0 || x == W {
		CNT += 2;
		return;
	}
 
	t = y * (W + 1) + x;
	(*GRID.offset(t as isize)) += 1;
	(*GRID.offset((LEN - t) as isize)) += 1;
 
	i = 0;
	while i < 4 {
		if *GRID.offset((t + NEXT[i as usize]) as isize) == 0 {
			walk(y + DIR[i as usize][0], x + DIR[i as usize][1]);
		}
		i += 1;
	}
 
	(*GRID.offset(t as isize)) -= 1;
	(*GRID.offset((LEN - t) as isize)) -= 1;
}
 
unsafe fn solve(hh: i32, ww: i32, recur: i32) -> u64 {
	let mut t: i32;
	let mut cy: i32;
	let mut cx: i32;
	let mut x: i32;
 
	H = hh;
	W = ww;
 
	if H & 1!= 0 {
		t = W;
		W = H;
		H = t;
	}
	if H & 1!= 0 {
		return 0;
	}
	if W == 1 {
		return H as u64;
	}
	if W == 2 {
		return H as u64;
	}
	if H == 2 {
		return W as u64;
	}
 
	cy = H / 2;
	cx = W / 2;
 
	LEN = (H + 1) * (W + 1);
	GRID = mem::transmute(realloc(mem::transmute(GRID), (LEN + 1) as usize) as *mut u8);
	memset(GRID, 0, (LEN + 1) as usize);
	LEN -= 1;
 
	if recur!= 0 {
		CNT = 0;
	}
	x = cx + 1;
	while x < W {
		t = cy * (W + 1) + x;
		*GRID.offset(t as isize) = 1;
		*GRID.offset((LEN - t) as isize) = 1;
		walk(cy - 1, x);
		x += 1;
	}
	CNT += 1;
 
	if H == W {
		CNT *= 2;
	} else if W & 1 == 0 && recur!= 0 {
		solve(W, H, 0);
	}
 
	return CNT;
}
 
fn main() {
	let mut y: i32;
	let mut x: i32;
	y = 1;
	while y <= 10 {
		x = 1;
		while x <= y {
			if x & 1 == 0 || y & 1 == 0 {
				println!("{} x {}: {}", y, x, unsafe { solve(y, x, 1) });
			}
			x += 1;
		}
		y += 1;
	}
}

use std::cmp;
use std::ops::Sub;
use num::bigint::BigInt;
 
fn main() {
 
	let int_min = |a: i32, b: i32| -> i32 {
		if a < b {
			a
		} else {
			b
		}
	};
 
	let mut cache = vec![vec![BigInt::from(1)]];
 
	let cumu = |n: i32| -> Vec<BigInt> {
		for y in cache.len()..=n as usize {
			let mut row = vec![BigInt::from(0)];
			for x in 1..=y {
				let cache_value = cache[y - x][int_min(x, y - x) as usize].clone();
				row.push(row[row.len() - 1].clone() + cache_value);
			}
			cache.push(row);
		}
		cache[n as usize].clone()
	};
 
	let row = |n: i32| {
		let e = cumu(n);
		for i in 0..n {
			print!(" {}", (e[i + 1].clone() - e[i].clone()).to_string());
		}
		println!();
	};
 
	println!("rows:");
	for x in 1..11 {
		row(x);
	}
	println!();
 
	println!("sums:");
	for num in [23, 123, 1234, 12345].iter() {
		let r = cumu(*num);
		println!("{} {}", num, r[r.len() - 1].to_string());
	}
}

// version 1.1.3
 
typealias Vector = Vec<i32>;
typealias Matrix = Vec<Vector>;
 
fn zigzagMatrix(n: usize) -> Matrix {
    let mut result = vec![vec![0; n]; n];
    let mut down = false;
    let mut count = 0;
    for col in 0..n {
        if down {
            for row in 0..=col {
                result[row][col - row] = count;
                count += 1;
            }
        } else {
            for row in (0..=col).rev() {
                result[row][col - row] = count;
                count += 1;
            }
        }
        down =!down;
    }
    for row in 1..n {
        if down {
            for col in (row..n).rev() {
                result[row + n - 1 - col][col] = count;
                count += 1;
            }
        } else {
            for col in row..n {
                result[row + n - 1 - col][col] = count;
                count += 1;
            }
        }
        down =!down;
    }
    result
}
 
fn printMatrix(m: &Matrix) {
    for i in 0..m.len() {
        for j in 0..m.len() {
            print!("{:2} ", m[i][j]);
        }
        println!();
    }
    println!();
}
 
fn main() {
    printMatrix(&zigzagMatrix(5));
    printMatrix(&zigzagMatrix(10));
}

