use std::f64::consts::PI;
 
const TWO_PI: f64 = 2.0 * PI;
 
fn normalize2deg(a: f64) -> f64 {
    let mut a = a;
    while a < 0.0 { a += 360.0; }
    while a >= 360.0 { a -= 360.0; }
    a
}
fn normalize2grad(a: f64) -> f64 {
    let mut a = a;
    while a < 0.0 { a += 400.0; }
    while a >= 400.0 { a -= 400.0; }
