use std::ops::{Index, IndexMut};
 
type Vector = Vec<f64>;
type Matrix = Vec<Vector>;
 
impl Matrix {
    fn mul(&self, other: &Matrix) -> Matrix {
        let rows1 = self.len();
        let cols1 = self[0].len();
        let rows2 = other.len();
        let cols2 = other[0].len();
        if cols1!= rows2 {
            panic!("Matrices cannot be multiplied.");
        }
        let mut result = vec![vec![0.0; cols2]; rows1];
        for i in 0..rows1 {
            for j in 0..cols2 {
                for k in 0..rows2 {
                    result[i][j] += self[i][k] * other[k][j];
                }
            }
        }
        result
    }
 
    fn identity(n: usize) -> Matrix {
        if n < 1 {
            panic!("Size of identity matrix can't be less than 1");
        }
        let mut ident = vec![vec![0.0; n]; n];
        for i in 0..n {
            ident[i][i] = 1.0;
        }
        ident
    }
 
    fn pow(&self, n: usize) -> Matrix {
        let le = self.len();
        if le!= self[0].len() {
            panic!("Not a square matrix");
        }
        match n {
            0 => Self::identity(le),
            1 => self.clone(),
            _ => {
                let mut pow = Self::identity(le);
                let mut base = self.clone();
                let mut e = n;
                while e > 0 {
                    if (e & 1) == 1 {
                        pow = pow.mul(&base);
                    }
                    e >>= 1;
                    base = base.mul(&base);
                }
                pow
            }
        }
    }
}
 
fn main() {
    let m = Matrix::from(vec![vec![3.0, 2.0], vec![2.0, 1.0]]);
    for i in 0..=10 {
        println!("** Power of {} **", i);
        println!("{:?}", m.pow(i));
        println!();
    }
}

