fn from_roman(roman: &str) -> u32 {
    let mut n = 0;
    let mut r = roman.to_uppercase();
    while!r.is_empty() {
        let (v, len) = match r.as_str() {
            "M" => (1000, 1),
            "CM" => (900, 2),
            "D" => (500, 1),
            "CD" => (400, 2),
            "C" => (100, 1),
            "XC" => (90, 2),
            "L" => (50, 1),
            "XL" => (40, 2),
            "X" => (10, 1),
            "IX" => (9, 2),
            "V" => (5, 1),
            "IV" => (4, 2),
            "I" => (1, 1),
            _ => panic!("invalid roman numerals: {}", roman),
        };
        n += v;
        r = &r[len..];
    }
    n
}
 
fn main() {
    let romans = ["MCMXC", "MMVIII", "MDCLXVI"];
    for r in romans.iter() {
        println!("{} => {}", r, from_roman(r));
    }
}

use std::mem;
use std::str::FromStr;
 
#[derive(Debug)]
struct List {
	is_list: bool,
	ival: i32,
	lst: Vec<Box<List>>,
}
 
impl List {
	fn new() -> List {
		List {
			is_list: true,
			ival: 0,
			lst: Vec::new(),
		}
	}
 
	fn append(&mut self, child: Box<List>) {
		self.lst.push(child);
	}
 
	fn from_string(s: &str) -> List {
		let mut parent = List::new();
		let mut ret = Box::new(List::new());
		let mut s = s.chars();
		while let Some(c) = s.next() {
			match c {
				']' => return parent,
				'[' => {
					ret = Box::new(List::new());
					ret.is_list = true;
					ret.ival = 0;
					parent.append(ret);
					List::from_string(&s.as_str());
				},
				_ if c.is_digit(10) => {
					ret = Box::new(List::new());
					ret.is_list = false;
					ret.ival = i32::from_str(&c.to_string()).unwrap();
					parent.append(ret);
				},
				_ => (),
			}
		}
		parent
	}
 
	fn show_list(&self) {
		if!self.is_list {
			print!("{}", self.ival);
			return;
		}
		print!("[");
		for (i, l) in self.lst.iter().enumerate() {
			l.show_list();
			if i < self.lst.len() - 1 {
				print!(", ");
			}
		}
		print!("]");
	}
 
	fn flatten(&self) -> List {
		let mut to = List::new();
		if!self.is_list {
			let mut t = List::new();
			mem::swap(&mut t, self);
			to.append(Box::new(t));
		} else {
			for l in &self.lst {
				to.append(Box::new(l.flatten()));
			}
		}
		to
	}
}
 
fn main() {
	let l = List::from_string("[1], 2, [[3,4], 5], [[[]]], [[[6]]], 7, 8, []");
	println!("Nested: ");
	l.show_list();
	println!("\n");
	let flat = l.flatten();
	println!("Flattened: ");
	flat.show_list();
}

