fn main() {
    let f = |x: f64| x * x * x - 3.0 * x * x + 2.0 * x;
    let step = 0.001;
    let start = -1.0;
    let stop = 3.0;
    let mut sign = f(start) > 0.0;
    let mut x = start;
    while x <= stop {
        let value = f(x);
        if value == 0.0 {
            println!("Root found at {}", x);
        } else if (value > 0.0)!= sign {
            println!("Root found near {}", x);
        }
        sign = value > 0.0;
        x += step;
    }
}

// populationCount :: Int -> Int
fn population_count(n: i32) -> i32 {
    // The number of non-zero bits in the binary
    // representation of the integer n.
    sum(unfoldr(
        |x| if 0 < x {
            Some((x % 2, x / 2))
        } else {
            None
        },
        n
    ))
}

