        enum_from_to(0, 59)
    );
    println!("Population counts of the first 30 powers of three:");
    println!("    [{}]", enum_from_to(0, 29)
       .map(|x| population_count(raise(3, x)))
       .collect::<Vec<i32>>()
       .join(","));
    println!("\nFirst thirty 'evil' numbers:");
    println!("    [{}]", evens.join(","));
    println!("\nFirst thirty 'odious' numbers:");
    println!("    [{}]", odds.join(","));
}

// ----------------- GENERIC FUNCTIONS -----------------

// Just :: a -> Maybe a
fn just<T>(x: T) -> Option<T> {
    Some(x)
}

// Nothing :: Maybe a
fn nothing<T>() -> Option<T> {
    None
}

// Tuple (,) :: a -> b -> (a, b)
fn tuple<T, U>(a: T, b: U) -> (T, U) {
    (a, b)
}

// compose (<<<) :: (b -> c) -> (a -> b) -> a -> c
fn compose<A, B, C, F, G>(f: F, g: G) -> impl Fn(A) -> C
where
    F: Fn(B) -> C,
    G: Fn(A) -> B,
{
    move |x| f(g(x))
}

// enumFromTo :: Int -> Int -> [Int]
fn enum_from_to(m: i32, n: i32) -> Vec<i32> {
    if!m.is_nan() {
        (m..=n).collect()
    } else {
        enum_from_to_(m, n)
    }
}

// even :: Int -> Bool
fn even(n: i32) -> bool {
    // True if n is an even number.
    0 == n % 2
}

// partition :: (a -> Bool) -> [a] -> ([a], [a])
fn partition<T, F>(p: F, xs: Vec<T>) -> (Vec<T>, Vec<T>)
where
    F: Fn(T) -> bool,
{
    xs.into_iter().partition(p)
}

// raise :: Num -> Int -> Num
fn raise(x: i32, n: i32) -> i32 {
    // X to the power of n.
    x.pow(n as u32)
}

// sum :: [Num] -> Num
fn sum(xs: Vec<i32>) -> i32 {
    // The numeric sum of all values in xs.
    xs.iter().sum()
}

// unfoldr :: (b -> Maybe (a, b)) -> b -> [a]
fn unfoldr<A, B, F>(f: F, v: B) -> Vec<A>
where
    F: Fn(B) -> Option<(A, B)>,
{
    let mut xs = vec![];
    let mut xr = (v, v);
    while let Some(mb) = f(xr.1) {
        xr = mb;
        xs.push(xr.0);
    }
    xs
}

