use std::fs;
use std::path::Path;
 
fn walk_directory(dir_path: &str, pattern: &str) -> Vec<String> {
    let d = Path::new(dir_path);
    assert!(d.exists() && d.is_dir());
    let mut files = Vec::new();
    for entry in fs::read_dir(d).unwrap() {
        let entry = entry.unwrap();
        let path = entry.path();
        if path.is_file() {
            let file_name = path.file_name().unwrap().to_str().unwrap();
            if file_name.matches(pattern).count() > 0 {
                files.push(file_name.to_string());
            }
        }
    }
    files
}
 
fn main() {
    let r = "a.*\\.h";  // get all C header files beginning with 'a'
    let files = walk_directory("/usr/include", r);
    for file in files {
        println!("{}", file);
    }
}

use ndarray::{Array2, ArrayView2};
use ndarray_image::{ImageDecoder, ImageEncoder};
use std::error::Error;
use std::fs::File;
use std::io::BufWriter;
 
fn init_grid(x_dim: usize, y_dim: usize) -> Array2<i32> {
    let mut grid = Array2::zeros((x_dim, y_dim));
    grid[[x_dim / 2, y_dim / 2]] = 64000;
    grid
}
 
fn print_grid(grid: &Array2<i32>) -> Result<(), Box<dyn Error>> {
    // for output to the terminal uncomment next line
    // only makes sense for small grid < 32x32;
    // println!("{:?}", grid);
 
    // output result to an image
    let file = File::create("grid.jpg")?;
    let ref mut w = BufWriter::new(file);
    let mut encoder = ImageEncoder::new(w, 800, 600)?;
    encoder.encode(&grid.view())?;
    Ok(())
}
 
fn iterate_grid(grid: &mut Array2<i32>, x_dim: usize, y_dim: usize) -> bool {
    let mut changed = false;
 
    for i in 0..x_dim {
        for j in 0..y_dim {
            if grid[[i, j]] >= 4 {
                grid[[i, j]] -= 4;
                changed = true;
                if i > 0 {
                    grid[[i - 1, j]] += 1;
                }
                if i < x_dim - 1 {
                    grid[[i + 1, j]] += 1;
                }
                if j > 0 {
                    grid[[i, j - 1]] += 1;
                }
                if j < y_dim - 1 {
                    grid[[i, j + 1]] += 1;
                }
            }
        }
    }
 
    changed
}
 
fn main() -> Result<(), Box<dyn Error>> {
    let x_dim = 200;
    let y_dim = 200;
 
    let mut grid = init_grid(x_dim, y_dim);
    let mut changed = true;
 
    iterate_grid(&mut grid, x_dim, y_dim);
 
    while changed == true {
        changed = iterate_grid(&mut grid, x_dim, y_dim);
    }
    print_grid(&grid)?;
 
    Ok(())
}

use rand::Rng;

fn main() {
    let mut switch_wins = 0;
    let mut stay_wins = 0;

    for _ in 0..1000000 {
        let mut doors = [0, 0, 0];
        let winner = rand::thread_rng().gen_range(0, 3);
        doors[winner] = 1;

        let choice = rand::thread_rng().gen_range(0, 3);
        let mut shown = rand::thread_rng().gen_range(0, 3);
        while doors[shown] == 1 || shown == choice {
            shown = rand::thread_rng().gen_range(0, 3);
        }

        stay_wins += doors[choice];
        switch_wins += doors[3 - choice - shown];
    }

    println!("Staying wins {} times.", stay_wins);
    println!("Switching wins {} times.", switch_wins);
}

