use std::io;
 
fn next_in_cycle(c: &Vec<i32>, index: usize) -> i32 {
    c[index % c.len()]
}
 
fn kolakoski(c: &Vec<i32>, slen: usize) -> Vec<i32> {
    let mut s = vec![0; slen];
    let mut i = 0;
    let mut k = 0;
    while i < slen {
        s[i] = next_in_cycle(c, k);
        if s[k] > 1 {
            for j in 1..s[k] {
                i += 1;
                if i == slen {
                    return s;
                }
                s[i] = s[i - 1];
            }
        }
        i += 1;
        k += 1;
    }
    s
}
 
fn possible_kolakoski(s: &Vec<i32>) -> bool {
    let slen = s.len();
    let mut rle = Vec::new();
    let mut prev = s[0];
    let mut count = 1;
    for i in 1..slen {
        if s[i] == prev {
            count += 1;
        } else {
            rle.push(count);
            count = 1;
            prev = s[i];
        }
    }
    // no point adding final 'count' to rle as we're not going to compare it anyway
    for i in 0..rle.len() {
        if rle[i]!= s[i] {
            return false;
        }
    }
    true
}
 
fn print_ints(ia: &Vec<i32>, suffix: &str) {
    print!("[");
    let alen = ia.len();
    for i in 0..alen {
        print!("{}", ia[i]);
        if i < alen - 1 {
            print!(", ");
        }
    }
    println!("]{}", suffix);
}
 
fn main() {
    let ias = vec![vec![1, 2], vec![2, 1], vec![1, 3, 1, 2], vec![1, 3, 2, 1]];
    let slens = vec![20, 20, 30, 30];
    for i in 0..ias.len() {
        let slen = slens[i];
        let kol = kolakoski(&ias[i], slen);
        println!("First {} members of the sequence generated by ", slen);
        print_ints(&ias[i], ":");
        print_ints(&kol, "");
        let p = possible_kolakoski(&kol);
        let poss = if p { "Yes" } else { "No" };
        println!("Possible Kolakoski sequence? {}", poss);
        println!("\n");
    }
}

// version 1.0.6
 
const SHADERS: &str = ".:!*oe&#%@";
const LIGHT: [f64; 3] = [30.0, 30.0, -50.0];
 
fn normalize(v: &mut [f64; 3]) {
    let len = (v[0] * v[0] + v[1] * v[1] + v[2] * v[2]).sqrt();
    v[0] /= len; v[1] /= len; v[2] /= len;
}
 
fn dot(x: &[f64; 3], y: &[f64; 3]) -> f64 {
    let d = x[0] * y[0] + x[1] * y[1] + x[2] * y[2];
    if d < 0.0 { -d } else { 0.0 }
}
 
fn draw_sphere(r: f64, k: f64, ambient: f64) {
    let mut vec = [0.0; 3];
    let mut intensity: usize;
    let mut b: f64;
    let mut x: f64;
    let mut y: f64;
    for i in (r.floor() as i32).. (r.ceil() as i32 + 1) {
        x = i as f64 + 0.5;
        for j in ((-2.0 * r).floor() as i32).. ((2.0 * r).ceil() as i32 + 1) {
            y = (j as f64) / 2.0 + 0.5;
            if x * x + y * y <= r * r {
                vec[0] = x;
                vec[1] = y;
                vec[2] = (r * r - x * x - y * y).sqrt();
                normalize(&mut vec);
                b = dot(&LIGHT, &vec).powf(k) + ambient;
                intensity = ((1.0 - b) * (SHADERS.len() as f64 - 1.0)) as usize;
                if intensity < 0 { intensity = 0; }
                if intensity >= SHADERS.len() - 1 { intensity = SHADERS.len() - 2; }
                print!("{}", SHADERS.chars().nth(intensity).unwrap());
            }
            else { print!(" "); }
        }
        println!();
    }
}
 
fn main() {
    normalize(&mut LIGHT);
    draw_sphere(20.0, 4.0, 0.1);
    draw_sphere(10.0, 2.0, 0.4);
}

fn f(n: i32) -> i32 {
    let mut result = 1;
    if n > 0 {
        result = n - m(f(n - 1));
    }
    result
}
 
fn m(n: i32) -> i32 {
    let mut result = 0;
    if n > 0 {
        result = n - f(m(n - 1));
    }
    result
}
 
fn main() {
    println!("{}", f(10));
    println!("{}", m(10));
}

