fn linear(x: &[i32]) -> String {
    x.iter()
       .enumerate()
       .filter(|&(_, v)| *v!= 0)
       .map(|(i, v)| {
            let sign = if *v == -1 { "-" } else { if *v == 1 { "" } else { v.to_string() + "*" } };
            sign + &format!("e({})", i + 1)
        })
       .collect::<Vec<_>>()
       .join(" + ")
       .replace(" + -", " - ")
}
 
