use std::sync::Arc;
use std::sync::Mutex;
use std::thread;
use std::time::Duration;
 
fn worker(sem: Arc<Mutex<i32>>, id: i32) {
    let mut sem = sem.lock().unwrap();
    println!("Thread {} has a semaphore & is now working.", id);
    thread::sleep(Duration::from_millis(2000));
    println!("#{} done.", id);
}
 
fn main() {
    let semaphore = Arc::new(Mutex::new(0));
    let mut handles = vec![];
 
    println!("You have {} processors availiabe", num_cpus::get());
    println!("This program will use {} semaphores.\n", num_cpus::get() * 2);
 
    for i in 0..num_cpus::get() * 3 {
        let sem = semaphore.clone();
        let handle = thread::spawn(move || {
            worker(sem, i);
        });
        handles.push(handle);
    }
 
    for handle in handles {
        handle.join().unwrap();
    }
}

use std::collections::HashMap;
use std::io;
use std::io::prelude::*;
use std::str::FromStr;
 
#[derive(Debug)]
struct Employee {
    name: String,
    id: String,
    salary: u32,
    department: String,
}
 
fn main() {
    let data = get_data();
    let employees = parse_data(&data);
    let groups = group_by_department(&employees);
    show_top_salaries_per_group(&groups, 3);
}
 
fn get_data() -> String {
    let mut data = String::new();
    io::stdin().read_to_string(&mut data).unwrap();
    data
}
 
fn parse_data(data: &str) -> Vec<Employee> {
    let mut employees = Vec::new();
    for line in data.lines().skip(1) {
        let mut fields = line.split(',');
        let name = fields.next().unwrap().to_string();
        let id = fields.next().unwrap().to_string();
        let salary = u32::from_str(fields.next().unwrap()).unwrap();
        let department = fields.next().unwrap().to_string();
        employees.push(Employee {
            name: name,
            id: id,
            salary: salary,
            department: department,
        });
    }
    employees
}
 
fn group_by_department(employees: &Vec<Employee>) -> HashMap<String, Vec<Employee>> {
    let mut groups = HashMap::new();
    for emp in employees {
        let dept = emp.department.clone();
        let mut group = groups.entry(dept).or_insert(Vec::new());
        group.push(emp.clone());
    }
    groups
}
 
fn show_top_salaries_per_group(groups: &HashMap<String, Vec<Employee>>, n: usize) {
    for (dept, emps) in groups {
        println!("{}", dept);
        let mut top_emps = emps.clone();
        top_emps.sort_by(|a, b| b.salary.cmp(&a.salary));
        for emp in top_emps.iter().take(n) {
            println!("    {:<16} {:<6} {:<7}", emp.name, emp.id, emp.salary);
        }
        println!("");
    }
}

use image::{ImageBuffer, Rgba};
use std::fs::File;
use std::io::BufReader;
 
fn main() {
    // Open the input file.
    let infile = File::open("in.png").unwrap();
    let infile = BufReader::new(infile);
 
    // Decode the input file.
    let img = image::load(infile, image::ImageFormat::PNG).unwrap().to_rgba();
 
    // Create a new image to hold the output.
    let (width, height) = img.dimensions();
    let mut outimg = ImageBuffer::new(width, height);
 
    // Draw the input image to the output.
    for (x, y, pixel) in img.enumerate_pixels() {
        outimg.put_pixel(x, y, *pixel);
    }
 
    // Draw a red rectangle on the output.
    let red = Rgba([255, 0, 0, 255]);
    for x in 100..200 {
        for y in 100..200 {
            outimg.put_pixel(x, y, red);
        }
    }
 
    // Open the output file.
    let mut outfile = File::create("out.png").unwrap();
 
    // Encode the output file.
    outimg.save(&mut outfile, image::ImageFormat::PNG).unwrap();
}

