use std::env;
use std::fs::File;
use std::io::prelude::*;
use std::io::BufReader;
use std::process;

struct Rule {
    pattern: String,
    replacement: String,
    terminal: bool,
}

fn is_whitespace(c: char) -> bool {
    c =='' || c == '\t'
}

fn read_rules(rulefile: &mut BufReader<File>) -> Vec<Rule> {
    let mut rules: Vec<Rule> = Vec::new();
    let mut line = String::new();
    while let Ok(_) = rulefile.read_line(&mut line) {
        let mut pos: usize;

        // remove comments
        pos = line.find('#');
        if pos!= None {
            line.truncate(pos.unwrap());
        }

        // ignore lines consisting only of whitespace
        if line.trim().is_empty() {
            continue;
        }

        // find "->" surrounded by whitespace
        pos = line.find("->");
        while pos!= None && (pos == 0 ||!is_whitespace(line.chars().nth(pos.unwrap() - 1).unwrap())) {
            pos = line.find("->");
        }

        if pos == None || line.len() < pos.unwrap() + 3 ||!is_whitespace(line.chars().nth(pos.unwrap() + 2).unwrap()) {
            println!("invalid rule: {}", line);
            process::exit(1);
        }

        let pattern = line.split_at(pos.unwrap() - 1).0.to_string();
        let replacement = line.split_at(pos.unwrap() + 3).1.to_string();

        // remove additional separating whitespace
        let pattern = pattern.trim().to_string();
        let replacement = replacement.trim().to_string();

        // test for terminal rule
        let terminal =!replacement.is_empty() && replacement.chars().nth(0).unwrap() == '.';
        let replacement = if terminal {
            replacement.split_at(1).1.to_string()
        } else {
            replacement
        };

        rules.push(Rule {
            pattern: pattern,
            replacement: replacement,
            terminal: terminal,
        });
    }

    rules
}

fn markov(rules: &Vec<Rule>, input: &str) -> String {
    let mut output = input.to_string();
    let mut iter = rules.iter();

    // Loop through each rule, transforming our current version
    // with each rule.
    while let Some(rule) = iter.next() {
        let pos = output.find(&rule.pattern);
        if pos!= None {
            output.replace_range(pos.unwrap()..pos.unwrap() + rule.pattern.len(), &rule.replacement);
            if rule.terminal {
                break;
            }
            iter = rules.iter();
        }
    }

    output
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len()!= 3 {
        println!("usage:\n {} rulefile text\n", args[0]);
        process::exit(1);
    }

    let mut rulefile = BufReader::new(File::open(&args[1]).unwrap());
    let rules = read_rules(&mut rulefile);

    let input = &args[2];
    let output = markov(&rules, input);

    println!("{}", output);
}

// version 1.1.0
 
fn circle_sort<T: PartialOrd>(array: &mut [T], lo: usize, hi: usize, n_swaps: usize) -> usize {
    if lo == hi {
        return n_swaps;
    }
 
    fn swap<T>(array: &mut [T], i: usize, j: usize) {
        let temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
 
    let mut high = hi;
    let mut low = lo;
    let mid = (hi - lo) / 2;
    let mut swaps = n_swaps;
    while low < high {
        if array[low] > array[high] {
            swap(array, low, high);
            swaps += 1;
        }
        low += 1;
        high -= 1;
    }
    if low == high {
        if array[low] > array[high + 1] {
            swap(array, low, high + 1);
            swaps += 1;
        }
    }
    swaps = circle_sort(array, lo, lo + mid, swaps);
    swaps = circle_sort(array, lo + mid + 1, hi, swaps);
    swaps
}
 
fn main() {
    let mut array = [6, 7, 8, 9, 2, 5, 3, 4, 1];
    println!("Original: {:?}", array);
    while circle_sort(&mut array, 0, array.len() - 1, 0)!= 0 {} // empty statement
    println!("Sorted  : {:?}", array);
    println!();
    let mut array2 = ["the", "quick", "brown", "fox", "jumps", "over", "the", "lazy", "dog"];
    println!("Original: {:?}", array2);
    while circle_sort(&mut array2, 0, array2.len() - 1, 0)!= 0 {}
    println!("Sorted  : {:?}", array2);
}

fn prime_sieve(limit: u64) -> Vec<bool> {
    let mut sieve = vec![true; limit as usize];
    if limit > 0 {
        sieve[0] = false;
    }
    if limit > 1 {
        sieve[1] = false;
    }
    for i in (4..limit).step_by(2) {
        sieve[i as usize] = false;
    }
    for p in (3..limit).step_by(2) {
        let q = p * p;
        if q >= limit {
            break;
        }
        if sieve[p as usize] {
            let mut inc = 2 * p;
            for q in (q..limit).step_by(inc as usize) {
                sieve[q as usize] = false;
            }
        }
    }
    sieve
}
 
fn modpow(base: u64, exp: u64, modulus: u64) -> u64 {
    if modulus == 1 {
        return 0;
    }
    let mut result = 1;
    let mut base = base % modulus;
    for exp in (0..exp).rev() {
        if (exp & 1) == 1 {
            result = (result * base) % modulus;
        }
        base = (base * base) % modulus;
    }
    result
}
 
fn wieferich_primes(limit: u64) -> Vec<u64> {
    let sieve = prime_sieve(limit);
    let mut result = Vec::new();
    for p in 2..limit {
        if sieve[p as usize] && modpow(2, p - 1, p * p) == 1 {
            result.push(p);
        }
    }
    result
}
 
