fn create_xml(character_remarks: &HashMap<&str, &str>) -> String {
    let mut xml = String::new();
    xml.push_str("<CharacterRemarks>");
    for (key, value) in character_remarks {
        xml.push_str("<Character Name=\"");
        xml.push_str(key);
        xml.push_str("\">");
        xml.push_str(value);
        xml.push_str("</Character>");
    }
    xml.push_str("</CharacterRemarks>");
    xml
}
 
