use std::collections::BTreeMap;
 
fn main() {
    let values = vec![4, 51, 1, -3, 3, 6, 8, 26, 2, 4];
    let (max, min) = min_max_num(&values);
 
    println!("Min: {}\nMax: {}", min, max);
}
 
fn min_max_num(nums: &Vec<i32>) -> (i32, i32) {
    let mut sorted_nums = BTreeMap::new();
    for num in nums {
        sorted_nums.insert(num, num);
    }
 
    let min = sorted_nums.first().unwrap().1;
    let max = sorted_nums.last().unwrap().1;
 
    (max, min)
}

use std::collections::VecDeque;

fn combinations(m: usize, n: usize) -> Vec<Vec<usize>> {
    let mut result = vec![0; m];
    let mut stack = VecDeque::new();
    stack.push_back(0);

    let mut combinations = vec![];

    while let Some(value) = stack.pop_back() {
        let mut index = stack.len();

        while value < n {
            result[index] = value + 1;
            stack.push_back(value + 1);
            index += 1;

            if index == m {
                combinations.push(result.clone());
                break;
            }
        }
    }

    combinations
}

fn main() {
    for c in combinations(3, 5) {
        println!("{:?}", c);
    }
}

