use std::collections::LinkedList;
use std::string::String;
 
fn encode(msg: &str, sym_table: &str) -> LinkedList<usize> {
	let mut output = LinkedList::new();
	let mut s = sym_table.to_string();
	for c in msg.chars() {
		let idx = s.find(c).unwrap();
		output.push_back(idx);
		s.remove(idx);
		s.insert(0, c);
	}
	output
}
 
fn decode(idxs: &LinkedList<usize>, sym_table: &str) -> String {
	let mut output = String::new();
	let mut s = sym_table.to_string();
	for idx in idxs {
		let c = s.chars().nth(*idx).unwrap();
		output.push(c);
		s.remove(*idx);
		s.insert(0, c);
	}
	output
}
 
fn test(to_encode: &str, sym_table: &str) {
	let encoded = encode(to_encode, sym_table);
	println!("{}: {:?}", to_encode, encoded);
	let decoded = decode(&encoded, sym_table);
	println!("{} decoded to {}", to_encode, decoded);
}
 
fn main() {
	let sym_table = "abcdefghijklmnopqrstuvwxyz";
	test("broood", sym_table);
	test("bananaaa", sym_table);
	test("hiphophiphop", sym_table);
}

fn main() {
    let mut d: i64;
    let mut n: i64;
    let mut o: i64;
    let mut u: i64;
    let mut u89: i64;
    n = 1;
    u89 = 0;
    while n < 100000000 {
        o = n;
        loop {
            u = 0;
            loop {
                d = o % 10;
                o = (o - d) / 10;
                u += d * d;
                if o == 0 {
                    break;
                }
            }
            if u == 89 || u == 1 {
                if u == 89 {
                    u89 += 1;
                }
                break;
            }
            o = u;
        }
        n += 1;
    }
    println!("{}", u89);
}

