use rand::Rng;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;
 
fn main() {
    let mut n_workers = String::new();
    let mut n_tasks = String::new();
    println!("Enter number of workers to use: ");
    std::io::stdin().read_line(&mut n_workers).unwrap();
    println!("Enter number of tasks to complete: ");
    std::io::stdin().read_line(&mut n_tasks).unwrap();
    let n_workers: u32 = n_workers.trim().parse().unwrap();
    let n_tasks: u32 = n_tasks.trim().parse().unwrap();
    run_tasks(n_workers, n_tasks);
}
 
fn run_tasks(n_workers: u32, n_tasks: u32) {
    for i in 1..=n_tasks {
        println!("\nStarting task number {}.", i);
        let mut workers = Vec::new();
        let n_finished = Arc::new(Mutex::new(0));
        for j in 1..=n_workers {
            let n_finished = Arc::clone(&n_finished);
            workers.push(thread::spawn(move || {
                let work_time = rand::thread_rng().gen_range(100, 1000);
                println!("Worker {} will work for {} msec.", j, work_time);
                thread::sleep(Duration::from_millis(work_time));
                let mut n_finished = n_finished.lock().unwrap();
                *n_finished += 1;
                println!("Worker {} is ready", j);
            }));
        }
        for worker in workers {
            worker.join().unwrap();
        }
        check_point(n_workers, n_finished);
    }
}
 
fn check_point(n_workers: u32, n_finished: Arc<Mutex<u32>>) {
    while *n_finished.lock().unwrap()!= n_workers {
        thread::sleep(Duration::from_millis(10));
    }
    *n_finished.lock().unwrap() = 0;
}

