use std::mem;
 
fn egyptian_division(dividend: u64, divisor: u64, remainder: &mut u64) -> u64 {
	// remainder is an out parameter, pass NULL if you do not need the remainder
 
	let mut powers: [u64; 64] = unsafe { mem::uninitialized() };
	let mut doublings: [u64; 64] = unsafe { mem::uninitialized() };
 
	let mut i: i32;
 
	for i in 0..64 {
		powers[i as usize] = 1 << i;
		doublings[i as usize] = divisor << i;
		if doublings[i as usize] > dividend {
			break;
		}
	}
 
	let mut answer: u64 = 0;
	let mut accumulator: u64 = 0;
 
	for i in (0..i).rev() {
		// If the current value of the accumulator added to the
		// doublings cell would be less than or equal to the
		// dividend then add it to the accumulator
		if accumulator + doublings[i as usize] <= dividend {
			accumulator += doublings[i as usize];
			answer += powers[i as usize];
		}
	}
 
	if remainder.is_some() {
		*remainder = Some(dividend - accumulator);
	}
	return answer;
}
 
fn go(a: u64, b: u64) {
	let x = egyptian_division(a, b, &mut None);
	println!("{} / {} = {} remainder {}", a, b, x, a - b * x);
	assert!(a == b * x + (a - b * x));
}
 
