fn build_oms(s: usize) -> (Vec<Vec<usize>>, usize) {
    let mut q = vec![vec![0; s]; s];
    let mut p = 1;
    let mut i = s / 2;
    let mut j = 0;
    while p <= (s * s) {
        q[i][j] = p;
        let ti = i + 1;
        let ti = if ti >= s { 0 } else { ti };
        let tj = j - 1;
        let tj = if tj < 0 { s - 1 } else { tj };
        if q[ti][tj]!= 0 {
            let ti = i;
            let tj = j + 1;
            i = ti;
            j = tj;
        } else {
            i = ti;
            j = tj;
        }
        p += 1;
    }
    (q, s)
}
 
fn build_sems(s: usize) -> (Vec<Vec<usize>>, usize) {
    let mut s = s;
    if s % 2 == 0 {
        s += 1;
    }
    while s % 4 == 0 {
        s += 2;
    }
    let mut q = vec![vec![0; s]; s];
    let z = s / 2;
    let b = z * z;
    let c = 2 * b;
    let d = 3 * b;
    let o = build_oms(z);
    for j in 0..z {
        for i in 0..z {
            let a = o.0[i][j];
            q[i][j] = a;
            q[i + z][j + z] = a + b;
            q[i + z][j] = a + c;
            q[i][j + z] = a + d;
        }
    }
    let lc = z / 2;
    let rc = lc;
    for j in 0..z {
        for i in 0..s {
            if i < lc || i > s - rc || (i == lc && j == lc) {
                if!(i == 0 && j == lc) {
                    let t = q[i][j];
                    q[i][j] = q[i][j + z];
                    q[i][j + z] = t;
                }
            }
        }
    }
    (q, s)
}
 
fn format_sqr(s: &str, l: usize) -> String {
    let mut s = s.to_string();
    for _ in 0..(l - s.len()) {
        s = "0".to_string() + &s;
    }
    s + " "
}
 
fn display(q: (Vec<Vec<usize>>, usize)) {
    let s = q.1;
    println!(" - {} x {}", s, s);
    let k = 1 + (s * s as usize).log10() as usize;
    for j in 0..s {
        for i in 0..s {
            print!("{}", format_sqr(&q.0[i][j].to_string(), k));
        }
        println!();
    }
    println!("Magic sum: {}\n", s * ((s * s) + 1) / 2);
}
 
fn main() {
    println!("Singly Even Magic Square");
    display(build_sems(6));
}

