use std::fmt;
 
fn replace_first(s: &mut String, target: &str, replace: &str) -> &str {
    let pos = s.find(target);
    if pos.is_none() {
        return s;
    }
    let pos = pos.unwrap();
    s.replace_range(pos..pos + target.len(), replace);
    s
}
 
fn main() {
    // string creation
    let mut x = String::from("hello world");
 
    // reassign string (no garbage collection)
    x = String::new();
 
    // string assignment with a null byte
    x = String::from("ab\0");
    println!("{}", x);
    println!("{}", x.len());
 
    // string comparison
    if x == "hello" {
        println!("equal");
    } else {
        println!("not equal");
    }
    if x < "bc" {
        println!("x is lexigraphically less than 'bc'");
    }
 
    // string cloning
    let y = x.clone();
    println!("{}", x == y);
    println!("{}", &x == &y);
 
    // check if empty
    let empty = String::new();
    if empty.is_empty() {
        println!("String is empty");
    }
 
    // append a byte
    x = String::from("helloworld");
    x.push('S' as u8);
    println!("{}", x);
 
    // substring
    let slice = &x[5..10];
    println!("{}", slice);
 
    // replace bytes
    let greeting = replace_first(&mut x, "worldS", "");
    println!("{}", greeting);
 
    // join strings
    let join = format!("{} {}", greeting, slice);
    println!("{}", join);
}

