struct Segment {
    p1: PointF,
    p2: PointF,
}

impl Segment {
    pub fn new(p1: PointF, p2: PointF) -> Segment {
        Segment { p1, p2 }
    }

    pub fn length(&self) -> f32 {
        (self.p1.x - self.p2.x) * (self.p1.x - self.p2.x)
            + (self.p1.y - self.p2.y) * (self.p1.y - self.p2.y)
    }

    pub fn length_squared(&self) -> f32 {
        (self.p1.x - self.p2.x) * (self.p1.x - self.p2.x)
            + (self.p1.y - self.p2.y) * (self.p1.y - self.p2.y)
    }
}

fn halve( n : i32 ) -> i32 {  n / 2  }
fn double( n : i32 ) -> i32 {  2 * n  }
fn isEven( n : i32 ) -> bool {  n % 2 == 0  }
 
fn mult( a : i32, b : i32 ) -> i32 {
	let mut sum = 0;
	let mut a = vec![a];
	let mut b = vec![b];
 
	while a[0]!= 1 {
		a.insert( 0, halve( a[0] ) );
		b.insert( 0, double( b[0] ) );
	}
 
	for i in (0..a.len()-1).rev() {
		if!isEven( a[i] ) {
			sum += b[i];
		}
	}
	return sum + b[0];
}
