use std::env;
use std::thread;
use std::time::Duration;
use rand::Rng;
 
fn show(univ: &mut [[u8; 100]; 100], w: usize, h: usize) {
	print!("\x1B[H");
	for y in 0..h {
		for x in 0..w {
			if univ[y][x] == 1 {
				print!("\x1B[07m  \x1B[m");
			} else {
				print!("  ");
			}
		}
		print!("\x1B[E");
	}
}
 
fn evolve(univ: &mut [[u8; 100]; 100], w: usize, h: usize) {
	let mut new = [[0; 100]; 100];
	for y in 0..h {
		for x in 0..w {
			let mut n = 0;
			for y1 in y - 1..y + 2 {
				for x1 in x - 1..x + 2 {
					if univ[(y1 + h) % h][(x1 + w) % w] == 1 {
						n += 1;
					}
				}
			}
			if univ[y][x] == 1 {
				n -= 1;
			}
			new[y][x] = if n == 3 || (n == 2 && univ[y][x] == 1) { 1 } else { 0 };
		}
	}
	for y in 0..h {
		for x in 0..w {
			univ[y][x] = new[y][x];
		}
	}
}
 
fn game(w: usize, h: usize) {
	let mut univ = [[0; 100]; 100];
	for y in 0..h {
		for x in 0..w {
			if rand::thread_rng().gen_range(0, 10) == 0 {
				univ[y][x] = 1;
			}
		}
	}
	loop {
		show(&mut univ, w, h);
		evolve(&mut univ, w, h);
		thread::sleep(Duration::from_millis(200));
	}
}
 
fn main() {
	let args: Vec<String> = env::args().collect();
	let w = if args.len() > 1 {
		args[1].parse::<usize>().unwrap()
	} else {
		30
	};
	let h = if args.len() > 2 {
		args[2].parse::<usize>().unwrap()
	} else {
		30
	};
	game(w, h);
}

