use std::collections::HashMap;
 
fn find_abbreviations_length(command_table_text: &str) -> HashMap<&str, usize> {
    let mut command_table = HashMap::new();
    for word in command_table_text.split_whitespace() {
        let abbr_len = word.chars().filter(|c| c.is_uppercase()).count();
        let abbr_len = if abbr_len == 0 { word.len() } else { abbr_len };
        command_table.insert(word, abbr_len);
    }
    command_table
}
 
fn find_abbreviations(command_table: &HashMap<&str, usize>) -> HashMap<&str, &str> {
    let mut abbreviations = HashMap::new();
    for (command, min_abbr_len) in command_table {
        for l in min_abbr_len..command.len()+1 {
            let abbr = &command[..l].to_lowercase();
            abbreviations.insert(abbr, command.to_uppercase());
        }
    }
    abbreviations
}
 
fn parse_user_string(user_string: &str, abbreviations: &HashMap<&str, &str>) -> String {
    let user_words = user_string.split_whitespace().collect::<Vec<_>>();
    let commands = user_words.iter().map(|user_word| {
        abbreviations.get(user_word).unwrap_or(&"*error*")
    }).collect::<Vec<_>>();
    commands.join(" ")
}
 
