fn check_word(blocks: &str, word: &str) -> bool {
    // Makes sure that word only contains letters.
    if!word.chars().all(|c| c.is_ascii_alphabetic()) {
        return false;
    }
    // Loops through each character to see if a block exists.
    for c in word.chars() {
        // Stores the length of the blocks to determine if a block was removed.
        let length = blocks.len();
        // The regexp gets constructed by eval to allow more browsers to use the function.
        let reg = format!("([a-z]{}|{}[a-z])", c, c);
        // Removes all occurrences of the match.
        let blocks = blocks.replace(reg, "");
        // If the length did not change then a block did not exist.
        if blocks.len() == length {
            return false;
        }
    }
    // If every character has passed then return true.
    true
}
 
fn main() {
    let blocks = "BO XK DQ CP NA GT RE TG QD FS JW HU VI AN OB ER FS LY PC ZM";
    let words = [
        "A",
        "BARK",
        "BOOK",
        "TREAT",
        "COMMON",
        "SQUAD",
        "CONFUSE",
    ];
    for word in &words {
        println!("{}: {}", word, check_word(blocks, word));
    }
}

fn chain_insert(lst: &mut List, at: &str, item: &str) {
    while let Some(ref mut pair) = *lst {
        if pair.0 == at {
            pair.1 = Some(Box::new((item.to_string(), pair.1)));
            return;
        }
        lst = &mut pair.1;
    }
    panic!("{} not found", at);
}
 
fn main() {
    let mut chain = Box::new(("A".to_string(), Some(Box::new(("B".to_string(), None)))));
    chain_insert(&mut chain, "A", "C");
    println!("{:?}", chain);
}

use std::thread;
use std::sync::mpsc::channel;
use std::sync::Arc;
