fn sleep_sort_and_print(nums: Vec<i32>) {
    let (tx, rx) = channel();
    let mut threads = Vec::new();
    let done_signal = Arc::new(Mutex::new(0));
    for num in nums {
        let tx = tx.clone();
        let done_signal = done_signal.clone();
        threads.push(thread::spawn(move || {
            let mut done_signal = done_signal.lock().unwrap();
            *done_signal += 1;
            drop(done_signal);
            rx.recv().unwrap();
            thread::sleep(Duration::from_millis(num as u64 * 1000));
            tx.send(num).unwrap();
        }));
    }
    for _ in 0..nums.len() {
        tx.send(()).unwrap();
    }
    for thread in threads {
        thread.join().unwrap();
    }
}

fn main() {
    let args: Vec<i32> = std::env::args()
       .skip(1)
       .map(|s| s.parse().unwrap())
       .collect();
    sleep_sort_and_print(args);
}

