use std::fs::OpenOptions;
use std::io::Result;
use std::io::Write;
 
fn truncate_file(file_name: &str, new_size: u64) -> Result<()> {
    let mut file = OpenOptions::new()
       .write(true)
       .open(file_name)?;
    if new_size >= file.metadata()?.len() {
        println!("Requested file size isn't less than existing size");
    } else {
        file.set_len(new_size)?;
    }
    Ok(())
}
 
