use std::collections::HashMap;

fn main() {
    let table_a = vec![
        (27, "Jonah"),
        (18, "Alan"),
        (28, "Glory"),
        (18, "Popeye"),
        (28, "Alan"),
    ];
    let table_b = vec![
        ("Jonah", "Whales"),
        ("Jonah", "Spiders"),
        ("Alan", "Ghosts"),
        ("Alan", "Zombies"),
        ("Glory", "Buffy"),
    ];
    // hash phase
    let mut h = HashMap::new();
    for (i, r) in table_a.iter().enumerate() {
        h.entry(r.1).or_insert(vec![]).push(i);
    }
    // join phase
    for x in table_b.iter() {
        if let Some(a) = h.get(x.0) {
            for i in a.iter() {
                println!("{:?} {:?}", table_a[*i], x);
            }
        }
    }
}

