use image::{GenericImageView, ImageBuffer};
use image::imageops::resize;
use image::imageops::FilterType;
use image::RgbImage;
 
fn get_difference_percent(img1: &RgbImage, img2: &RgbImage) -> f64 {
    let width = img1.width();
    let height = img1.height();
    let width2 = img2.width();
    let height2 = img2.height();
    if width!= width2 || height!= height2 {
        let f = format!("({},{}) vs. ({},{})", width, height, width2, height2);
        panic!("Images must have the same dimensions: {}", f);
    }
    let mut diff = 0;
    for y in 0..height {
        for x in 0..width {
            diff += pixel_diff(img1.get_pixel(x, y), img2.get_pixel(x, y));
        }
    }
    let max_diff = 3 * 255 * width * height;
    return 100.0 * diff as f64 / max_diff as f64;
}
 
fn pixel_diff(rgb1: &Rgb<u8>, rgb2: &Rgb<u8>) -> u32 {
    let r1 = rgb1[0];
    let g1 = rgb1[1];
    let b1 = rgb1[2];
    let r2 = rgb2[0];
    let g2 = rgb2[1];
    let b2 = rgb2[2];
    return (r1 as i32 - r2 as i32).abs() as u32
        + (g1 as i32 - g2 as i32).abs() as u32
        + (b1 as i32 - b2 as i32).abs() as u32;
}
 
fn main() -> Result<(), Error> {
    let img1 = image::open("Lenna50.jpg")?.resize(50, 50, FilterType::Nearest);
    let img2 = image::open("Lenna100.jpg")?.resize(50, 50, FilterType::Nearest);
    let p = get_difference_percent(&img1, &img2);
    println!("The percentage difference is {:.6}", p);
    Ok(())
}

