fn run(n: i32) -> Vec<Vec<i32>> {
    // Here comes the list comprehension bit
    // input stream - bit clunky
    (1..n)
       .flat_map(|x| (x..n).flat_map(move |y| (y..n).map(move |z| vec![x, y, z])))
        // predicate
       .filter(|a| a[0] * a[0] + a[1] * a[1] == a[2] * a[2])
        // output expression
       .collect()
}

use image::{ImageBuffer, Rgb, RgbImage};
use rand::Rng;
use std::fs::File;
