// The compiler can automatically implement Clone on structs (assuming all members have implemented Clone).
#[derive(Clone)]
struct Tree<T> {
    left: Leaf<T>,
    data: T,
    right: Leaf<T>,
}
 
type Leaf<T> = Option<Box<Tree<T>>>;
 
impl<T> Tree<T> {
    fn root(data: T) -> Self {
        Self { left: None, data, right: None }
    }
 
    fn leaf(d: T) -> Leaf<T> {
        Some(Box::new(Self::root(d)))
    }
}
 
fn main() {
    let mut tree = Tree::root([4, 5, 6]);
    tree.right = Tree::leaf([1, 2, 3]);
    tree.left = Tree::leaf([7, 8, 9]);
 
    let newtree = tree.clone();
}

// main.rs
// References:
// https://en.wikipedia.org/wiki/Full_reptend_prime
// https://en.wikipedia.org/wiki/Primitive_root_modulo_n#Finding_primitive_roots
 
mod bit_array;
mod prime_sieve;
 
use prime_sieve::PrimeSieve;
 
fn modpow(mut base: usize, mut exp: usize, n: usize) -> usize {
    if n == 1 {
        return 0;
    }
    let mut result = 1;
    base %= n;
    while exp > 0 {
        if (exp & 1) == 1 {
            result = (result * base) % n;
        }
        base = (base * base) % n;
        exp >>= 1;
    }
    result
}
 
fn is_long_prime(sieve: &PrimeSieve, prime: usize) -> bool {
    if !sieve.is_prime(prime) {
        return false;
    }
    if 10 % prime == 0 {
        return false;
    }
    let n = prime - 1;
    let mut m = n;
    let mut p = 2;
    while p * p <= n {
        if sieve.is_prime(p) && m % p == 0 {
            if modpow(10, n / p, prime) == 1 {
                return false;
            }
            while m % p == 0 {
                m /= p;
            }
        }
        p += 1;
    }
    if m == 1 {
        return true;
    }
    modpow(10, n / m, prime) != 1
}
 
fn long_primes(limit1: usize, limit2: usize) {
    let sieve = PrimeSieve::new(limit2);
    let mut count = 0;
    let mut limit = limit1;
    let mut prime = 3;
    while prime < limit2 {
        if is_long_prime(&sieve, prime) {
            if prime < limit1 {
                print!("{} ", prime);
            }
            if prime > limit {
                print!("\nNumber of long primes up to {}: {}", limit, count);
                limit *= 2;
            }
            count += 1;
        }
        prime += 2;
    }
    println!("\nNumber of long primes up to {}: {}", limit, count);
}
 
fn main() {
    long_primes(500, 8192000);
}

// [dependencies]
// radix_fmt = "1.0"
 
fn digit_product(base: u32, mut n: u32) -> u32 {
    let mut product = 1;
    while n != 0 {
        product *= n % base;
        n /= base;
    }
    product
}
 
fn prime_factor_sum(mut n: u32) -> u32 {
    let mut sum = 0;
    while (n & 1) == 0 {
        sum += 2;
        n >>= 1;
    }
    let mut p = 3;
    while p * p <= n {
        while n % p == 0 {
            sum += p;
            n /= p;
        }
        p += 2;
    }
    if n > 1 {
        sum += n;
    }
    sum
}
 
fn is_prime(n: u32) -> bool {
    if n < 2 {
        return false;
    }
    if n % 2 == 0 {
        return n == 2;
    }
    if n % 3 == 0 {
        return n == 3;
    }
    let mut p = 5;
    while p * p <= n {
        if n % p == 0 {
            return false;
        }
        p += 2;
        if n % p == 0 {
            return false;
        }
        p += 4;
    }
    true
}
 
fn is_rhonda(base: u32, n: u32) -> bool {
    digit_product(base, n) == base * prime_factor_sum(n)
}
 
fn main() {
    let limit = 15;
    for base in 2..=36 {
        if is_prime(base) {
            continue;
        }
        println!("First {} Rhonda numbers to base {}:", limit, base);
        let numbers: Vec<u32> = (1..).filter(|x| is_rhonda(base, *x)).take(limit).collect();
        print!("In base 10:");
        for n in &numbers {
            print!(" {}", n);
        }
        print!("\nIn base {}:", base);
        for n in &numbers {
            print!(" {}", radix_fmt::radix(*n, base as u8));
        }
        print!("\n\n");
    }
}

#[cfg(unix)]
fn main() {
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::thread;
    use std::time::{Duration, Instant};
 
    use libc::{sighandler_t, SIGINT};
 
    // The time between ticks of our counter.
    let duration = Duration::from_secs(1) / 2;
 
    // "SIGINT received" global variable.
    static mut GOT_SIGINT: AtomicBool = AtomicBool::new(false);
 
    unsafe {
        // Initially, "SIGINT received" is false.
        GOT_SIGINT.store(false, Ordering::Release);
        // Interrupt handler that handles the SIGINT signal
        unsafe fn handle_sigint() {
            // It is dangerous to perform any system calls in interrupts, so just set the atomic
            // "SIGINT received" global to true when it arrives.
            GOT_SIGINT.store(true, Ordering::Release);
        }
        // Make handle_sigint the signal handler for SIGINT.
        libc::signal(SIGINT, handle_sigint as sighandler_t);
    }
 
    // Get the start time...
    let start = Instant::now();
 
    // Integer counter
    let mut i = 0u32;
 
    // Every `duration`...
    loop {
        thread::sleep(duration);
 
        // Break if SIGINT was handled
        if unsafe { GOT_SIGINT.load(Ordering::Acquire) } {
            break;
        }
 
        // Otherwise, increment and display the integer and continue the loop.
        i += 1;
        println!("{}", i);
    }
 
    // Get the elapsed time.
    let elapsed = start.elapsed();
 
    // Print the difference and exit
    println!("Program has run for {} seconds", elapsed.as_secs());
}
 
